    /// Derive an AXT policy snapshot, preferring explicit policy entries when present and
    /// otherwise projecting from the Space Directory + lane catalog.
    #[must_use]
    pub fn axt_policy_snapshot(&self) -> iroha_data_model::nexus::AxtPolicySnapshot {
        let view = self.view();
        StateReadOnly::axt_policy_snapshot(&view)
    }

    /// Install or update a dataspace AXT policy entry.
    pub fn set_axt_policy(&mut self, dsid: DataSpaceId, policy: AxtPolicyEntry) {
        let mut block = self.world.axt_policies.block();
        let mut tx = block.transaction();
        tx.insert(dsid, policy);
        tx.apply();
        block.commit();
    }

    /// Rebuild the committed AXT policy cache from Space Directory manifests and lane bindings.
    ///
    /// When the Space Directory is empty, existing explicit policies are preserved unless they
    /// target lanes that no longer exist in the current lane catalog.
    pub fn refresh_axt_policies_from_directory(&self) -> Option<AxtPolicySnapshot> {
        let view = self.view();
        let nexus = view.nexus.clone();
        let block_height = self.block_hashes.view().len() as u64;
        let valid_lanes = axt_cached_policy_retain_lane_ids_at_height(&nexus, block_height);
        let mut snapshot =
            crate::smartcontracts::ivm::host::CoreHost::derive_axt_policy_snapshot_from_directory(
                &view,
            );
        drop(view);
        let Some(snap) = snapshot.as_mut() else {
            let (has_directory_data, has_active_manifest) = {
                let manifests = self.world.space_directory_manifests.view();
                let bindings = self.world.uaid_dataspaces.view();
                let has_directory_data =
                    manifests.iter().next().is_some() || bindings.iter().next().is_some();
                let has_active_manifest = manifests
                    .iter()
                    .any(|(_, set)| set.iter().any(|(_, record)| record.is_active()));
                (has_directory_data, has_active_manifest)
            };
            if !has_directory_data || has_active_manifest {
                let mut block = self.world.axt_policies.block();
                let mut tx = block.transaction();
                let stale: Vec<_> = tx
                    .view()
                    .iter()
                    .filter(|(_, policy)| !valid_lanes.contains(&policy.target_lane))
                    .map(|(dsid, _)| *dsid)
                    .collect();
                if stale.is_empty() {
                    return None;
                }
                for dsid in stale {
                    tx.remove(dsid);
                }
                tx.apply();
                block.commit();
                return None;
            }
            let mut block = self.world.axt_policies.block();
            let mut tx = block.transaction();
            let stale: Vec<_> = tx.view().iter().map(|(dsid, _)| *dsid).collect();
            for dsid in stale {
                tx.remove(dsid);
            }
            tx.apply();
            block.commit();
            return None;
        };

        let mut block = self.world.axt_policies.block();
        let mut tx = block.transaction();
        let existing: BTreeMap<_, _> = tx
            .view()
            .iter()
            .map(|(dsid, policy)| (*dsid, *policy))
            .collect();

        for binding in &mut snap.entries {
            if let Some(prev) = existing.get(&binding.dsid) {
                if prev.manifest_root == binding.policy.manifest_root
                    && prev.target_lane == binding.policy.target_lane
                {
                    binding.policy.min_handle_era =
                        binding.policy.min_handle_era.max(prev.min_handle_era);
                    binding.policy.min_sub_nonce =
                        binding.policy.min_sub_nonce.max(prev.min_sub_nonce);
                }
            }
        }
        snap.version = AxtPolicySnapshot::compute_version(&snap.entries);

        let existing_keys: Vec<_> = tx.view().iter().map(|(dsid, _)| *dsid).collect();
        for dsid in existing_keys {
            tx.remove(dsid);
        }
        for binding in &snap.entries {
            tx.insert(binding.dsid, binding.policy);
        }
        tx.apply();
        block.commit();
        snapshot
    }

    /// Remove a dataspace AXT policy entry.
    pub fn remove_axt_policy(&mut self, dsid: &DataSpaceId) {
        let mut block = self.world.axt_policies.block();
        block.remove(*dsid);
        block.commit();
    }

    /// Update `current_slot` for all policy entries.
    pub fn update_axt_policy_slots(&mut self, current_slot: u64) {
        let mut block = self.world.axt_policies.block();
        let keys: Vec<DataSpaceId> = block.iter().map(|(dsid, _)| *dsid).collect();
        for dsid in keys {
            if let Some(policy) = block.get_mut(&dsid) {
                policy.current_slot = current_slot;
            }
        }
        block.commit();
    }

    /// Push a committed block hash when constructing scenarios in tests.
    ///
    /// The synthetic autoscale sample keeps the test state eligible for a
    /// canonical snapshot: production block commits always retain the same
    /// height/hash suffix, so a hash-only fixture must do so as well.
    #[cfg(any(test, feature = "iroha-core-tests"))]
    pub fn push_block_hash_for_testing(&mut self, block_hash: HashOf<BlockHeader>) {
        let block_height = u64::try_from(self.block_hashes.committed_height())
            .unwrap_or(u64::MAX)
            .saturating_add(1);
        let mut block = self.block_hashes.block();
        block.push(block_hash);
        block.commit();

        let history_cap = autoscale_sample_history_cap(&self.nexus.read().autoscale);
        let mut history = self.autoscale_sample_history.write();
        let baseline_timestamp_ms = block_height.saturating_mul(100).max(1);
        let creation_time_ms = history.back().map_or(baseline_timestamp_ms, |previous| {
            previous
                .creation_time_ms
                .saturating_add(1)
                .max(baseline_timestamp_ms)
        });
        append_autoscale_sample_record(
            &mut history,
            AutoscaleSampleRecord {
                block_height,
                block_hash,
                creation_time_ms,
                work_count: 0,
            },
            history_cap,
        );
    }

    #[cfg(any(test, feature = "iroha-core-tests"))]
    /// Latest committed block height recorded in the transactions storage (0 when empty).
    pub fn transactions_latest_height_for_testing(&self) -> usize {
        self.transactions.latest_height()
    }

    #[cfg(any(test, feature = "app_api"))]
    /// Prune the AXT replay ledger using the provided slot and retention window (test helper).
    pub fn prune_axt_replay_ledger_for_tests(&mut self, current_slot: u64, retention_slots: u64) {
        let mut block = self.world.axt_replay_ledger.block();
        let expired: Vec<_> = block
            .iter()
            .filter(|(_, record)| record.is_expired(current_slot, retention_slots))
            .map(|(key, _)| *key)
            .collect();
        for key in expired {
            block.remove(key);
        }
        block.commit();
    }

    #[cfg(any(test, feature = "app_api"))]
    /// Insert an AXT replay record (test helper).
    pub fn insert_axt_replay_entry_for_tests(
        &mut self,
        key: AxtHandleReplayKey,
        record: AxtReplayRecord,
    ) {
        let mut block = self.world.axt_replay_ledger.block();
        block.insert(key, record);
        block.commit();
    }

