    #[test]
    fn escrow_records_roundtrip_through_state_json() {
        let mut world = World::default();
        let seller = AccountId::new(crate::state::checked_keypair().public_key().clone());
        let buyer = AccountId::new(crate::state::checked_keypair().public_key().clone());
        let asset_definition = AssetDefinitionId::new(
            DomainId::try_new("escrowsnapshot", "universal").expect("domain id"),
            "xor".parse().expect("asset name"),
        );

        let public_id = iroha_data_model::escrow::EscrowId::new(Hash::new("public-escrow"));
        let public_record = iroha_data_model::escrow::AssetEscrowRecord {
            id: public_id,
            seller: seller.clone(),
            buyer: Some(buyer.clone()),
            asset_definition: asset_definition.clone(),
            amount: Quantity::from(42_u32),
            custody: seller.clone(),
            status: iroha_data_model::escrow::AssetEscrowStatus::PaymentSent,
            kind: iroha_data_model::escrow::AssetEscrowKind::Marketplace,
            remaining_amount: Quantity::from(42_u32),
            release_authority: None,
            expires_at_ms: None,
            evidence_hashes: vec![Hash::new("public-evidence")],
            conditions: Vec::new(),
            created_at_ms: 1,
            accepted_at_ms: Some(2),
            payment_sent_at_ms: Some(3),
            disputed_at_ms: None,
            closed_at_ms: None,
            resolution: None,
        };

        let anonymous_id = iroha_data_model::escrow::EscrowId::new(Hash::new("anonymous-escrow"));
        let proof_record = iroha_data_model::escrow::AnonymousAssetEscrowProofRecord {
            nullifiers: vec![[0x11; 32]],
            output_commitments: vec![[0x22; 32]],
            proof_hash: [0x33; 32],
            envelope_hash: Some([0x44; 32]),
            root_hint: Some([0x55; 32]),
            recorded_at_ms: 4,
        };
        let anonymous_record = iroha_data_model::escrow::AnonymousAssetEscrowRecord {
            id: anonymous_id,
            seller: seller.clone(),
            buyer: Some(buyer),
            asset_definition,
            escrow_commitment: [0x22; 32],
            status: iroha_data_model::escrow::AssetEscrowStatus::Accepted,
            evidence_hashes: vec![Hash::new("anonymous-evidence")],
            opening: proof_record,
            release: None,
            cancellation: None,
            created_at_ms: 4,
            accepted_at_ms: Some(5),
            payment_sent_at_ms: None,
            disputed_at_ms: None,
            closed_at_ms: None,
            resolution: None,
        };

        world.asset_escrows.insert(public_id, public_record.clone());
        world
            .anonymous_asset_escrows
            .insert(anonymous_id, anonymous_record.clone());

        let state = State::new(
            world,
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        let json_value = norito::json::to_value(&state).expect("serialize state");
        let seed = deserialize::KuraSeed {
            kura: Kura::blank_kura_for_testing(),
            query_handle: LiveQueryStore::start_test(),
            #[cfg(feature = "telemetry")]
            telemetry: crate::telemetry::StateTelemetry::default(),
        };
        let restored = seed
            .into_state_from_json(json_value)
            .expect("deserialize state");
        let view = restored.world_view();

        assert_eq!(
            view.asset_escrows().get(&public_id).expect("public escrow"),
            &public_record
        );
        assert_eq!(
            view.anonymous_asset_escrows()
                .get(&anonymous_id)
                .expect("anonymous escrow"),
            &anonymous_record
        );

        let state_view = restored.view();
        let restored_public_ids = FindAssetEscrowsByStatus {
            status: iroha_data_model::escrow::AssetEscrowStatus::PaymentSent,
        }
        .execute(CompoundPredicate::PASS, &state_view)
        .expect("query restored public escrow status index")
        .map(|record| record.id)
        .collect::<Vec<_>>();
        assert_eq!(restored_public_ids, vec![public_id]);

        let restored_anonymous_ids = FindAnonymousAssetEscrowsByStatus {
            status: iroha_data_model::escrow::AssetEscrowStatus::Accepted,
        }
        .execute(CompoundPredicate::PASS, &state_view)
        .expect("query restored anonymous escrow status index")
        .map(|record| record.id)
        .collect::<Vec<_>>();
        assert_eq!(restored_anonymous_ids, vec![anonymous_id]);
    }

    #[test]
    fn public_lane_staking_roundtrip_through_state_json() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut world = World::default();
        let validator = ALICE_ID.clone();
        let staker = BOB_ID.clone();
        let mismatched_validator_keypair = crate::state::checked_keypair();
        let mismatched_validator =
            AccountId::new(mismatched_validator_keypair.public_key().clone());
        let mismatched_staker_keypair = crate::state::checked_keypair();
        let mismatched_staker = AccountId::new(mismatched_staker_keypair.public_key().clone());
        let mismatched_lane = LaneId::new(99);
        let stake_asset_definition = AssetDefinitionId::new(
            DomainId::try_new("wonderland", "universal").expect("stake asset domain"),
            "stake".parse().expect("stake asset name"),
        );
        let reward_asset = AssetId::new(stake_asset_definition, validator.clone());
        let request_id = Hash::new("unbond-request");

        world.public_lane_validators.insert(
            (LaneId::SINGLE, validator.clone()),
            PublicLaneValidatorRecord {
                lane_id: LaneId::SINGLE,
                validator: validator.clone(),
                peer_id: PeerId::from(validator.signatory().clone()),
                stake_account: validator.clone(),
                total_stake: iroha_primitives::numeric::Quantity::from(2_000_u32),
                self_stake: iroha_primitives::numeric::Quantity::from(1_000_u32),
                metadata: Metadata::default(),
                status: PublicLaneValidatorStatus::Active,
                activation_epoch: Some(0),
                activation_height: Some(1),
                last_reward_epoch: Some(7),
            },
        );
        world.public_lane_validators.insert(
            (LaneId::SINGLE, mismatched_validator.clone()),
            PublicLaneValidatorRecord {
                lane_id: mismatched_lane,
                validator: mismatched_validator.clone(),
                peer_id: PeerId::from(mismatched_validator.signatory().clone()),
                stake_account: mismatched_validator.clone(),
                total_stake: iroha_primitives::numeric::Quantity::from(2_000_u32),
                self_stake: iroha_primitives::numeric::Quantity::from(1_000_u32),
                metadata: Metadata::default(),
                status: PublicLaneValidatorStatus::Active,
                activation_epoch: Some(0),
                activation_height: Some(1),
                last_reward_epoch: Some(7),
            },
        );
        world.public_lane_stake_shares.insert(
            (LaneId::SINGLE, validator.clone(), staker.clone()),
            PublicLaneStakeShare {
                lane_id: LaneId::SINGLE,
                validator: validator.clone(),
                staker: staker.clone(),
                bonded: iroha_primitives::numeric::Quantity::from(900_u32),
                pending_unbonds: BTreeMap::from([(
                    request_id,
                    PublicLaneUnbonding {
                        request_id,
                        amount: iroha_primitives::numeric::Quantity::from(100_u32),
                        release_at_ms: 12_345,
                    },
                )]),
                metadata: Metadata::default(),
            },
        );
        world.public_lane_stake_shares.insert(
            (LaneId::SINGLE, validator.clone(), mismatched_staker.clone()),
            PublicLaneStakeShare {
                lane_id: mismatched_lane,
                validator: validator.clone(),
                staker: mismatched_staker.clone(),
                bonded: iroha_primitives::numeric::Quantity::from(400_u32),
                pending_unbonds: BTreeMap::new(),
                metadata: Metadata::default(),
            },
        );
        world.public_lane_rewards.insert(
            (LaneId::SINGLE, 7),
            PublicLaneRewardRecord {
                lane_id: LaneId::SINGLE,
                epoch: 7,
                asset: reward_asset.clone(),
                total_reward: iroha_primitives::numeric::Quantity::from(77_u32),
                shares: vec![PublicLaneRewardShare {
                    account: validator.clone(),
                    role: PublicLaneRewardRole::Validator,
                    amount: iroha_primitives::numeric::Quantity::from(77_u32),
                }],
                metadata: Metadata::default(),
            },
        );
        world.public_lane_rewards.insert(
            (LaneId::SINGLE, 8),
            PublicLaneRewardRecord {
                lane_id: mismatched_lane,
                epoch: 9,
                asset: reward_asset.clone(),
                total_reward: iroha_primitives::numeric::Quantity::from(88_u32),
                shares: vec![PublicLaneRewardShare {
                    account: validator.clone(),
                    role: PublicLaneRewardRole::Validator,
                    amount: iroha_primitives::numeric::Quantity::from(88_u32),
                }],
                metadata: Metadata::default(),
            },
        );
        world
            .public_lane_reward_claims
            .insert((LaneId::SINGLE, validator.clone(), reward_asset.clone()), 6);

        let state = State::new(world, kura, query_handle);
        let json_value = norito::json::to_value(&state).expect("serialize state");
        let seed = deserialize::KuraSeed {
            kura: Kura::blank_kura_for_testing(),
            query_handle: LiveQueryStore::start_test(),
            #[cfg(feature = "telemetry")]
            telemetry: crate::telemetry::StateTelemetry::default(),
        };
        let restored = seed
            .into_state_from_json(json_value)
            .expect("deserialize state");
        let view = restored.world_view();

        assert_eq!(
            view.public_lane_validators()
                .get(&(LaneId::SINGLE, validator.clone()))
                .expect("validator"),
            &PublicLaneValidatorRecord {
                lane_id: LaneId::SINGLE,
                validator: validator.clone(),
                peer_id: PeerId::from(validator.signatory().clone()),
                stake_account: validator.clone(),
                total_stake: iroha_primitives::numeric::Quantity::from(2_000_u32),
                self_stake: iroha_primitives::numeric::Quantity::from(1_000_u32),
                metadata: Metadata::default(),
                status: PublicLaneValidatorStatus::Active,
                activation_epoch: Some(0),
                activation_height: Some(1),
                last_reward_epoch: Some(7),
            }
        );
        assert_eq!(
            view.public_lane_stake_shares()
                .get(&(LaneId::SINGLE, validator.clone(), staker.clone()))
                .expect("stake share")
                .bonded,
            Quantity::from(900_u32)
        );
        assert_eq!(
            view.public_lane_rewards()
                .get(&(LaneId::SINGLE, 7))
                .expect("reward")
                .total_reward,
            Quantity::from(77_u32)
        );
        assert_eq!(
            view.public_lane_reward_claims()
                .get(&(LaneId::SINGLE, validator, reward_asset)),
            Some(&6)
        );
        assert!(
            view.public_lane_validators()
                .get(&(LaneId::SINGLE, mismatched_validator.clone()))
                .is_none(),
            "snapshot restore must not preserve stale validator storage key rows"
        );
        assert!(
            view.public_lane_validators()
                .get(&(mismatched_lane, mismatched_validator))
                .is_none(),
            "snapshot restore must not normalize mismatched validator rows to embedded keys"
        );
        assert!(
            view.public_lane_stake_shares()
                .get(&(LaneId::SINGLE, ALICE_ID.clone(), mismatched_staker.clone()))
                .is_none(),
            "snapshot restore must not preserve stale stake-share storage key rows"
        );
        assert!(
            view.public_lane_stake_shares()
                .get(&(mismatched_lane, ALICE_ID.clone(), mismatched_staker))
                .is_none(),
            "snapshot restore must not normalize mismatched stake-share rows to embedded keys"
        );
        assert!(
            view.public_lane_rewards()
                .get(&(LaneId::SINGLE, 8))
                .is_none(),
            "snapshot restore must not preserve stale reward storage key rows"
        );
        assert!(
            view.public_lane_rewards()
                .get(&(mismatched_lane, 9))
                .is_none(),
            "snapshot restore must not normalize mismatched reward rows to embedded keys"
        );
    }
