    #[test]
    fn latest_block_header_fast_reads_latest_committed_header() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);

        assert!(state.latest_block_header_fast().is_none());

        let keypair = crate::state::checked_keypair();
        let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 42, 0);
        let block = iroha_data_model::block::builder::BlockBuilder::new(header)
            .build_with_signature(0, keypair.private_key());
        let header = block.header();
        let block_hash = block.hash();
        kura.store_block(Arc::new(block))
            .expect("store block in kura");
        {
            let mut block_hashes = state.block_hashes.block();
            block_hashes.push_for_tests(block_hash);
            block_hashes.commit_for_tests();
        }
        state.update_latest_block_header_cache_for_tests(header);

        let latest = state
            .latest_block_header_fast()
            .expect("latest block header should exist");
        assert_eq!(latest.height().get(), 1);
        assert_eq!(latest.creation_time().as_millis(), 42);
    }

    fn dataspace_catalog_for_lane_catalog(catalog: &LaneCatalog) -> DataSpaceCatalog {
        let mut ids: BTreeSet<DataSpaceId> = catalog
            .lanes()
            .iter()
            .map(|lane| lane.dataspace_id)
            .collect();
        ids.insert(DataSpaceId::UNIVERSAL);
        let entries = ids
            .into_iter()
            .map(|id| DataSpaceMetadata {
                id,
                alias: format!("dataspace_{}", id.as_u64()),
                description: None,
                fault_tolerance: 1,
            })
            .collect();
        DataSpaceCatalog::new(entries).expect("dataspace catalog")
    }

    fn store_tlv_bytes(vm: &mut IVM, ty: PointerType, payload: &[u8]) -> u64 {
        let tlv = make_tlv(ty, payload);
        vm.alloc_input_tlv(&tlv).expect("alloc input TLV")
    }

    fn store_tlv_norito<T: norito::NoritoSerialize>(
        vm: &mut IVM,
        ty: PointerType,
        value: &T,
    ) -> u64 {
        let payload = norito::to_bytes(value).expect("serialize Norito payload");
        store_tlv_bytes(vm, ty, &payload)
    }

