        assert_eq!(lane.settlement.as_deref(), Some("settlement-v3"));
        assert_eq!(lane.storage, LaneStorageProfile::FullReplica);
        assert_eq!(lane.proof_scheme, DaProofScheme::KzgBls12_381);
