    #[test]
    fn set_crypto_updates_sm2_distid_default() {
        struct DistidGuard(String);
        impl Drop for DistidGuard {
            fn drop(&mut self) {
                Sm2PublicKey::set_default_distid(self.0.clone())
                    .expect("sm2_distid_default must be valid");
            }
        }

        let original = Sm2PublicKey::default_distid();
        let _guard = DistidGuard(original.clone());

        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let world = World::default();
        let state = State::new_for_testing(world, kura, query_handle);

        let mut crypto_cfg = (*state.crypto()).clone();
        crypto_cfg.sm2_distid_default = "runtime-override".to_owned();
        state.set_crypto(crypto_cfg.clone());

        assert_eq!(Sm2PublicKey::default_distid(), "runtime-override");

        crypto_cfg.sm2_distid_default = original;
        state.set_crypto(crypto_cfg);
    }

