    #[test]
    fn apply_lane_lifecycle_internal_autoscale_rejects_malformed_managed_addition() {
        let mut bad_managed_value =
            autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
        bad_managed_value
            .metadata
            .insert(AUTOSCALE_META_MANAGED.to_owned(), "TRUE".to_owned());

        let mut bad_alias =
            autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
        bad_alias.alias = "elastic".to_owned();

        let mut bad_height =
            autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
        bad_height
            .metadata
            .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "0".to_owned());

        let mut restricted =
            autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
        restricted.visibility = LaneVisibility::Restricted;

        for (lane, expected_reason) in [
            (
                bad_managed_value,
                "autoscale.managed must be exactly `true`",
            ),
            (bad_alias, "alias must match elastic-lane-{id}"),
            (
                bad_height,
                "autoscale.created_height must be a positive integer",
            ),
            (restricted, "autoscale-managed lanes must be public"),
        ] {
            let kura = Kura::blank_kura_for_testing();
            let query_handle = LiveQueryStore::start_test();
            let state = State::new_for_testing(World::default(), kura, query_handle);
            enable_nexus_autoscale_for_testing(&state);
            let lane_id = lane.id;
            let plan = iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![lane],
                retire: Vec::new(),
            };

            let err = state
                .apply_lane_lifecycle_with_options(&plan, false, true)
                .expect_err("internal autoscale lifecycle must reject malformed managed lanes");
            assert!(matches!(
                err,
                LaneLifecycleError::InvalidAutoscaleManagedLane { lane, reason }
                    if lane == lane_id && reason == expected_reason
            ));
            assert_eq!(state.nexus_snapshot().lane_catalog.lanes().len(), 1);
        }
    }

    #[test]
    fn apply_lane_lifecycle_internal_autoscale_rejects_base_profile_drift() {
        let mut base_lane = LaneConfig {
            lane_type: Some("regulated-public".to_owned()),
            settlement: Some("settlement-v3".to_owned()),
            proof_scheme: DaProofScheme::KzgBls12_381,
            ..LaneConfig::default()
        };
        base_lane
            .metadata
            .insert("security.profile".to_owned(), "strict".to_owned());
        base_lane
            .metadata
            .insert("scheduler.teu_capacity".to_owned(), "2400".to_owned());
        let mut valid_lane = autoscale_elastic_lane_config_from_base(LaneId::new(1), &base_lane, 2)
            .expect("public base profile should produce a managed lane");
        attach_synthetic_autoscale_committee_for_test(&mut valid_lane);
        let profile_drifts = [
            ("lane type", {
                let mut drift = valid_lane.clone();
                drift.lane_type = Some("unregulated".to_owned());
                drift
            }),
            ("governance", {
                let mut drift = valid_lane.clone();
                drift.governance = Some("governance-v1".to_owned());
                drift
            }),
            ("settlement", {
                let mut drift = valid_lane.clone();
                drift.settlement = Some("settlement-v1".to_owned());
                drift
            }),
            ("storage", {
                let mut drift = valid_lane.clone();
                drift.storage = LaneStorageProfile::SplitReplica;
                drift
            }),
            ("proof scheme", {
                let mut drift = valid_lane.clone();
                drift.proof_scheme = DaProofScheme::MerkleSha256;
                drift
            }),
            ("metadata value", {
                let mut drift = valid_lane.clone();
                drift
                    .metadata
                    .insert("security.profile".to_owned(), "permissive".to_owned());
                drift
            }),
            ("missing metadata", {
                let mut drift = valid_lane.clone();
                drift.metadata.remove("scheduler.teu_capacity");
                drift
            }),
            ("extra metadata", {
                let mut drift = valid_lane;
                drift
                    .metadata
                    .insert("unexpected".to_owned(), "value".to_owned());
                drift
            }),
        ];

        for (field, lane) in profile_drifts {
            let query_handle = LiveQueryStore::start_test();
            let state = State::new_with_nexus_for_testing(
                World::default(),
                autoscale_transition_test_nexus(vec![base_lane.clone()], 1, 3, 100),
                query_handle,
            );

            let err = state
                .apply_lane_lifecycle_with_options(
                    &iroha_data_model::nexus::LaneLifecyclePlan {
                        additions: vec![lane],
                        retire: Vec::new(),
                    },
                    false,
                    true,
                )
                .unwrap_err();
            assert!(
                matches!(
                    &err,
                    LaneLifecycleError::InvalidAutoscaleManagedLane { lane, reason }
                        if *lane == LaneId::new(1) && *reason == AUTOSCALE_PROFILE_DRIFT_REASON
                ),
                "internal autoscale lifecycle accepted {field} drift: {err}"
            );
            assert_eq!(
                state.nexus_snapshot().lane_catalog.lanes(),
                &[base_lane.clone()],
                "rejected {field} drift must not mutate the lane catalog"
            );
        }
    }

