    #[test]
    fn set_nexus_prunes_lane_relay_emergency_overrides_for_removed_lanes() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), kura, query_handle);

        let removed = LaneId::new(1);

        let initial_nexus = iroha_config::parameters::actual::Nexus {
            enabled: true,
            dataspace_catalog: DataSpaceCatalog::new(vec![DataSpaceMetadata {
                id: DataSpaceId::UNIVERSAL,
                alias: "universal".to_string(),
                description: None,
                fault_tolerance: 1,
            }])
            .expect("dataspace catalog"),
            lane_catalog: LaneCatalog::new(
                nonzero!(2_u32),
                vec![
                    LaneConfig::default(),
                    LaneConfig {
                        id: LaneId::new(1),
                        dataspace_id: DataSpaceId::UNIVERSAL,
                        alias: "historical".to_string(),
                        ..LaneConfig::default()
                    },
                ],
            )
            .expect("lane catalog"),
            ..iroha_config::parameters::actual::Nexus::default()
        };
        state
            .set_nexus(initial_nexus)
            .expect("set initial nexus config");

        let mut wb = state.world.block();
        wb.lane_relay_emergency_validators.insert(
            removed,
            LaneRelayEmergencyValidatorSet {
                peers: vec![PeerId::from(ALICE_ID.signatory().clone())],
                expires_at_height: 10,
                metadata: Metadata::default(),
            },
        );
        wb.commit();
        assert!(
            state
                .world
                .lane_relay_emergency_validators
                .view()
                .get(&removed)
                .is_some(),
            "test setup should install removed-lane override"
        );

        let updated_nexus = iroha_config::parameters::actual::Nexus {
            enabled: true,
            dataspace_catalog: DataSpaceCatalog::new(vec![DataSpaceMetadata {
                id: DataSpaceId::UNIVERSAL,
                alias: "universal".to_string(),
                description: None,
                fault_tolerance: 1,
            }])
            .expect("dataspace catalog"),
            lane_catalog: LaneCatalog::new(nonzero!(1_u32), vec![LaneConfig::default()])
                .expect("lane catalog"),
            ..iroha_config::parameters::actual::Nexus::default()
        };
        state
            .set_nexus(updated_nexus)
            .expect("set updated nexus config");

        assert!(
            state
                .world
                .lane_relay_emergency_validators
                .view()
                .get(&removed)
                .is_none(),
            "removed lane override must be pruned by set_nexus"
        );
    }

    #[test]
    fn apply_lane_lifecycle_prunes_stale_lane_relay_emergency_overrides() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query_handle);
        state.nexus.write().enabled = true;

        let retained = LaneId::SINGLE;
        let added = LaneId::new(1);
        let stale_unknown = LaneId::new(9);
        let override_set = LaneRelayEmergencyValidatorSet {
            peers: vec![PeerId::from(ALICE_ID.signatory().clone())],
            expires_at_height: 10,
            metadata: Metadata::default(),
        };
        {
            let mut wb = state.world.block();
            wb.lane_relay_emergency_validators
                .insert(retained, override_set.clone());
            wb.lane_relay_emergency_validators
                .insert(added, override_set.clone());
            wb.lane_relay_emergency_validators
                .insert(stale_unknown, override_set);
            wb.commit();
        }

        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![LaneConfig {
                    id: added,
                    alias: "new-emergency-lane".to_owned(),
                    ..LaneConfig::default()
                }],
                retire: Vec::new(),
            })
            .expect("adding an unrelated lane should prune stale emergency overrides");

        let view = state.world.view();
        assert!(
            view.lane_relay_emergency_validators()
                .get(&retained)
                .is_some(),
            "active default-lane emergency override must remain"
        );
        assert!(
            view.lane_relay_emergency_validators().get(&added).is_none(),
            "pre-staged overrides for a newly created lane id must be pruned as stale prior-incarnation state"
        );
        assert!(
            view.lane_relay_emergency_validators()
                .get(&stale_unknown)
                .is_none(),
            "manual lifecycle updates must prune emergency overrides for lanes absent from the updated catalog"
        );
    }

    #[test]
    fn set_nexus_recreation_preserves_lineage_across_snapshot_and_accepts_first_merge() {
        let _status_guard = crate::sumeragi::status::nexus_fee_test_lock()
            .lock()
            .expect("nexus status test lock");
        crate::sumeragi::status::reset_nexus_economics_for_tests();
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
        let lane_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![
                LaneConfig::default(),
                LaneConfig {
                    id: LaneId::new(1),
                    alias: "beta".to_string(),
                    ..LaneConfig::default()
                },
            ],
        )
        .expect("two-lane catalog");
        let two_lane_nexus = iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog: lane_catalog.clone(),
            ..iroha_config::parameters::actual::Nexus::default()
        };
        let recreated_lane_config = RuntimeLaneConfig::from_catalog(&lane_catalog);
        state
            .set_nexus(two_lane_nexus)
            .expect("configure initial two-lane nexus");
        let historical_lane_incarnation = state
            .lane_incarnation(LaneId::new(1))
            .expect("initial lane has an active incarnation");
        let historical_lineage = state.lane_incarnation_lineage_snapshot()[&LaneId::new(1)];
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                ..iroha_config::parameters::actual::Nexus::default()
            })
            .expect("retire lane1 before simulating a restart and recreation");

        let retired_snapshot = norito::json::to_value(&state).expect("serialize retired state");
        let mut restarted = deserialize::KuraSeed {
            kura: Arc::clone(&kura),
            query_handle: LiveQueryStore::start_test(),
            #[cfg(feature = "telemetry")]
            telemetry: crate::telemetry::StateTelemetry::default(),
        }
        .into_state_from_json(retired_snapshot)
        .expect("restore retired state with retained incarnation lineage");
        assert_eq!(
            restarted.lane_incarnation_lineage_snapshot()[&LaneId::new(1)],
            historical_lineage,
            "restart must retain the retired lane's latest incarnation lineage"
        );
        seed_stale_da_cursors_for_lane_recreation(
            &restarted,
            &recreated_lane_config,
            LaneId::new(1),
        );
        let stale_status_bonded = Quantity::from(924_u32);
        let retained_status_bonded = Quantity::from(904_u32);
        record_public_lane_staking_status_for_test(LaneId::new(1), &stale_status_bonded);
        record_public_lane_staking_status_for_test(LaneId::SINGLE, &retained_status_bonded);
        restarted
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog,
                ..iroha_config::parameters::actual::Nexus::default()
            })
            .expect("config swap recreates lane1");
        let recreated_lane_incarnation = restarted
            .lane_incarnation(LaneId::new(1))
            .expect("recreated lane has an active incarnation");
        assert_ne!(
            recreated_lane_incarnation, historical_lane_incarnation,
            "config recreation must not reuse the historical lane incarnation"
        );
        let recreated_lineage = restarted.lane_incarnation_lineage_snapshot()[&LaneId::new(1)];
        assert_eq!(
            recreated_lineage.generation,
            historical_lineage.generation + 1
        );
        assert_eq!(recreated_lineage.incarnation, recreated_lane_incarnation);
        assert_recreated_lane_da_cursors_accept_fresh_sequence(&restarted, LaneId::new(1));
        assert_public_lane_staking_status_absent(
            LaneId::new(1),
            "set_nexus recreated lane must not inherit old operator staking status",
        );
        assert_public_lane_staking_status_bonded(
            LaneId::SINGLE,
            &retained_status_bonded,
            "set_nexus recreated lane reset must preserve unrelated operator staking status",
        );
        assert_eq!(
            expected_next_merge_lane_height(
                &restarted.merge_admission.read().latest_lane_snapshots,
                LaneId::new(1),
                DataSpaceId::UNIVERSAL,
                recreated_lane_incarnation,
            ),
            Some(1),
            "set_nexus reset must reopen the recreated lane-local height namespace at one"
        );

        let commit_keypairs = configure_commit_topology(&restarted, 4);
        install_lane_manifest_registry_for_keypairs(
            &restarted,
            &[LaneId::SINGLE, LaneId::new(1)],
            &commit_keypairs,
        );
        ensure_merge_carrier_parent_for_test(&restarted);
        let lane1_h1 = sample_lane_relay_envelope_for_state_at_heights_with_view(
            &restarted,
            1,
            1,
            LaneId::new(1),
            0,
            &commit_keypairs,
        );
        restarted
            .lane_relays
            .write()
            .insert(lane1_h1.clone())
            .expect("recreated lane relay stored");
        let candidate = restarted
            .merge_entry_candidates_from_lane_relays()
            .into_iter()
            .next()
            .expect("recreated lane must produce a merge candidate");
        assert!(
            candidate.lane_snapshots.iter().any(|snapshot| {
                snapshot.lane_id == LaneId::new(1)
                    && snapshot.lane_incarnation == recreated_lane_incarnation
                    && snapshot.lane_block_height == lane1_h1.block_height
            }),
            "set_nexus recreation must admit the fresh lane-local height-one relay"
        );
        let merge_qc = merge_qc_for_candidate(&restarted, &candidate, &commit_keypairs, &[0, 1, 2]);
        restarted
            .commit_merge_entry(merge_entry_from_candidate(candidate, merge_qc))
            .expect("first recreated-lane merge entry commits after set_nexus recreation");
        crate::sumeragi::status::reset_nexus_economics_for_tests();
    }

    #[test]
    fn set_nexus_prunes_uaid_bindings_for_removed_dataspaces() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), kura, query_handle);

        let retained = DataSpaceId::UNIVERSAL;
        let removed = DataSpaceId::new(7);
        let uaid = UniversalAccountId::from_hash(Hash::new(b"uaid::stale-binding"));

        let initial_nexus = iroha_config::parameters::actual::Nexus {
            enabled: true,
            dataspace_catalog: DataSpaceCatalog::new(vec![
                DataSpaceMetadata {
                    id: retained,
                    alias: "universal".to_string(),
                    description: None,
                    fault_tolerance: 1,
                },
                DataSpaceMetadata {
                    id: removed,
                    alias: "historical".to_string(),
                    description: None,
                    fault_tolerance: 1,
                },
            ])
            .expect("dataspace catalog"),
            ..iroha_config::parameters::actual::Nexus::default()
        };
        state
            .set_nexus(initial_nexus)
            .expect("set initial nexus config");

        let mut bindings = UaidDataspaceBindings::default();
        bindings.bind_account(retained, ALICE_ID.clone());
        bindings.bind_account(removed, ALICE_ID.clone());

        let mut wb = state.world.block();
        wb.uaid_dataspaces.insert(uaid, bindings);
        wb.commit();

        let updated_nexus = iroha_config::parameters::actual::Nexus {
            enabled: true,
            dataspace_catalog: DataSpaceCatalog::new(vec![DataSpaceMetadata {
                id: retained,
                alias: "universal".to_string(),
                description: None,
                fault_tolerance: 1,
            }])
            .expect("dataspace catalog"),
            ..iroha_config::parameters::actual::Nexus::default()
        };
        state
            .set_nexus(updated_nexus)
            .expect("set updated nexus config");

        let binding_view = state.world.uaid_dataspaces.view();
        let retained_bindings = binding_view
            .get(&uaid)
            .expect("uaid binding should remain for retained dataspace");
        assert!(
            retained_bindings
                .iter()
                .all(|(dataspace_id, _)| *dataspace_id == retained),
            "all stale dataspaces should be pruned from uaid bindings"
        );
    }

