    #[test]
    fn apply_lane_lifecycle_retire_prunes_direct_lane_application_markers() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query_handle);
        state.nexus.write().enabled = true;

        let retired_lane = LaneId::new(1);
        let retained_lane = LaneId::SINGLE;
        let add_lane = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig {
                id: retired_lane,
                alias: "direct-marker-retired".to_string(),
                ..LaneConfig::default()
            }],
            retire: Vec::new(),
        };
        state
            .apply_lane_lifecycle(&add_lane)
            .expect("add direct-marker test lane");

        let retired_key = seed_direct_lane_application_marker(
            &state,
            retired_lane,
            DataSpaceId::UNIVERSAL,
            1,
            0x31,
        );
        let retained_key = seed_direct_lane_application_marker(
            &state,
            retained_lane,
            DataSpaceId::UNIVERSAL,
            1,
            0x32,
        );
        let (embedded_retired_key, embedded_retired_marker) = sample_direct_lane_application_marker(
            retained_lane,
            retired_lane,
            DataSpaceId::UNIVERSAL,
            2,
            0x33,
        );
        {
            let mut block = state.world.direct_lane_block_application_markers.block();
            block.insert(embedded_retired_key, embedded_retired_marker);
            block.commit();
        }

        let retire_lane = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: Vec::new(),
            retire: vec![retired_lane],
        };
        state
            .apply_lane_lifecycle(&retire_lane)
            .expect("retire direct-marker test lane");

        let view = state.world.view();
        assert!(
            view.direct_lane_block_application_markers()
                .get(&retired_key)
                .is_none(),
            "lane retirement must prune direct markers keyed by the reset lane"
        );
        assert!(
            view.direct_lane_block_application_markers()
                .get(&embedded_retired_key)
                .is_none(),
            "lane retirement must prune direct markers whose payload names the reset lane"
        );
        assert!(
            view.direct_lane_block_application_markers()
                .get(&retained_key)
                .is_some(),
            "lane retirement must preserve unrelated direct markers"
        );
        drop(view);

        state
            .apply_lane_lifecycle(&add_lane)
            .expect("recreate direct-marker test lane");
        let view = state.world.view();
        assert!(
            view.direct_lane_block_application_markers()
                .get(&retired_key)
                .is_none(),
            "recreated lanes must not inherit old direct-application markers"
        );
        assert!(
            view.direct_lane_block_application_markers()
                .get(&retained_key)
                .is_some(),
            "recreation must still preserve unrelated direct markers"
        );
    }

    #[test]
    fn lane_recreation_generation_overflow_is_atomic() {
        let state = State::new_for_testing(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        state.nexus.write().enabled = true;
        let lane_id = LaneId::new(1);
        let lane = LaneConfig {
            id: lane_id,
            alias: "overflow-lineage".to_owned(),
            ..LaneConfig::default()
        };
        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![lane.clone()],
                retire: Vec::new(),
            })
            .expect("add lane");
        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: Vec::new(),
                retire: vec![lane_id],
            })
            .expect("retire lane");
        state
            .lane_incarnation_lineage
            .write()
            .get_mut(&lane_id)
            .expect("retired lineage")
            .generation = u64::MAX;

        let nexus_before = state.nexus_snapshot();
        let lineage_before = state.lane_incarnation_lineage_snapshot();
        let incarnations_before = state.lane_incarnations_snapshot();
        let error = state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![lane],
                retire: Vec::new(),
            })
            .expect_err("lineage generation overflow must fail closed");
        assert!(error.to_string().contains("generation overflow"));
        assert_eq!(
            state.nexus_snapshot().lane_catalog,
            nexus_before.lane_catalog
        );
        assert_eq!(state.lane_incarnation_lineage_snapshot(), lineage_before);
        assert_eq!(state.lane_incarnations_snapshot(), incarnations_before);
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn apply_lane_lifecycle_retire_prunes_lane_relays() {
        let _status_guard = crate::sumeragi::status::lane_relay_test_guard();
        crate::sumeragi::status::set_lane_relay_envelopes(Vec::new());
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query_handle);
        state.nexus.write().enabled = true;

        let plan = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig {
                id: LaneId::new(1),
                alias: "beta".to_string(),
                ..LaneConfig::default()
            }],
            retire: Vec::new(),
        };
        state
            .apply_lane_lifecycle(&plan)
            .expect("added second lane");
        let commit_keypairs = configure_commit_topology(&state, 4);
        install_lane_manifest_registry_for_keypairs(
            &state,
            &[LaneId::SINGLE, LaneId::new(1)],
            &commit_keypairs,
        );

        let lane1_h1 =
            sample_lane_relay_envelope_for_state(&state, 1, LaneId::new(1), &commit_keypairs);
        let historical_lane_incarnation = lane1_h1.lane_incarnation;
        let lane0_h1 =
            sample_lane_relay_envelope_for_state(&state, 1, LaneId::SINGLE, &commit_keypairs);
        {
            let mut relays = state.lane_relays.write();
            let _ = relays.insert(lane0_h1.clone()).expect("lane0 relay stored");
            let _ = relays.insert(lane1_h1.clone()).expect("lane1 relay stored");
        }
        crate::sumeragi::status::set_lane_relay_envelopes(vec![lane0_h1.clone(), lane1_h1.clone()]);
        ensure_merge_carrier_parent_for_test(&state);
        let merge_candidate = merge_candidate_from_relay(&state, 1, &lane1_h1);
        let merge_qc =
            merge_qc_for_candidate(&state, &merge_candidate, &commit_keypairs, &[0, 1, 2]);
        state
            .commit_merge_entry(merge_entry_from_candidate(merge_candidate, merge_qc))
            .expect("seed lane1 merge history");
        {
            let mut commitments = state.da_commitments.write();
            let record = DaCommitmentRecord::new(
                LaneId::new(1),
                1,
                0,
                BlobDigest::new([0xAA; 32]),
                ManifestDigest::new([0xBB; 32]),
                DaProofScheme::MerkleSha256,
                Hash::prehashed([0xCC; 32]),
                None,
                None,
                RetentionClass::default(),
                StorageTicketId::new([0xEE; 32]),
                checked_da_ack_signature(0x11),
            );
            commitments.insert(
                &record,
                DaCommitmentLocation {
                    block_height: 3,
                    index_in_bundle: 0,
                },
            );
            state.da_confidential_compute.write().insert(
                &record,
                DaCommitmentLocation {
                    block_height: 3,
                    index_in_bundle: 1,
                },
                &ConfidentialComputePolicy::new(
                    ConfidentialComputeMechanism::Encryption,
                    7,
                    Vec::new(),
                ),
            );
        }
        {
            let mut intents = state.da_pin_intents.write();
            let mut intent = DaPinIntent::new(
                LaneId::new(1),
                1,
                1,
                StorageTicketId::new([0x44; 32]),
                ManifestDigest::new([0x55; 32]),
            );
            intent.alias = Some("lane1-alias".to_string());
            intents.insert(
                intent,
                DaCommitmentLocation {
                    block_height: 3,
                    index_in_bundle: 2,
                },
            );
        }

        let retire_plan = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: Vec::new(),
            retire: vec![LaneId::new(1)],
        };
        state
            .apply_lane_lifecycle(&retire_plan)
            .expect("retired lane");

        let snapshot = state.lane_relay_snapshot();
        assert_eq!(snapshot.len(), 1);
        assert_eq!(snapshot[0].lane_id, LaneId::new(0));
        let status_relays = crate::sumeragi::status::lane_relay_envelopes_snapshot();
        assert_eq!(
            status_relays,
            vec![lane0_h1],
            "retired lane relay status snapshot must be pruned with state"
        );
        assert!(
            state
                .da_commitments
                .read()
                .get_by_lane_epoch_sequence(1, 1, 0)
                .is_none(),
            "retired lane commitments pruned"
        );
        assert!(
            state
                .da_confidential_compute
                .read()
                .get_by_lane_epoch_sequence(1, 1, 0)
                .is_none(),
            "retired lane confidential receipts pruned"
        );
        assert!(
            state
                .da_pin_intents
                .read()
                .get_by_alias("lane1-alias")
                .is_none(),
            "retired lane pin intents pruned"
        );

        state
            .apply_lane_lifecycle(&plan)
            .expect("re-added second lane");
        let recreated_lane_incarnation = state
            .lane_incarnation(LaneId::new(1))
            .expect("recreated lane has an active incarnation");
        assert_ne!(
            recreated_lane_incarnation, historical_lane_incarnation,
            "manual recreation must derive a fresh lane incarnation"
        );
        assert!(
            !state
                .merge_admission
                .read()
                .latest_lane_snapshots
                .contains_key(&(
                    LaneId::new(1),
                    DataSpaceId::UNIVERSAL,
                    historical_lane_incarnation,
                )),
            "retired lane merge history must be pruned before recreation"
        );
        assert_eq!(
            expected_next_merge_lane_height(
                &state.merge_admission.read().latest_lane_snapshots,
                LaneId::new(1),
                DataSpaceId::UNIVERSAL,
                recreated_lane_incarnation,
            ),
            Some(1),
            "recreated lane-local merge height must restart at one"
        );
        install_lane_manifest_registry_for_keypairs(
            &state,
            &[LaneId::SINGLE, LaneId::new(1)],
            &commit_keypairs,
        );
        let lane1_recreated_h1 = sample_lane_relay_envelope_for_state_at_heights_with_view(
            &state,
            2,
            1,
            LaneId::new(1),
            0,
            &commit_keypairs,
        );
        state
            .lane_relays
            .write()
            .insert(lane1_recreated_h1.clone())
            .expect("recreated lane relay stored");
        let candidates = state.merge_entry_candidates_from_lane_relays();
        let candidate = candidates
            .into_iter()
            .next()
            .expect("recreated lane must produce a merge candidate");
        assert!(
            candidate.lane_snapshots.iter().any(|snapshot| {
                snapshot.lane_id == LaneId::new(1)
                    && snapshot.lane_incarnation == recreated_lane_incarnation
                    && snapshot.lane_block_height == lane1_recreated_h1.block_height
            }),
            "retired lane merge history must not block the same height under a fresh incarnation"
        );
        let merge_qc = merge_qc_for_candidate(&state, &candidate, &commit_keypairs, &[0, 1, 2]);
        state
            .commit_merge_entry(merge_entry_from_candidate(candidate, merge_qc))
            .expect("recreated lane merge entry commits");
        crate::sumeragi::status::set_lane_relay_envelopes(Vec::new());
    }

    #[test]
    fn apply_lane_lifecycle_retire_prunes_da_pin_intent_world_indexes() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query_handle);
        state.nexus.write().enabled = true;
        let retired_lane_id = LaneId::new(1);
        let plan = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig {
                id: retired_lane_id,
                alias: "pin-lane".to_string(),
                ..LaneConfig::default()
            }],
            retire: Vec::new(),
        };
        state
            .apply_lane_lifecycle(&plan)
            .expect("added pin test lane");

        let mut retired_intent = DaPinIntent::new(
            retired_lane_id,
            5,
            0,
            StorageTicketId::new([0x61; 32]),
            ManifestDigest::new([0x71; 32]),
        );
        retired_intent.alias = Some("retired-pin".to_owned());
        let mut retained_intent = DaPinIntent::new(
            LaneId::SINGLE,
            5,
            1,
            StorageTicketId::new([0x62; 32]),
            ManifestDigest::new([0x72; 32]),
        );
        retained_intent.alias = Some("retained-pin".to_owned());
        seed_da_pin_intent_world_indexes_for_test(&state, retired_intent.clone(), 3, 0);
        seed_da_pin_intent_world_indexes_for_test(&state, retained_intent.clone(), 3, 1);

        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: Vec::new(),
                retire: vec![retired_lane_id],
            })
            .expect("retired pin test lane");

        let view = state.view();
        let world = view.world();
        assert!(
            world
                .da_pin_intents_by_ticket()
                .get(&retired_intent.storage_ticket)
                .is_none(),
            "retired lane pin intent must be removed from the ticket index"
        );
        assert!(
            world.da_pin_intents_by_alias().get("retired-pin").is_none(),
            "retired lane pin intent alias must be removed"
        );
        assert!(
            world
                .da_pin_intents_by_manifest()
                .get(&retired_intent.manifest_hash)
                .is_none(),
            "retired lane pin intent manifest index must be removed"
        );
        assert!(
            world
                .da_pin_intents_by_lane_epoch()
                .get(&(
                    retired_intent.lane_id,
                    retired_intent.epoch,
                    retired_intent.sequence
                ))
                .is_none(),
            "retired lane pin intent lane-epoch index must be removed"
        );
        assert!(
            world
                .da_pin_intents_by_ticket()
                .get(&retained_intent.storage_ticket)
                .is_some(),
            "surviving lane pin intent ticket index must be retained"
        );
        assert_eq!(
            world.da_pin_intents_by_alias().get("retained-pin"),
            Some(&retained_intent.storage_ticket)
        );
        assert_eq!(
            world
                .da_pin_intents_by_manifest()
                .get(&retained_intent.manifest_hash),
            Some(&retained_intent.storage_ticket)
        );
        assert_eq!(
            world.da_pin_intents_by_lane_epoch().get(&(
                retained_intent.lane_id,
                retained_intent.epoch,
                retained_intent.sequence
            )),
            Some(&retained_intent.storage_ticket)
        );
    }

    #[test]
    fn set_nexus_retire_prunes_da_pin_intent_world_indexes() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), kura, query_handle);
        let retired_lane_id = LaneId::new(1);
        let initial_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![
                LaneConfig::default(),
                LaneConfig {
                    id: retired_lane_id,
                    alias: "set-nexus-pin-lane".to_string(),
                    ..LaneConfig::default()
                },
            ],
        )
        .expect("initial lane catalog");
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog: initial_catalog,
                ..Default::default()
            })
            .expect("seed pin test lane through set_nexus");

        let mut retired_intent = DaPinIntent::new(
            retired_lane_id,
            5,
            0,
            StorageTicketId::new([0x63; 32]),
            ManifestDigest::new([0x73; 32]),
        );
        retired_intent.alias = Some("set-nexus-retired-pin".to_owned());
        let mut retained_intent = DaPinIntent::new(
            LaneId::SINGLE,
            5,
            1,
            StorageTicketId::new([0x64; 32]),
            ManifestDigest::new([0x74; 32]),
        );
        retained_intent.alias = Some("set-nexus-retained-pin".to_owned());
        seed_da_pin_intent_world_indexes_for_test(&state, retired_intent.clone(), 4, 0);
        seed_da_pin_intent_world_indexes_for_test(&state, retained_intent.clone(), 4, 1);

        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog: LaneCatalog::default(),
                ..Default::default()
            })
            .expect("retire pin test lane through set_nexus");

        let view = state.view();
        let world = view.world();
        assert!(
            world
                .da_pin_intents_by_ticket()
                .get(&retired_intent.storage_ticket)
                .is_none(),
            "set_nexus lane retirement must remove stale pin intent tickets"
        );
        assert!(
            world
                .da_pin_intents_by_alias()
                .get("set-nexus-retired-pin")
                .is_none(),
            "set_nexus lane retirement must remove stale pin intent aliases"
        );
        assert!(
            world
                .da_pin_intents_by_manifest()
                .get(&retired_intent.manifest_hash)
                .is_none(),
            "set_nexus lane retirement must remove stale pin intent manifests"
        );
        assert!(
            world
                .da_pin_intents_by_lane_epoch()
                .get(&(
                    retired_intent.lane_id,
                    retired_intent.epoch,
                    retired_intent.sequence,
                ))
                .is_none(),
            "set_nexus lane retirement must remove stale pin intent lane-epoch indexes"
        );
        assert!(
            world
                .da_pin_intents_by_ticket()
                .get(&retained_intent.storage_ticket)
                .is_some(),
            "set_nexus lane retirement must preserve active-lane pin intent tickets"
        );
        assert_eq!(
            world
                .da_pin_intents_by_alias()
                .get("set-nexus-retained-pin"),
            Some(&retained_intent.storage_ticket)
        );
        assert_eq!(
            world
                .da_pin_intents_by_manifest()
                .get(&retained_intent.manifest_hash),
            Some(&retained_intent.storage_ticket)
        );
        assert_eq!(
            world.da_pin_intents_by_lane_epoch().get(&(
                retained_intent.lane_id,
                retained_intent.epoch,
                retained_intent.sequence,
            )),
            Some(&retained_intent.storage_ticket)
        );
    }

    #[test]
    fn apply_lane_lifecycle_addition_resets_rehydrated_merge_history_for_recreated_lane() {
        let _status_guard = crate::sumeragi::status::nexus_fee_test_lock()
            .lock()
            .expect("nexus status test lock");
        crate::sumeragi::status::reset_nexus_economics_for_tests();
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
        state.nexus.write().enabled = true;
        let lane1_config = LaneConfig {
            id: LaneId::new(1),
            alias: "beta".to_string(),
            ..LaneConfig::default()
        };
        let recreated_lane_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![LaneConfig::default(), lane1_config.clone()],
        )
        .expect("two-lane catalog");
        let recreated_lane_config = RuntimeLaneConfig::from_catalog(&recreated_lane_catalog);
        let add_lane = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![lane1_config],
            retire: Vec::new(),
        };
        state
            .apply_lane_lifecycle(&add_lane)
            .expect("added second lane");
        let commit_keypairs = configure_commit_topology(&state, 4);
        install_lane_manifest_registry_for_keypairs(
            &state,
            &[LaneId::SINGLE, LaneId::new(1)],
            &commit_keypairs,
        );
        let lane1_h1 =
            sample_lane_relay_envelope_for_state(&state, 1, LaneId::new(1), &commit_keypairs);
        state
            .lane_relays
            .write()
            .insert(lane1_h1.clone())
            .expect("lane1 relay stored");
        let historical_lane_incarnation = lane1_h1.lane_incarnation;
        ensure_merge_carrier_parent_for_test(&state);
        let candidate = merge_candidate_from_relay(&state, 1, &lane1_h1);
        let merge_qc = merge_qc_for_candidate(&state, &candidate, &commit_keypairs, &[0, 1, 2]);
        let stored = state
            .commit_merge_entry(merge_entry_from_candidate(candidate, merge_qc))
            .expect("seed lane1 merge history");
        publish_committed_merge_carrier_for_test(&state, stored.as_ref());
        let retire_lane = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: Vec::new(),
            retire: vec![LaneId::new(1)],
        };
        state
            .apply_lane_lifecycle(&retire_lane)
            .expect("retired lane");
        seed_autoscale_sample_history_for_snapshot_test(&state);

        let retired_snapshot =
            norito::json::to_value(&state).expect("serialize retired lane state for restart");
        drop(state);
        let restarted =
            deserialize_state_snapshot_value_with_kura(retired_snapshot, Arc::clone(&kura))
                .expect("restore retired lane state with exact lifecycle lineage");
        ensure_merge_carrier_parent_for_test(&restarted);
        restarted
            .recover_merge_ledger_from_kura()
            .expect("rehydrate historical merge snapshots from Kura");
        assert!(
            restarted.nexus_snapshot().enabled,
            "the restored runtime snapshot must preserve enabled Nexus state"
        );
        assert!(
            restarted
                .merge_admission
                .read()
                .latest_lane_snapshots
                .contains_key(&(
                    LaneId::new(1),
                    DataSpaceId::UNIVERSAL,
                    historical_lane_incarnation,
                )),
            "startup should rehydrate historical merge snapshots from Kura"
        );
        seed_stale_da_cursors_for_lane_recreation(
            &restarted,
            &recreated_lane_config,
            LaneId::new(1),
        );
        let stale_status_bonded = Quantity::from(925_u32);
        let retained_status_bonded = Quantity::from(905_u32);
        record_public_lane_staking_status_for_test(LaneId::new(1), &stale_status_bonded);
        record_public_lane_staking_status_for_test(LaneId::SINGLE, &retained_status_bonded);
        restarted
            .apply_lane_lifecycle(&add_lane)
            .expect("recreated second lane after restart");
        let recreated_lane_incarnation = restarted
            .lane_incarnation(LaneId::new(1))
            .expect("recreated lane has an active incarnation");
        assert_ne!(
            recreated_lane_incarnation, historical_lane_incarnation,
            "manual recreation must derive a fresh lane incarnation"
        );
        assert!(
            !restarted
                .merge_admission
                .read()
                .latest_lane_snapshots
                .contains_key(&(
                    LaneId::new(1),
                    DataSpaceId::UNIVERSAL,
                    historical_lane_incarnation,
                )),
            "adding a fresh lane incarnation must clear rehydrated merge history"
        );
        assert_recreated_lane_da_cursors_accept_fresh_sequence(&restarted, LaneId::new(1));
        assert_public_lane_staking_status_absent(
            LaneId::new(1),
            "manual lifecycle recreated lane must not inherit old operator staking status",
        );
        assert_public_lane_staking_status_bonded(
            LaneId::SINGLE,
            &retained_status_bonded,
            "manual lifecycle recreated lane reset must preserve unrelated operator staking status",
        );
        assert_eq!(
            expected_next_merge_lane_height(
                &restarted.merge_admission.read().latest_lane_snapshots,
                LaneId::new(1),
                DataSpaceId::UNIVERSAL,
                recreated_lane_incarnation,
            ),
            Some(1),
            "rehydrated old history must not advance the recreated lane-local namespace"
        );

        let commit_keypairs = configure_commit_topology(&restarted, 4);
        install_lane_manifest_registry_for_keypairs(
            &restarted,
            &[LaneId::SINGLE, LaneId::new(1)],
            &commit_keypairs,
        );
        let lane1_h1 = sample_lane_relay_envelope_for_state_at_heights_with_view(
            &restarted,
            3,
            1,
            LaneId::new(1),
            0,
            &commit_keypairs,
        );
        restarted
            .lane_relays
            .write()
            .insert(lane1_h1.clone())
            .expect("recreated lane relay stored");
        let candidates = restarted.merge_entry_candidates_from_lane_relays();
        let candidate = candidates
            .into_iter()
            .next()
            .expect("recreated lane must produce a merge candidate after restart");
        assert!(
            candidate.lane_snapshots.iter().any(|snapshot| {
                snapshot.lane_id == LaneId::new(1)
                    && snapshot.lane_incarnation == recreated_lane_incarnation
                    && snapshot.lane_block_height == lane1_h1.block_height
            }),
            "rehydrated old merge history must not suppress recreated lane relay"
        );
        let merge_qc = merge_qc_for_candidate(&restarted, &candidate, &commit_keypairs, &[0, 1, 2]);
        restarted
            .commit_merge_entry(merge_entry_from_candidate(candidate, merge_qc))
            .expect("recreated lane merge entry commits after restart");
        crate::sumeragi::status::reset_nexus_economics_for_tests();
    }

    #[test]
    fn apply_lane_lifecycle_recreated_lane_hides_previous_da_indexes_after_kura_replay() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let recreated_lane_id = LaneId::new(1);
        let lane1_config = LaneConfig {
            id: recreated_lane_id,
            alias: "beta".to_string(),
            ..LaneConfig::default()
        };
        let two_lane_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![LaneConfig::default(), lane1_config.clone()],
        )
        .expect("two-lane catalog");
        let two_lane_config = RuntimeLaneConfig::from_catalog(&two_lane_catalog);
        let initial_lane_config = RuntimeLaneConfig::default();
        let kura = strict_kura_for_testing(temp_dir.path().join("kura"), &initial_lane_config);
        let state = State::new_for_testing(
            World::default(),
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
        );
        install_existing_nexus_geometry_for_test(
            &state,
            iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog: two_lane_catalog.clone(),
                lane_config: two_lane_config.clone(),
                ..Default::default()
            },
        );

        let stale_record = sample_da_commitment_record(recreated_lane_id, 2, 1, 0xC8);
        let mut stale_pin = DaPinIntent::new(
            recreated_lane_id,
            2,
            1,
            StorageTicketId::new([0xCB; 32]),
            ManifestDigest::new([0xCC; 32]),
        );
        stale_pin.alias = Some("old-incarnation-pin".to_owned());
        let keypair = crate::state::checked_keypair();
        let old_block: SignedBlock = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .with_da_commitments(Some(
                iroha_data_model::da::commitment::DaCommitmentBundle::new(vec![
                    stale_record.clone(),
                ]),
            ))
            .with_da_pin_intents(Some(
                iroha_data_model::da::pin_intent::DaPinIntentBundle::new(vec![stale_pin.clone()]),
            ))
            .sign(keypair.private_key())
            .unpack(|_| {})
            .into();
        kura.store_block(Arc::new(old_block.clone()))
            .expect("store old-incarnation DA block");
        {
            let mut block_hashes = state.block_hashes.block();
            block_hashes.push(old_block.hash());
            block_hashes.commit_for_tests();
        }
        assert_eq!(
            state.find_da_commitment_by_manifest(&stale_record.manifest_hash),
            Some(stale_record.clone()),
            "test setup should hydrate old-incarnation DA commitment before reset"
        );
        assert!(
            state
                .da_pin_intents()
                .get_by_alias("old-incarnation-pin")
                .is_some(),
            "test setup should hydrate old-incarnation pin before reset"
        );

        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: Vec::new(),
                retire: vec![recreated_lane_id],
            })
            .expect("retire lane before recreation");
        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![lane1_config],
                retire: Vec::new(),
            })
            .expect("recreate lane");

        state
            .rewind_da_indexes_to_height(old_block.header().height().get())
            .expect("rewind DA indexes after lane recreation");
        {
            let commitments = state.da_commitments();
            assert!(
                commitments
                    .get_by_manifest(&stale_record.manifest_hash)
                    .is_none(),
                "old-incarnation commitment must not be query-visible after replay"
            );
            assert!(
                commitments
                    .get_committed_by_key(&DaCommitmentKey::from_record(&stale_record))
                    .is_none(),
                "old-incarnation commitment must not reserve fresh-lane identities after replay"
            );
            assert!(
                commitments
                    .bundle_at(old_block.header().height().get())
                    .is_some(),
                "committed block bundle remains available as historical proof material"
            );
        }
        assert!(
            state
                .da_pin_intents()
                .get_by_alias("old-incarnation-pin")
                .is_none(),
            "old-incarnation pin intent must not rehydrate into the fresh lane"
        );

        let restarted = State::new_for_testing(
            World::default(),
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
        );
        {
            let mut nexus = restarted.nexus.write();
            nexus.enabled = true;
            nexus.lane_catalog = two_lane_catalog;
            nexus.lane_config = two_lane_config;
        }
        {
            let mut block_hashes = restarted.block_hashes.block();
            block_hashes.push(old_block.hash());
            block_hashes.commit_for_tests();
        }
        restarted
            .ensure_da_indexes_hydrated()
            .expect("restart should hydrate with lane reset watermark");
        assert!(
            restarted
                .da_commitments()
                .get_by_manifest(&stale_record.manifest_hash)
                .is_none(),
            "persisted reset watermark must suppress old-incarnation commitment after restart"
        );
        assert!(
            restarted
                .da_pin_intents()
                .get_by_alias("old-incarnation-pin")
                .is_none(),
            "persisted reset watermark must suppress old-incarnation pin after restart"
        );
    }

    #[test]
    fn non_nexus_lane_artifact_snapshots_track_only_implicit_default_route() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let foreign_lane = LaneId::new(1);
        let two_lane_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![
                LaneConfig::default(),
                LaneConfig {
                    id: foreign_lane,
                    alias: "foreign-disabled-nexus-lane".to_owned(),
                    ..LaneConfig::default()
                },
            ],
        )
        .expect("two-lane catalog");
        let lane_config = RuntimeLaneConfig::from_catalog(&two_lane_catalog);
        let kura = strict_kura_for_testing(temp_dir.path().join("kura"), &lane_config);
        let state = State::new_for_testing(
            World::default(),
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
        );
        // Poison the disabled catalog deliberately. Snapshot helpers must still
        // trust only the implicit compatibility route, while Kura retains the
        // matching physical lane geometry needed by strict startup.
        install_existing_nexus_geometry_for_test(
            &state,
            iroha_config::parameters::actual::Nexus {
                enabled: false,
                lane_catalog: two_lane_catalog,
                ..Default::default()
            },
        );
        let default_incarnation = state
            .lane_incarnation(LaneId::SINGLE)
            .expect("implicit default lane must have an active incarnation");
        let foreign_incarnation = state
            .lane_incarnation(foreign_lane)
            .expect("foreign physical lane must retain its installed incarnation marker");

        let (default_block, default_session, default_signer_pops) =
            lane_artifact_block_and_session_for_state_test(
                None,
                LaneId::SINGLE,
                DataSpaceId::UNIVERSAL,
                default_incarnation,
                1,
            );
        kura.store_block(Arc::new(default_block.clone()))
            .expect("store default-lane artifact block");
        kura.persist_committed_lane_block_session(&default_session, &default_signer_pops)
            .expect("persist default-lane certified session");
        kura.persist_lane_block_application_receipt(&default_session.proposal)
            .expect("persist default-lane application receipt");
        assert_eq!(
            kura.latest_lane_block_artifact_for_dataspace(LaneId::SINGLE, DataSpaceId::UNIVERSAL,)
                .expect("default raw artifact is readable before foreign fixture")
                .ownership
                .lane_block_descriptor_hash,
            Some(default_session.proposal.descriptor.descriptor_hash),
        );
        assert!(
            kura.read_lane_block_application_receipt(LaneId::SINGLE, 1)
                .is_some(),
            "default application receipt is readable before foreign fixture"
        );
        assert_eq!(
            state.lane_block_artifact_tips_snapshot_cached(),
            vec![(
                LaneId::SINGLE,
                DataSpaceId::UNIVERSAL,
                default_incarnation,
                1,
                Some(default_session.proposal.descriptor.descriptor_hash),
            )],
            "test setup must expose the applied default tip before adding foreign evidence"
        );

        let (foreign_block, foreign_session, foreign_signer_pops) =
            lane_artifact_block_and_session_for_state_test(
                Some(&default_block),
                foreign_lane,
                DataSpaceId::UNIVERSAL,
                foreign_incarnation,
                2,
            );
        kura.store_block(Arc::new(foreign_block.clone()))
            .expect("store foreign-lane artifact block");
        kura.persist_committed_lane_block_session(&foreign_session, &foreign_signer_pops)
            .expect("persist foreign-lane certified session");
        assert!(
            kura.read_lane_block_artifact(LaneId::SINGLE, 1).is_some(),
            "foreign fixture must not overwrite the default raw artifact"
        );
        assert!(
            kura.read_lane_block_artifact(foreign_lane, 2).is_some(),
            "foreign raw artifact is readable at its distinct lane-local height"
        );

        let default_descriptor = &default_session.proposal.descriptor;
        assert_eq!(
            state.lane_block_artifact_tips_snapshot_cached(),
            vec![(
                LaneId::SINGLE,
                DataSpaceId::UNIVERSAL,
                default_incarnation,
                1,
                Some(default_descriptor.descriptor_hash),
            )],
            "disabled Nexus must preserve the applied default-lane artifact tip"
        );
        assert!(
            state
                .unapplied_lane_block_artifact_heights_snapshot_cached()
                .is_empty(),
            "an unapplied foreign-lane artifact must not block non-Nexus proposal readiness"
        );
        assert_eq!(
            state.certified_lane_block_tips_snapshot_cached(),
            vec![(
                LaneId::SINGLE,
                DataSpaceId::UNIVERSAL,
                default_incarnation,
                1,
                Some(default_descriptor.descriptor_hash),
            )],
            "disabled Nexus must preserve only the default-lane certified tip"
        );
        assert_eq!(
            state.certified_lane_block_sessions_snapshot_cached(8),
            vec![default_session.clone()],
            "restart hydration must exclude certified sessions from disabled-catalog lanes"
        );
        assert!(
            state
                .unapplied_certified_lane_block_heights_snapshot_cached()
                .is_empty(),
            "the receipted default session must not be blocked by an unapplied foreign session"
        );

        let (unapplied_default_block, _, _) = lane_artifact_block_and_session_for_state_test(
            Some(&foreign_block),
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            default_incarnation,
            3,
        );
        kura.store_block(Arc::new(unapplied_default_block))
            .expect("store newer unapplied default-lane artifact");
        assert!(
            state.lane_block_artifact_tips_snapshot_cached().is_empty(),
            "an unapplied newest artifact must not be exposed as an extendable tip"
        );
        assert_eq!(
            state.unapplied_lane_block_artifact_heights_snapshot_cached(),
            BTreeMap::from([((LaneId::SINGLE, DataSpaceId::UNIVERSAL), 3)]),
            "an unapplied default-lane artifact must block non-Nexus proposal readiness"
        );
    }

    #[test]
    fn durable_lane_diagnostics_ignore_stale_process_status_caches() {
        struct StatusCacheCleanup;
        impl Drop for StatusCacheCleanup {
            fn drop(&mut self) {
                status::clear_lane_payload_ownerships();
                status::set_committed_lane_blocks(Vec::new());
                status::set_lane_block_sessions(Vec::new());
            }
        }
        let _status_guard = status::rbc_status_test_guard();
        let _status_cache_cleanup = StatusCacheCleanup;
        status::clear_lane_payload_ownerships();
        status::set_committed_lane_blocks(Vec::new());
        status::set_lane_block_sessions(Vec::new());

        let lane_config = RuntimeLaneConfig::from_catalog(&LaneCatalog::default());
        let source_temp_dir = tempfile::tempdir().expect("source temp dir");
        let source_kura =
            strict_kura_for_testing(source_temp_dir.path().join("source-kura"), &lane_config);
        let source_state = State::new_for_testing(
            World::default(),
            Arc::clone(&source_kura),
            LiveQueryStore::start_test(),
        );
        let incarnation = source_state
            .lane_incarnation(LaneId::SINGLE)
            .expect("implicit default lane has an active incarnation");
        let (block, session, signer_pops) = lane_artifact_block_and_session_for_state_test(
            None,
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            incarnation,
            1,
        );
        source_kura
            .store_block(Arc::new(block))
            .expect("store durable diagnostic source block");
        source_kura
            .persist_committed_lane_block_session(&session, &signer_pops)
            .expect("persist durable diagnostic source certificate");
        source_kura
            .persist_lane_block_application_receipt(&session.proposal)
            .expect("persist durable diagnostic source receipt");
        let stale_cache = source_state.durable_lane_diagnostics();
        assert_eq!(stale_cache.lane_payload_ownerships.len(), 1);
        assert_eq!(stale_cache.committed_lane_blocks.len(), 1);
        assert_eq!(stale_cache.lane_block_sessions.len(), 1);

        status::set_lane_payload_ownerships(stale_cache.lane_payload_ownerships.clone());
        status::set_committed_lane_blocks(stale_cache.committed_lane_blocks.clone());
        status::set_lane_block_sessions(stale_cache.lane_block_sessions.clone());
        let process_snapshot = status::snapshot();
        assert_eq!(
            process_snapshot.lane_payload_ownerships,
            stale_cache.lane_payload_ownerships
        );
        assert_eq!(
            process_snapshot.committed_lane_blocks,
            stale_cache.committed_lane_blocks
        );
        assert_eq!(
            process_snapshot.lane_block_sessions,
            stale_cache.lane_block_sessions
        );

        let empty_temp_dir = tempfile::tempdir().expect("empty temp dir");
        let empty_kura =
            strict_kura_for_testing(empty_temp_dir.path().join("empty-kura"), &lane_config);
        let empty_state =
            State::new_for_testing(World::default(), empty_kura, LiveQueryStore::start_test());
        assert_eq!(
            empty_state.durable_lane_diagnostics(),
            crate::sumeragi::status::DurableLaneDiagnosticsSnapshot::default(),
            "durable diagnostics must ignore stale process-static status rows"
        );
    }

    #[test]
    fn durable_lane_diagnostics_reconstruct_after_kura_restart() {
        use crate::sumeragi::status::CommittedLaneBlockExecutionStatus;

        let temp_dir = tempfile::tempdir().expect("temp dir");
        let kura_config =
            strict_kura_config_for_testing(temp_dir.path().join("restart-diagnostics-kura"));
        let lane_config = RuntimeLaneConfig::from_catalog(&LaneCatalog::default());

        let expected = {
            let (kura, _) = Kura::new(&kura_config, &lane_config).expect("initialize Kura");
            let state = State::new_for_testing(
                World::default(),
                Arc::clone(&kura),
                LiveQueryStore::start_test(),
            );
            let incarnation = state
                .lane_incarnation(LaneId::SINGLE)
                .expect("implicit default lane has an active incarnation");
            let (block, session, signer_pops) = lane_artifact_block_and_session_for_state_test(
                None,
                LaneId::SINGLE,
                DataSpaceId::UNIVERSAL,
                incarnation,
                1,
            );
            kura.store_block(Arc::new(block))
                .expect("store restart diagnostic block");
            kura.persist_committed_lane_block_session(&session, &signer_pops)
                .expect("persist restart diagnostic certificate");
            kura.persist_lane_block_application_receipt(&session.proposal)
                .expect("persist restart diagnostic receipt");

            let snapshot = state.durable_lane_diagnostics();
            assert_eq!(snapshot.lane_payload_ownerships.len(), 1);
            assert_eq!(snapshot.committed_lane_blocks.len(), 1);
            assert_eq!(snapshot.lane_block_sessions.len(), 1);
            assert_eq!(
                snapshot.committed_lane_blocks[0].execution_status,
                CommittedLaneBlockExecutionStatus::StateAppliedByCanonicalBlock
            );
            assert!(snapshot.lane_block_sessions[0].committed_session_drained);
            let autonomous = state
                .autonomous_lane_execution_diagnostics()
                .expect("derive restart-stable autonomous diagnostics");
            assert!(
                autonomous.is_empty(),
                "globally anchored lane evidence must not be misclassified as autonomous"
            );
            (snapshot, autonomous)
        };

        let (reopened_kura, _) =
            Kura::new(&kura_config, &lane_config).expect("reopen persistent Kura");
        let restarted_state = State::new_for_testing(
            World::default(),
            reopened_kura,
            LiveQueryStore::start_test(),
        );
        assert_eq!(
            restarted_state.durable_lane_diagnostics(),
            expected.0,
            "a restarted peer must reconstruct the same diagnostic rows from durable evidence"
        );
        assert_eq!(
            restarted_state
                .autonomous_lane_execution_diagnostics()
                .expect("reconstruct autonomous diagnostics after restart"),
            expected.1,
            "autonomous diagnostics must reconstruct from Kura instead of process caches"
        );
    }

    #[test]
    fn autonomous_lane_diagnostic_same_identity_drift_is_conflict() {
        let incarnation = Hash::new(b"autonomous-diagnostic-conflict-incarnation");
        let (_, session, _) = lane_artifact_block_and_session_for_state_test(
            None,
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            incarnation,
            1,
        );
        let mut left =
            AutonomousLaneDiagnosticEvidence::from_proposal(&session.proposal).expect("row");
        left.payload_durable = true;
        left.row.reservation_count = left.row.transaction_count;
        left.row.executable_payload_hash = Some(Hash::new(b"first-payload"));
        let mut right = left.clone();
        right.row.executable_payload_hash = Some(Hash::new(b"conflicting-payload"));
        left.merge(right);
        let row = left.finish();
        assert_eq!(
            row.highest_durable_stage,
            SumeragiAutonomousLaneExecutionStage::Conflict
        );
        assert_eq!(
            row.stuck_reason,
            Some(SumeragiAutonomousLaneExecutionStuckReason::EvidenceConflict)
        );
    }

    #[test]
    fn autonomous_lane_diagnostic_certified_payload_without_bundle_reports_exact_stall() {
        let incarnation = Hash::new(b"autonomous-diagnostic-certified-incarnation");
        let (_, session, _) = lane_artifact_block_and_session_for_state_test(
            None,
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            incarnation,
            1,
        );
        let mut evidence =
            AutonomousLaneDiagnosticEvidence::from_proposal(&session.proposal).expect("row");
        evidence.payload_durable = true;
        evidence.availability_certified = true;
        evidence.lane_certified = true;
        evidence.row.reservation_count = evidence.row.transaction_count;
        evidence.row.executable_payload_hash =
            Some(Hash::new(b"autonomous-diagnostic-certified-payload"));

        let row = evidence.finish();
        assert_eq!(
            row.highest_durable_stage,
            SumeragiAutonomousLaneExecutionStage::LaneCertified
        );
        assert_eq!(
            row.stuck_reason,
            Some(SumeragiAutonomousLaneExecutionStuckReason::CertifiedBundleUnavailable)
        );
        row.validate()
            .expect("certified autonomous payload stall must remain a valid diagnostic row");
    }

    #[test]
    fn autonomous_lane_diagnostic_queue_finalization_is_terminal() {
        let incarnation = Hash::new(b"autonomous-diagnostic-finalized-incarnation");
        let (_, session, _) = lane_artifact_block_and_session_for_state_test(
            None,
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            incarnation,
            1,
        );
        let mut evidence =
            AutonomousLaneDiagnosticEvidence::from_proposal(&session.proposal).expect("row");
        evidence.payload_durable = true;
        evidence.availability_certified = true;
        evidence.lane_certified = true;
        evidence.bundle_durable = true;
        evidence.globally_committed = true;
        evidence.application_receipt = true;
        evidence.queue_finalized = true;
        evidence.row.reservation_count = evidence.row.transaction_count;
        evidence.row.executable_payload_hash =
            Some(Hash::new(b"autonomous-diagnostic-finalized-payload"));
        evidence.row.source_bundle_hash =
            Some(Hash::new(b"autonomous-diagnostic-finalized-bundle"));
        evidence.row.merge_entry_hash = Some(HashOf::from_untyped_unchecked(Hash::new(
            b"autonomous-diagnostic-finalized-merge",
        )));
        evidence.row.application_block_height = Some(9);
        evidence.row.application_block_hash = Some(HashOf::from_untyped_unchecked(Hash::new(
            b"autonomous-diagnostic-finalized-carrier",
        )));

        let row = evidence.finish();
        assert_eq!(
            row.highest_durable_stage,
            SumeragiAutonomousLaneExecutionStage::QueueFinalized
        );
        assert_eq!(row.stuck_reason, None);
        row.validate()
            .expect("queue-finalized autonomous work must be a valid terminal diagnostic row");
    }

    #[test]
    fn lane_lifecycle_same_lane_policy_change_rejects_unapplied_certified_lane_block() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let recreated_lane_id = LaneId::new(1);
        let lane1_config = LaneConfig {
            id: recreated_lane_id,
            alias: "certified-reset".to_string(),
            visibility: LaneVisibility::Public,
            ..LaneConfig::default()
        };
        let two_lane_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![LaneConfig::default(), lane1_config.clone()],
        )
        .expect("two-lane catalog");
        let two_lane_config = RuntimeLaneConfig::from_catalog(&two_lane_catalog);
        let initial_lane_config = RuntimeLaneConfig::from_catalog(&LaneCatalog::default());
        let kura = strict_kura_for_testing(
            temp_dir.path().join("certified-sidecar-reset-kura"),
            &initial_lane_config,
        );
        let state = State::new_for_testing(
            World::default(),
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
        );
        install_existing_nexus_geometry_for_test(
            &state,
            iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog: two_lane_catalog.clone(),
                lane_config: two_lane_config.clone(),
                ..Default::default()
            },
        );

        let keypair = crate::state::checked_keypair();
        let old_block: SignedBlock = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .sign(keypair.private_key())
            .unpack(|_| {})
            .into();
        let old_block_height = old_block.header().height().get();
        kura.store_block(Arc::new(old_block.clone()))
            .expect("store old-incarnation block");
        {
            let mut block_hashes = state.block_hashes.block();
            block_hashes.push(old_block.hash());
            block_hashes.commit_for_tests();
        }
        let stale_lane_incarnation = state
            .lane_incarnation(recreated_lane_id)
            .expect("configured lane must have an active incarnation");

        let (stale_session, stale_signer_pops) = sample_committed_lane_block_session_for_state_test(
            recreated_lane_id,
            DataSpaceId::UNIVERSAL,
            stale_lane_incarnation,
            old_block_height,
            old_block_height,
        );
        kura.persist_committed_lane_block_session(&stale_session, &stale_signer_pops)
            .expect("persist old-incarnation certified lane block");
        assert_eq!(
            state.unapplied_certified_lane_block_height(recreated_lane_id, DataSpaceId::UNIVERSAL),
            Some(old_block_height),
            "test setup should expose the old certified sidecar before lane reset"
        );
        assert_eq!(
            state
                .unapplied_certified_lane_block_heights_snapshot_cached()
                .get(&(recreated_lane_id, DataSpaceId::UNIVERSAL))
                .copied(),
            Some(old_block_height),
            "test setup should expose the old certified sidecar in proposal readiness snapshots before lane reset"
        );
        assert_eq!(
            state.certified_lane_block_sessions_snapshot_cached(8).len(),
            1,
            "test setup should expose the old certified session before lane reset"
        );
        assert_eq!(
            state
                .certified_lane_block_tips_snapshot_cached()
                .into_iter()
                .map(|(_, _, _, height, _)| height)
                .collect::<Vec<_>>(),
            vec![old_block_height],
            "test setup should expose the old certified tip before lane reset"
        );

        let policy_lane_config = LaneConfig {
            visibility: LaneVisibility::Restricted,
            ..lane1_config
        };
        let policy_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![LaneConfig::default(), policy_lane_config.clone()],
        )
        .expect("policy catalog");
        let policy_config = RuntimeLaneConfig::from_catalog(&policy_catalog);
        assert_eq!(
            two_lane_config.shard_id(recreated_lane_id),
            policy_config.shard_id(recreated_lane_id),
            "test setup should keep the reset lane on the same storage shard"
        );
        let nexus_before = state.nexus_snapshot();
        let incarnations_before = state.lane_incarnations_snapshot();
        let lineage_before = state.lane_incarnation_lineage_snapshot();
        let activation_heights_before = state.lane_incarnation_activation_heights_snapshot();
        let error = state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![policy_lane_config],
                retire: vec![recreated_lane_id],
            })
            .expect_err("lifecycle policy replacement must reject unapplied certified work");
        let LaneLifecycleError::Storage(message) = error else {
            panic!("pending certified work should fail through Kura retirement: {error:?}");
        };
        assert!(message.contains("kura journal"), "{message}");
        assert!(
            message.contains("pending certified work targets a retiring lane incarnation"),
            "{message}"
        );
        let nexus_after = state.nexus_snapshot();
        assert_eq!(nexus_after.lane_catalog, nexus_before.lane_catalog);
        assert_eq!(
            nexus_after.dataspace_catalog,
            nexus_before.dataspace_catalog
        );
        assert_eq!(nexus_after.routing_policy, nexus_before.routing_policy);
        assert_eq!(state.lane_incarnations_snapshot(), incarnations_before);
        assert_eq!(state.lane_incarnation_lineage_snapshot(), lineage_before);
        assert_eq!(
            state.lane_incarnation_activation_heights_snapshot(),
            activation_heights_before
        );
        assert_eq!(
            state
                .da_shard_cursors
                .read()
                .canonical_reset_height_for_lane(recreated_lane_id),
            None,
            "rejected reset must not install an in-memory DA reset watermark"
        );
        let da_cursor_journal_path = state.da_shard_cursor_journal_path();
        if da_cursor_journal_path.exists() {
            let journal =
                DaShardCursorJournal::load(&nexus_before.lane_config, &da_cursor_journal_path)
                    .expect("load DA cursor journal after rejected reset");
            assert_eq!(
                journal.canonical_reset_height_for_lane(recreated_lane_id),
                None,
                "rejected reset must not persist a DA reset watermark"
            );
        }

        assert!(
            kura.read_certified_lane_block_artifact(recreated_lane_id, old_block_height)
                .is_some(),
            "rejected reset must preserve the certified sidecar"
        );
        assert_eq!(
            state.unapplied_certified_lane_block_height(recreated_lane_id, DataSpaceId::UNIVERSAL),
            Some(old_block_height),
            "rejected reset must keep pending work visible to scale-in safety checks"
        );
        assert_eq!(
            state.certified_lane_block_sessions_snapshot_cached(8).len(),
            1,
            "rejected reset must preserve the committed lane session"
        );
        assert_eq!(
            state
                .certified_lane_block_tips_snapshot_cached()
                .into_iter()
                .map(|(_, _, _, height, _)| height)
                .collect::<Vec<_>>(),
            vec![old_block_height],
            "rejected reset must preserve the exact incarnation-bound certified tip"
        );
        assert_eq!(
            state
                .unapplied_certified_lane_block_heights_snapshot_cached()
                .get(&(recreated_lane_id, DataSpaceId::UNIVERSAL))
                .copied(),
            Some(old_block_height),
            "rejected reset must preserve proposal-readiness blocking"
        );
    }

    #[test]
    fn canonical_reset_filters_same_incarnation_certified_lane_block_snapshots() {
        let lane_id = LaneId::new(1);
        let lane_config = LaneConfig {
            id: lane_id,
            alias: "canonical-reset-filter".to_string(),
            visibility: LaneVisibility::Public,
            ..LaneConfig::default()
        };
        let lane_catalog =
            LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), lane_config])
                .expect("two-lane catalog");
        let runtime_lane_config = RuntimeLaneConfig::from_catalog(&lane_catalog);
        let kura = Kura::blank_kura_for_testing();
        let mut state = State::new_for_testing(
            World::default(),
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
        );
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog,
                lane_config: runtime_lane_config,
                ..Default::default()
            })
            .expect("apply two-lane nexus catalog");
        let lane_incarnation = state
            .lane_incarnation(lane_id)
            .expect("configured lane must have an active incarnation");

        let reset_height = 1_u64;
        let stale_lane_block_height = 5_u64;
        let (stale_session, stale_signer_pops) = sample_committed_lane_block_session_for_state_test(
            lane_id,
            DataSpaceId::UNIVERSAL,
            lane_incarnation,
            reset_height,
            stale_lane_block_height,
        );
        kura.persist_committed_lane_block_session(&stale_session, &stale_signer_pops)
            .expect("persist same-incarnation pre-reset certified block");
        assert_eq!(
            state
                .certified_lane_block_tips_snapshot_cached()
                .into_iter()
                .map(|(_, _, _, height, _)| height)
                .collect::<Vec<_>>(),
            vec![stale_lane_block_height]
        );
        assert_eq!(
            state.unapplied_certified_lane_block_height(lane_id, DataSpaceId::UNIVERSAL),
            Some(stale_lane_block_height)
        );
        assert!(
            !state.has_pending_merge_execution_sources(),
            "a certified height beyond the exact frontier successor must not keep execution readiness asserted"
        );

        state
            .da_shard_cursors
            .write()
            .mark_lanes_canonically_reset(&BTreeSet::from([lane_id]), reset_height);
        assert!(state.certified_lane_block_tips_snapshot_cached().is_empty());
        assert!(
            state
                .certified_lane_block_sessions_snapshot_cached(8)
                .is_empty()
        );
        assert!(
            state
                .unapplied_certified_lane_block_heights_snapshot_cached()
                .is_empty()
        );
        assert_eq!(
            state.unapplied_certified_lane_block_height(lane_id, DataSpaceId::UNIVERSAL),
            None
        );
        assert!(!state.has_pending_merge_execution_sources());
        assert!(state.canonical_merge_execution_sources().is_none());
        assert!(
            state
                .build_merge_execution_batch(
                    1,
                    BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0),
                )
                .is_none()
        );

        let fresh_proposal_height = reset_height + 1;
        let fresh_lane_block_height = 1_u64;
        let (fresh_session, fresh_signer_pops) = sample_committed_lane_block_session_for_state_test(
            lane_id,
            DataSpaceId::UNIVERSAL,
            lane_incarnation,
            fresh_proposal_height,
            fresh_lane_block_height,
        );
        state
            .persist_committed_lane_block_session_lifecycle_bound(
                &fresh_session,
                &fresh_signer_pops,
            )
            .expect("persist same-incarnation post-reset certified block");
        assert_eq!(
            state
                .latest_certified_lane_block_frontier_sessions_snapshot_cached()
                .into_iter()
                .map(|session| session.proposal.descriptor.lane_block_height)
                .collect::<Vec<_>>(),
            vec![fresh_lane_block_height],
            "the production frontier must cross the reset watermark to the lower fresh lane height"
        );
        assert_eq!(
            state
                .certified_lane_block_tips_snapshot_cached()
                .into_iter()
                .map(|(_, _, _, height, _)| height)
                .collect::<Vec<_>>(),
            vec![fresh_lane_block_height]
        );
        assert_eq!(
            state
                .certified_lane_block_sessions_snapshot_cached(8)
                .into_iter()
                .map(|session| session.proposal.descriptor.lane_block_height)
                .collect::<Vec<_>>(),
            vec![fresh_lane_block_height]
        );
        assert_eq!(
            state
                .unapplied_certified_lane_block_heights_snapshot_cached()
                .get(&(lane_id, DataSpaceId::UNIVERSAL))
                .copied(),
            Some(fresh_lane_block_height)
        );
        assert_eq!(
            state.unapplied_certified_lane_block_height(lane_id, DataSpaceId::UNIVERSAL),
            Some(fresh_lane_block_height)
        );
        assert!(state.has_pending_merge_execution_sources());
    }

    #[test]
    fn lane_lifecycle_same_lane_policy_change_ignores_stale_direct_application_marker_after_reset()
    {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
        let reset_lane_id = LaneId::new(1);
        let lane1_config = LaneConfig {
            id: reset_lane_id,
            alias: "direct-marker-reset".to_string(),
            visibility: LaneVisibility::Public,
            ..LaneConfig::default()
        };
        let two_lane_catalog = LaneCatalog::new(
            nonzero!(2_u32),
            vec![LaneConfig::default(), lane1_config.clone()],
        )
        .expect("two-lane catalog");
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog: two_lane_catalog.clone(),
                ..Default::default()
            })
            .expect("apply initial two-lane nexus catalog");

        let old_block_hash =
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xA7; Hash::LENGTH]));
        state.push_block_hash_for_testing(old_block_hash);
        let reset_height = 1_u64;
        let old_incarnation = state
            .lane_incarnation(reset_lane_id)
            .expect("reset lane has an old incarnation");
        let stale_key = seed_direct_lane_application_marker_for_incarnation(
            &state,
            reset_lane_id,
            old_incarnation,
            DataSpaceId::UNIVERSAL,
            reset_height,
            0xD3,
        );
        assert_eq!(
            state.unrepaired_direct_lane_application_marker_height(reset_lane_id),
            Some(reset_height),
            "test setup should expose the old direct marker before lane reset"
        );

        let policy_lane_config = LaneConfig {
            visibility: LaneVisibility::Restricted,
            ..lane1_config
        };
        state
            .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                additions: vec![policy_lane_config],
                retire: vec![reset_lane_id],
            })
            .expect("same-lane lifecycle policy reset should apply");
        assert_eq!(
            state
                .da_shard_cursors
                .read()
                .canonical_reset_height_for_lane(reset_lane_id),
            Some(reset_height),
            "same-lane policy reset should install the reset watermark"
        );
        assert!(
            state
                .world
                .view()
                .direct_lane_block_application_markers()
                .get(&stale_key)
                .is_none(),
            "same-lane policy reset should prune existing direct markers"
        );

        let stale_reintroduced_key = seed_direct_lane_application_marker_for_incarnation(
            &state,
            reset_lane_id,
            old_incarnation,
            DataSpaceId::UNIVERSAL,
            reset_height,
            0xD4,
        );
        assert!(
            state
                .world
                .view()
                .direct_lane_block_application_markers()
                .get(&stale_reintroduced_key)
                .is_some(),
            "test setup should manually reintroduce stale marker evidence after reset"
        );
        assert_eq!(
            state.unrepaired_direct_lane_application_marker_height(reset_lane_id),
            None,
            "stale pre-reset direct marker evidence must not block the fresh lane"
        );

        let fresh_height = reset_height
            .checked_add(1)
            .expect("fresh direct marker height should fit");
        let fresh_incarnation = state
            .lane_incarnation(reset_lane_id)
            .expect("reset lane has a fresh incarnation");
        seed_direct_lane_application_marker_for_incarnation(
            &state,
            reset_lane_id,
            fresh_incarnation,
            DataSpaceId::UNIVERSAL,
            fresh_height,
            0xD5,
        );
        assert_eq!(
            state.unrepaired_direct_lane_application_marker_height(reset_lane_id),
            Some(fresh_height),
            "fresh post-reset direct marker evidence must still block unsafe scale-in"
        );
    }

    #[test]
