    #[test]
    fn apply_lane_lifecycle_rejects_when_nexus_disabled() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query_handle);
        state.nexus.write().enabled = false;

        let plan = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig::default()],
            retire: Vec::new(),
        };
        let err = state
            .apply_lane_lifecycle(&plan)
            .expect_err("lane lifecycle requires Nexus");
        assert!(matches!(err, LaneLifecycleError::NexusDisabled));
    }

    fn install_lane_manifest_registry(
        state: &State,
        lanes: &[(LaneId, DataSpaceId, Vec<AccountId>)],
    ) {
        let mut statuses = BTreeMap::new();
        for (lane_id, dataspace_id, validators) in lanes {
            let validator_bindings = validators
                .iter()
                .map(|validator| ManifestValidatorBinding {
                    validator: validator.clone(),
                    peer_id: PeerId::from(
                        validator
                            .try_signatory()
                            .expect("manifest test validators must be single-signatory")
                            .clone(),
                    ),
                    torii_url: None,
                })
                .collect();
            let rules = GovernanceRules {
                validators: validators.clone(),
                validator_bindings,
                ..GovernanceRules::default()
            };
            let status = LaneManifestStatus {
                lane: *lane_id,
                alias: format!("lane-{}", lane_id.as_u32()),
                dataspace: *dataspace_id,
                visibility: LaneVisibility::Public,
                storage: LaneStorageProfile::FullReplica,
                governance: Some("parliament".to_string()),
                manifest_path: Some(std::path::PathBuf::from("/tmp/manifest.json")),
                governance_rules: Some(rules),
                privacy_commitments: Vec::new(),
            };
            statuses.insert(*lane_id, status);
        }
        let registry = Arc::new(LaneManifestRegistry::from_statuses(statuses));
        state.install_lane_manifests(&registry);
    }

    fn install_lane_privacy_commitment_fixture(state: &State, private_lane: LaneId) {
        use iroha_crypto::privacy::{LaneCommitmentId, LanePrivacyCommitment, MerkleCommitment};

        let nexus = state.nexus_snapshot();
        let statuses = nexus
            .lane_catalog
            .lanes()
            .iter()
            .map(|lane| {
                let is_private = lane.id == private_lane;
                let status = LaneManifestStatus {
                    lane: lane.id,
                    alias: lane.alias.clone(),
                    dataspace: lane.dataspace_id,
                    visibility: lane.visibility,
                    storage: lane.storage,
                    governance: lane.governance.clone(),
                    manifest_path: is_private
                        .then(|| std::path::PathBuf::from("/tmp/lane-privacy.manifest.json")),
                    governance_rules: None,
                    privacy_commitments: is_private
                        .then(|| {
                            vec![LanePrivacyCommitment::merkle(
                                LaneCommitmentId::new(1),
                                MerkleCommitment::from_root_bytes([0xA5; 32], 12),
                            )]
                        })
                        .unwrap_or_default(),
                };
                (lane.id, status)
            })
            .collect();
        state.install_lane_manifests(&Arc::new(LaneManifestRegistry::from_statuses(statuses)));
    }

    fn install_lane_manifest_registry_for_keypairs(
        state: &State,
        lane_ids: &[LaneId],
        keypairs: &[KeyPair],
    ) {
        let validators = keypairs
            .iter()
            .map(|keypair| AccountId::new(keypair.public_key().clone()))
            .collect::<Vec<_>>();
        let nexus = state.nexus_snapshot();
        let lanes = lane_ids
            .iter()
            .map(|lane_id| {
                let dataspace_id = nexus_catalog_geometry_lane_dataspace(*lane_id, &nexus)
                    .expect("manifest fixture lane must exist in the Nexus catalog");
                (*lane_id, dataspace_id, validators.clone())
            })
            .collect::<Vec<_>>();
        install_lane_manifest_registry(state, &lanes);
    }

    fn install_lane_manifest_registry_with_bindings(
        state: &State,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        validators: Vec<AccountId>,
        validator_bindings: Vec<ManifestValidatorBinding>,
    ) {
        let rules = GovernanceRules {
            validators,
            validator_bindings,
            ..GovernanceRules::default()
        };
        let status = LaneManifestStatus {
            lane: lane_id,
            alias: format!("lane-{}", lane_id.as_u32()),
            dataspace: dataspace_id,
            visibility: LaneVisibility::Public,
            storage: LaneStorageProfile::FullReplica,
            governance: Some("parliament".to_string()),
            manifest_path: Some(std::path::PathBuf::from("/tmp/manifest.json")),
            governance_rules: Some(rules),
            privacy_commitments: Vec::new(),
        };
        let registry = Arc::new(LaneManifestRegistry::from_statuses(BTreeMap::from([(
            lane_id, status,
        )])));
        state.install_lane_manifests(&registry);
    }

