    fn sample_lane_relay_envelope_with_chain_dataspace_view_and_incarnation(
        height: u64,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        chain_id: &ChainId,
        view: u64,
        lane_incarnation: Hash,
        signers: &[&KeyPair],
        signers_bitmap: Vec<u8>,
    ) -> LaneRelayEnvelope {
        let header = BlockHeader::new(
            NonZeroU64::new(height).expect("non-zero height"),
            None,
            None,
            None,
            1_700_000_000_000,
            view,
        );
        let parent_state_root = Hash::new([0xBC; 4]);
        let post_state_root = Hash::new([0xAB; 4]);
        let qc = commit_qc_with_signers(
            &header,
            lane_id,
            dataspace_id,
            parent_state_root,
            post_state_root,
            signers,
            signers_bitmap,
            chain_id,
        );
        let settlement = LaneBlockCommitment {
            block_height: height,
            lane_id,
            lane_incarnation,
            dataspace_id,
            tx_count: 1,
            total_local_amount: "0.000001".parse().expect("valid settlement quantity"),
            total_xor_due: "0.000001".parse().expect("valid settlement quantity"),
            total_xor_after_haircut: "0.000001".parse().expect("valid settlement quantity"),
            total_xor_variance: "0".parse().expect("valid settlement quantity"),
            swap_metadata: None,
            receipts: vec![LaneSettlementReceipt {
                source_id: [0xAA; 32],
                local_amount: "0.000001".parse().expect("valid settlement quantity"),
                xor_due: "0.000001".parse().expect("valid settlement quantity"),
                xor_after_haircut: "0.000001".parse().expect("valid settlement quantity"),
                xor_variance: "0".parse().expect("valid settlement quantity"),
                timestamp_ms: 1_700_000_000_000,
            }],
            nexus_fee_receipts: Vec::new(),
            native_amx_receipts: Vec::new(),
        };
        let envelope = LaneRelayEnvelope::new(header, Some(qc), None, settlement, 0)
            .expect("valid envelope")
            .with_lane_block_descriptor_hash(Some(Hash::new(
                format!(
                    "state-test-lane-descriptor:{}:{}:{height}:{view}",
                    dataspace_id.as_u64(),
                    lane_id.as_u32()
                )
                .as_bytes(),
            )));
        let fastpq_proof = sample_fastpq_proof_material(&envelope, view);
        envelope.with_fastpq_proof_material(Some(fastpq_proof))
    }

    fn lane_relay_committee_for_state_test(
        state: &State,
        height: u64,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
    ) -> Vec<PeerId> {
        let nexus = state.nexus_snapshot();
        let fault_tolerance = nexus
            .dataspace_catalog
            .entries()
            .iter()
            .find(|entry| entry.id == dataspace_id)
            .expect("test dataspace must exist")
            .fault_tolerance;
        let committee_size = usize::try_from(
            fault_tolerance
                .checked_mul(3)
                .and_then(|value| value.checked_add(1))
                .expect("test committee size"),
        )
        .expect("test committee size fits usize");
        let manifest_registry = state.lane_manifests.read().clone();
        let validator_mode = nexus.staking.validator_mode(lane_id, &nexus.lane_catalog);
        let commit_topology = state.commit_topology_snapshot();
        let world = state.world.view();
        let base_pool = State::authoritative_lane_peer_ids_from_sources(
            &world,
            state.chain_id_ref(),
            lane_id,
            validator_mode,
            manifest_registry.as_ref(),
            &nexus,
            &commit_topology,
            height,
        );
        let seed = state.lane_relay_committee_seed(dataspace_id, lane_id, height);
        if base_pool.len() >= committee_size {
            State::lane_relay_committee_from_pool(&base_pool, committee_size, seed)
                .expect("test committee selection")
        } else {
            base_pool
        }
    }

