    #[test]
    fn hydrate_da_indexes_restore_from_journal_without_blocks() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let store_root = temp_dir.path().join("kura");
        let lane_count = nonzero!(1_u32);
        let catalog =
            LaneCatalog::new(lane_count, vec![LaneConfig::default()]).expect("lane catalog");
        let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
        let kura_cfg = KuraConfig {
            init_mode: InitMode::Strict,
            store_dir: WithOrigin::inline(store_root),
            max_disk_usage_bytes: iroha_config::parameters::defaults::kura::MAX_DISK_USAGE_BYTES,
            blocks_in_memory: iroha_config::parameters::defaults::kura::BLOCKS_IN_MEMORY,
            debug_output_new_blocks: false,
            merge_ledger_cache_capacity:
                iroha_config::parameters::defaults::kura::MERGE_LEDGER_CACHE_CAPACITY,
            fsync_mode: iroha_config::kura::FsyncMode::Batched,
            fsync_interval: iroha_config::parameters::defaults::kura::FSYNC_INTERVAL,

            block_sync_roster_retention:
                iroha_config::parameters::defaults::kura::BLOCK_SYNC_ROSTER_RETENTION,
            roster_sidecar_retention:
                iroha_config::parameters::defaults::kura::ROSTER_SIDECAR_RETENTION,
            eviction_required_replicas:
                iroha_config::parameters::defaults::kura::EVICTION_REQUIRED_REPLICAS,
        };
        let (kura, _) = Kura::new(&kura_cfg, &lane_config).expect("init kura");

        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                lane_catalog: catalog.clone(),
                lane_config: lane_config.clone(),
                ..Default::default()
            })
            .expect("apply Nexus catalog for commitment pruning test");

        let record = DaCommitmentRecord::new(
            LaneId::new(0),
            1,
            2,
            BlobDigest::new([0xAA; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]),
            DaProofScheme::MerkleSha256,
            Hash::prehashed([0xCC; 32]),
            None,
            None,
            RetentionClass::default(),
            StorageTicketId::new([0xEE; 32]),
            checked_da_ack_signature(0x11),
        );
        state
            .advance_da_shard_cursors_from_bundle(5, std::slice::from_ref(&record))
            .expect("advance cursor");
        state.persist_da_shard_cursor_journal();
        let journal_path = crate::da::DaShardCursorJournal::journal_path(&kura.store_root());
        assert!(
            journal_path.exists(),
            "journal path should exist after persistence"
        );
        let journal = crate::da::DaShardCursorJournal::load(&lane_config, &journal_path)
            .expect("load journal from disk");
        assert!(
            journal.cursor_for_lane(record.lane_id).is_some(),
            "persisted journal must contain the lane entry"
        );

        drop(state);
        let query_handle = LiveQueryStore::start_test();
        let mut restored_state =
            State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
        restored_state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                lane_catalog: catalog,
                lane_config: lane_config.clone(),
                ..Default::default()
            })
            .expect("apply Nexus catalog after reload");

        restored_state
            .ensure_da_indexes_hydrated()
            .expect("hydrate from journal");
        let cursors = restored_state.da_shard_cursor_index();
        assert!(
            cursors.get(0).is_none(),
            "journal cursors ahead of the canonical replay height must remain inert"
        );
    }

    #[test]
    fn hydrate_da_indexes_skip_ahead_journal_entries() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let store_root = temp_dir.path().join("kura");
        let lane_count = nonzero!(1_u32);
        let catalog =
            LaneCatalog::new(lane_count, vec![LaneConfig::default()]).expect("lane catalog");
        let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
        let kura_cfg = KuraConfig {
            init_mode: InitMode::Strict,
            store_dir: WithOrigin::inline(store_root),
            max_disk_usage_bytes: iroha_config::parameters::defaults::kura::MAX_DISK_USAGE_BYTES,
            blocks_in_memory: iroha_config::parameters::defaults::kura::BLOCKS_IN_MEMORY,
            debug_output_new_blocks: false,
            merge_ledger_cache_capacity:
                iroha_config::parameters::defaults::kura::MERGE_LEDGER_CACHE_CAPACITY,
            fsync_mode: iroha_config::kura::FsyncMode::Batched,
            fsync_interval: iroha_config::parameters::defaults::kura::FSYNC_INTERVAL,

            block_sync_roster_retention:
                iroha_config::parameters::defaults::kura::BLOCK_SYNC_ROSTER_RETENTION,
            roster_sidecar_retention:
                iroha_config::parameters::defaults::kura::ROSTER_SIDECAR_RETENTION,
            eviction_required_replicas:
                iroha_config::parameters::defaults::kura::EVICTION_REQUIRED_REPLICAS,
        };
        let (kura, _) = Kura::new(&kura_cfg, &lane_config).expect("init kura");

        // Seed a journal entry that is ahead of the stored block height.
        {
            let query_handle = LiveQueryStore::start_test();
            let mut state =
                State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
            state
                .set_nexus(iroha_config::parameters::actual::Nexus {
                    lane_catalog: catalog.clone(),
                    lane_config: lane_config.clone(),
                    ..Default::default()
                })
                .expect("apply Nexus catalog for journal seed");
            let record = DaCommitmentRecord::new(
                LaneId::new(0),
                3,
                4,
                BlobDigest::new([0xAA; 32]),
                iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]),
                DaProofScheme::MerkleSha256,
                Hash::prehashed([0xCC; 32]),
                None,
                None,
                RetentionClass::default(),
                StorageTicketId::new([0xEE; 32]),
                checked_da_ack_signature(0x11),
            );
            state
                .advance_da_shard_cursors_from_bundle(5, std::slice::from_ref(&record))
                .expect("advance cursor");
            state.persist_da_shard_cursor_journal();
        }

        // Store a single block to set the latest height below the journal cursor.
        let keypair = crate::state::checked_keypair();
        let block = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .sign(keypair.private_key())
            .unpack(|_| {});
        let signed: SignedBlock = block.into();
        kura.store_block(Arc::new(signed.clone()))
            .expect("store block");

        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                lane_catalog: catalog,
                lane_config,
                ..Default::default()
            })
            .expect("apply Nexus catalog before hydration");
        {
            let mut hashes = state.block_hashes.block();
            hashes.push(signed.hash());
            hashes.commit_for_tests();
        }

        state
            .ensure_da_indexes_hydrated()
            .expect("hydration should skip ahead cursor");
        assert!(
            state.da_shard_cursor_index().is_empty(),
            "ahead-of-height journal entry should be ignored"
        );
    }

    #[test]
    fn commit_roster_journal_restores_status_history() {
        let _guard = status::commit_history_test_guard();
        status::reset_commit_certs_for_tests();
        status::reset_validator_checkpoints_for_tests();
        let state = State::new_for_testing(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        let keypair =
            crate::state::checked_keypair_with_algorithm(iroha_crypto::Algorithm::BlsNormal);
        let peer = PeerId::new(keypair.public_key().clone());
        let block_hash =
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed([0xA1; Hash::LENGTH]));
        let roster = vec![peer];
        let commit_cert = Qc {
            phase: crate::sumeragi::consensus::Phase::Commit,
            subject_block_hash: block_hash,
            parent_state_root: iroha_crypto::Hash::prehashed([0u8; iroha_crypto::Hash::LENGTH]),
            post_state_root: iroha_crypto::Hash::prehashed([0u8; iroha_crypto::Hash::LENGTH]),
            height: 2,
            view: 1,
            epoch: 0,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            mode_tag: crate::sumeragi::consensus::PERMISSIONED_TAG.to_string(),
            highest_qc: None,
            validator_set_hash: HashOf::new(&roster),
            validator_set_hash_version: iroha_data_model::consensus::VALIDATOR_SET_HASH_VERSION_V1,
            validator_set: roster.clone(),
            aggregate: crate::sumeragi::consensus::QcAggregate {
                signers_bitmap: vec![0b0000_0001],
                bls_aggregate_signature: Vec::new(),
            },
        };
        let checkpoint = ValidatorSetCheckpoint::new(
            2,
            commit_cert.view,
            block_hash,
            commit_cert.parent_state_root,
            commit_cert.post_state_root,
            roster,
            vec![0b0000_0001],
            Vec::new(),
            iroha_data_model::consensus::VALIDATOR_SET_HASH_VERSION_V1,
            None,
        );
        {
            let mut journal = state.commit_roster_journal.write();
            journal.upsert(commit_cert.clone(), checkpoint.clone(), None);
        }

        state.restore_commit_roster_history();
        let certs = status::commit_qc_history();
        let checkpoints = status::validator_checkpoint_history();
        assert!(
            certs.iter().any(|cert| cert == &commit_cert),
            "commit certificate should be restored from journal"
        );
        assert!(
            checkpoints.iter().any(|chk| chk == &checkpoint),
            "checkpoint should be restored from journal"
        );
        let view = state.view();
        let stored = view.world().commit_qcs().get(&block_hash);
        assert!(
            stored.is_none(),
            "commit-roster journal restore must not pre-populate WSV commit QC storage"
        );
        status::reset_commit_certs_for_tests();
        status::reset_validator_checkpoints_for_tests();
    }

    #[test]
    fn apply_without_execution_canonicalizes_commit_roster_signatures() {
        let _guard = status::commit_history_test_guard();
        status::reset_commit_certs_for_tests();
        status::reset_validator_checkpoints_for_tests();
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);

        let kp_a = crate::state::checked_keypair_with_algorithm(iroha_crypto::Algorithm::BlsNormal);
        let kp_b = crate::state::checked_keypair_with_algorithm(iroha_crypto::Algorithm::BlsNormal);
        let roster = vec![
            PeerId::new(kp_a.public_key().clone()),
            PeerId::new(kp_b.public_key().clone()),
        ];

        let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 1);
        let signed_block = iroha_data_model::block::builder::BlockBuilder::new(header)
            .build_with_signature(1, kp_b.private_key());

        let mut state_block = state.block(signed_block.header());
        let valid = ValidBlock::validate_unchecked(signed_block, &mut state_block).unpack(|_| {});
        let committed = valid.commit_unchecked().unpack(|_| {});
        let signers_bitmap = signer_bitmap(&[0, 1], roster.len());
        let zero_root = iroha_crypto::Hash::prehashed([0u8; iroha_crypto::Hash::LENGTH]);
        let height = committed.as_ref().header().height().get();
        let view = committed.as_ref().header().view_change_index();
        let vote = crate::sumeragi::consensus::Vote {
            phase: crate::sumeragi::consensus::Phase::Commit,
            block_hash: committed.as_ref().hash(),
            parent_state_root: zero_root,
            post_state_root: zero_root,
            height,
            view,
            epoch: 0,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            highest_qc: None,
            signer: 0,
            bls_sig: Vec::new(),
        };
        let preimage = crate::sumeragi::consensus::vote_preimage(
            &super::DEFAULT_TEST_CHAIN_ID,
            crate::sumeragi::consensus::PERMISSIONED_TAG,
            &vote,
        );
        let signatures: Vec<Vec<u8>> = [kp_a, kp_b]
            .iter()
            .map(|kp| {
                Signature::try_new(kp.private_key(), &preimage)
                    .expect("test fixture signing should succeed")
                    .payload()
                    .to_vec()
            })
            .collect();
        let sig_refs: Vec<&[u8]> = signatures.iter().map(Vec::as_slice).collect();
        let aggregate_signature = iroha_crypto::bls_normal_aggregate_signatures(&sig_refs)
            .expect("aggregate commit QC signatures");
        let commit_cert = Qc {
            phase: crate::sumeragi::consensus::Phase::Commit,
            subject_block_hash: committed.as_ref().hash(),
            parent_state_root: zero_root,
            post_state_root: zero_root,
            height,
            view,
            epoch: 0,
            chain_order_hash: crate::sumeragi::consensus::default_chain_order_hash(),
            rechain_seq: 0,
            mode_tag: crate::sumeragi::consensus::PERMISSIONED_TAG.to_string(),
            highest_qc: None,
            validator_set_hash: HashOf::new(&roster),
            validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
            validator_set: roster.clone(),
            aggregate: crate::sumeragi::consensus::QcAggregate {
                signers_bitmap: signers_bitmap.clone(),
                bls_aggregate_signature: aggregate_signature,
            },
        };
        status::record_commit_qc(commit_cert.clone());
        let _ = state_block.apply_without_execution_with_commit_qc(
            &committed,
            roster,
            Some(&commit_cert),
        );
        state_block.commit().expect("commit");

        let certs = status::commit_qc_history();
        let cert = certs.first().expect("commit certificate recorded");
        assert_eq!(cert.height, committed.as_ref().header().height().get());
        assert_eq!(cert.aggregate.signers_bitmap, signers_bitmap);
        let view = state.view();
        let stored = view.world().commit_qcs().get(&committed.as_ref().hash());
        assert_eq!(
            stored,
            Some(cert),
            "commit certificate should be recorded in world storage"
        );

        status::reset_commit_certs_for_tests();
        status::reset_validator_checkpoints_for_tests();
    }

