        let canonical_block = Arc::new(SignedBlock::presigned(signature, header, Vec::new()));
        let block_hash = canonical_block.hash();
        kura.store_block(Arc::clone(&canonical_block))
            .expect("store canonical block");
        let roster = vec![peer];
