    #[test]
    fn da_pin_intents_replay_sanitizes_invalid_entries() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let store_root = temp_dir.path().join("kura");
        let lane_count = nonzero!(1_u32);

        let catalog =
            LaneCatalog::new(lane_count, vec![LaneConfig::default()]).expect("lane catalog");
        let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
        let kura_cfg = KuraConfig {
            init_mode: InitMode::Strict,
            store_dir: WithOrigin::inline(store_root),
            max_disk_usage_bytes: iroha_config::parameters::defaults::kura::MAX_DISK_USAGE_BYTES,
            blocks_in_memory: iroha_config::parameters::defaults::kura::BLOCKS_IN_MEMORY,
            debug_output_new_blocks: false,
            merge_ledger_cache_capacity:
                iroha_config::parameters::defaults::kura::MERGE_LEDGER_CACHE_CAPACITY,
            fsync_mode: iroha_config::kura::FsyncMode::Batched,
            fsync_interval: iroha_config::parameters::defaults::kura::FSYNC_INTERVAL,

            block_sync_roster_retention:
                iroha_config::parameters::defaults::kura::BLOCK_SYNC_ROSTER_RETENTION,
            roster_sidecar_retention:
                iroha_config::parameters::defaults::kura::ROSTER_SIDECAR_RETENTION,
            eviction_required_replicas:
                iroha_config::parameters::defaults::kura::EVICTION_REQUIRED_REPLICAS,
        };
        let (kura, _) = Kura::new(&kura_cfg, &lane_config).expect("init kura");
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);

        let lane = lane_config.primary().lane_id;

        let mut superseded = DaPinIntent::new(
            lane,
            1,
            1,
            StorageTicketId::new([0x01; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x01; 32]),
        );
        superseded.alias = Some("alias-one".to_string());

        let mut winner = DaPinIntent::new(
            lane,
            2,
            0,
            StorageTicketId::new([0x02; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x02; 32]),
        );
        winner.alias = Some("alias-one".to_string());

        let mut zero_manifest = DaPinIntent::new(
            lane,
            3,
            0,
            StorageTicketId::new([0x03; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0; 32]),
        );
        zero_manifest.alias = Some("alias-drop".to_string());

        let plain = DaPinIntent::new(
            lane,
            4,
            0,
            StorageTicketId::new([0x04; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x04; 32]),
        );

        let bundle = DaPinIntentBundle::new(vec![
            superseded.clone(),
            winner.clone(),
            zero_manifest,
            plain.clone(),
        ]);
        let keypair = crate::state::checked_keypair();
        let new_block = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .with_da_pin_intents(Some(bundle))
            .sign(keypair.private_key())
            .unpack(|_| {});
        let signed_block: SignedBlock = new_block.into();
        kura.store_block(Arc::new(signed_block.clone()))
            .expect("store block");

        let mut block_hashes = state.block_hashes.block();
        block_hashes.push(signed_block.hash());
        block_hashes.commit_for_tests();

        let store = state.da_pin_intents();
        let collected: Vec<_> = store.all_sorted().cloned().collect();
        drop(store);

        assert_eq!(collected.len(), 2);
        assert!(
            collected
                .iter()
                .any(|intent| intent.intent.storage_ticket == winner.storage_ticket)
        );
        assert!(
            collected
                .iter()
                .any(|intent| intent.intent.storage_ticket == plain.storage_ticket)
        );
        assert_eq!(
            state
                .da_pin_intents()
                .get_by_alias("alias-one")
                .map(|(ticket, _)| ticket),
            Some(&winner.storage_ticket)
        );
    }

    #[test]
    fn da_pin_intents_drop_missing_owner_accounts() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), kura, query_handle);
        let lane_count = nonzero!(1_u32);
        let catalog =
            LaneCatalog::new(lane_count, vec![LaneConfig::default()]).expect("lane catalog");
        let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                lane_catalog: catalog,
                lane_config,
                ..Default::default()
            })
            .expect("configure nexus");
        let lane_id = state.nexus_snapshot().lane_config.primary().lane_id;
        let (missing_owner_id, _) = gen_account_in("missing-owner");

        let mut missing_owner = DaPinIntent::new(
            lane_id,
            6,
            0,
            StorageTicketId::new([0x10; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x20; 32]),
        );
        missing_owner.owner = Some(missing_owner_id);

        let mut valid = DaPinIntent::new(
            lane_id,
            6,
            1,
            StorageTicketId::new([0x30; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x40; 32]),
        );
        valid.alias = Some("kept-alias".to_string());

        let bundle = DaPinIntentBundle::new(vec![missing_owner.clone(), valid.clone()]);
        let keypair = crate::state::checked_keypair();
        let new_block = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .with_da_pin_intents(Some(bundle))
            .sign(keypair.private_key())
            .unpack(|_| {});
        let signed_block: SignedBlock = new_block.into();
        let mut state_block = state.block(signed_block.header());
        let valid_block = ValidBlock::validate_unchecked(signed_block, &mut state_block);
        let committed = valid_block.unpack(|_| {}).commit_unchecked().unpack(|_| {});
        let _ = state_block.apply_without_execution(&committed, Vec::new());
        state_block.commit().expect("commit state block");

        let view = state.view();
        let world = view.world();
        assert!(
            world
                .da_pin_intents_by_ticket()
                .get(&missing_owner.storage_ticket)
                .is_none(),
            "intent with unknown owner must not be persisted"
        );
        let stored = world
            .da_pin_intents_by_ticket()
            .get(&valid.storage_ticket)
            .expect("valid intent stored");
        assert_eq!(stored.intent, valid);
        assert_eq!(
            world.da_pin_intents_by_alias().get("kept-alias"),
            Some(&valid.storage_ticket)
        );
    }

    #[test]
    fn da_pin_intents_persist_into_world_indexes() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), kura, query_handle);
        let lane_count = nonzero!(1_u32);
        let catalog =
            LaneCatalog::new(lane_count, vec![LaneConfig::default()]).expect("lane catalog");
        let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
        let lane_id = lane_config.primary().lane_id;
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                lane_catalog: catalog,
                lane_config,
                ..Default::default()
            })
            .expect("configure nexus");

        let mut intent = DaPinIntent::new(
            lane_id,
            5,
            0,
            StorageTicketId::new([0xCC; 32]),
            iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xDD; 32]),
        );
        intent.alias = Some("persist-alias".to_string());

        let bundle = DaPinIntentBundle::new(vec![intent.clone()]);
        let keypair = crate::state::checked_keypair();
        let new_block = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .with_da_pin_intents(Some(bundle))
            .sign(keypair.private_key())
            .unpack(|_| {});
        let signed_block: SignedBlock = new_block.into();
        let mut state_block = state.block(signed_block.header());
        let valid = ValidBlock::validate_unchecked(signed_block, &mut state_block).unpack(|_| {});
        let committed = valid.commit_unchecked().unpack(|_| {});
        let _ = state_block.apply_without_execution(&committed, Vec::new());
        state_block.commit().expect("commit state block");

        {
            let view = state.view();
            let world = view.world();
            let stored = world
                .da_pin_intents_by_ticket()
                .get(&intent.storage_ticket)
                .expect("pin intent stored by ticket");
            assert_eq!(stored.intent, intent);
            assert_eq!(stored.location.index_in_bundle, 0);
            assert_eq!(
                world.da_pin_intents_by_alias().get("persist-alias"),
                Some(&intent.storage_ticket)
            );
            assert_eq!(
                world
                    .da_pin_intents_by_manifest()
                    .get(&intent.manifest_hash),
                Some(&intent.storage_ticket)
            );
            assert_eq!(
                world.da_pin_intents_by_lane_epoch().get(&(
                    intent.lane_id,
                    intent.epoch,
                    intent.sequence
                )),
                Some(&intent.storage_ticket)
            );

            use iroha_data_model::query::da::prelude::{
                FindDaPinIntentByAlias, FindDaPinIntentByLaneEpochSequence,
                FindDaPinIntentByManifest, FindDaPinIntentByTicket,
            };

            use crate::smartcontracts::ValidSingularQuery;

            let ticket = intent.storage_ticket;
            let manifest_hash = intent.manifest_hash;
            let alias = intent.alias.clone().expect("alias assigned");
            let lane_id = intent.lane_id;
            let epoch = intent.epoch;
            let sequence = intent.sequence;

            let by_ticket = FindDaPinIntentByTicket {
                storage_ticket: ticket,
            };
            let record = by_ticket
                .execute(&view)
                .expect("query by storage ticket should succeed");
            assert_eq!(record.intent, intent);

            let by_manifest = FindDaPinIntentByManifest { manifest_hash };
            let manifest_record = by_manifest
                .execute(&view)
                .expect("query by manifest should succeed");
            assert_eq!(manifest_record.intent.storage_ticket, ticket);

            let by_alias = FindDaPinIntentByAlias { alias };
            let alias_record = by_alias
                .execute(&view)
                .expect("query by alias should succeed");
            assert_eq!(alias_record.intent.storage_ticket, ticket);

            let by_lane_epoch = FindDaPinIntentByLaneEpochSequence {
                lane_id,
                epoch,
                sequence,
            };
            let lane_record = by_lane_epoch
                .execute(&view)
                .expect("query by lane/epoch/sequence should succeed");
            assert_eq!(lane_record.intent.manifest_hash, manifest_hash);
        }
    }

    #[test]
    fn da_pin_intent_ingest_rejects_future_created_autoscale_lane() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query_handle);
        let future_created_lane = LaneId::new(1);
        let elastic_lane =
            autoscale_elastic_lane_config(future_created_lane, DataSpaceId::UNIVERSAL, 7);
        let catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), elastic_lane])
            .expect("future-created autoscale lane catalog");
        {
            let mut nexus = state.nexus.write();
            nexus.enabled = true;
            nexus.autoscale.enabled = true;
            nexus.autoscale.min_lanes = nonzero!(1_u32);
            nexus.autoscale.max_lanes = nonzero!(3_u32);
            nexus.lane_config = RuntimeLaneConfig::from_catalog(&catalog);
            nexus.lane_catalog = catalog;
        }

        let mut early = DaPinIntent::new(
            future_created_lane,
            1,
            0,
            StorageTicketId::new([0xE1; 32]),
            ManifestDigest::new([0xE2; 32]),
        );
        early.alias = Some("future-created-autoscale-pin".to_owned());
        let inserted = state.ingest_pin_intents(6, vec![early], "future-created-test");
        assert!(
            inserted.is_empty(),
            "pin intents must not be indexed before the autoscale lane creation height"
        );
        assert!(
            state
                .da_pin_intents()
                .get_by_alias("future-created-autoscale-pin")
                .is_none()
        );

        let mut active = DaPinIntent::new(
            future_created_lane,
            1,
            1,
            StorageTicketId::new([0xE3; 32]),
            ManifestDigest::new([0xE4; 32]),
        );
        active.alias = Some("active-autoscale-pin".to_owned());
        let inserted = state.ingest_pin_intents(7, vec![active.clone()], "future-created-test");
        assert_eq!(inserted.len(), 1);
        assert_eq!(inserted[0].intent, active);
        assert_eq!(inserted[0].location.block_height, 7);
        assert!(
            state
                .da_pin_intents()
                .get_by_alias("active-autoscale-pin")
                .is_some()
        );
    }

