    #[test]
    fn time_trigger_failure_populates_entrypoint_instructions() -> Result<()> {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query);

        let header = BlockHeader::new(NonZeroU64::new(1).unwrap(), None, None, None, 0, 0);
        let mut state_block = state.block(header);

        {
            let mut stx = state_block.transaction();
            let domain_id: DomainId = DomainId::try_new("wonderland", "universal")?;
            Register::domain(Domain::new(domain_id.clone()))
                .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
            Register::asset_definition({
                let __asset_definition_id = iroha_data_model::asset::AssetDefinitionId::new(
                    DomainId::try_new("wonderland", "universal")?,
                    "rose".parse()?,
                );
                AssetDefinition::numeric(__asset_definition_id.clone())
                    .with_name(__asset_definition_id.name().to_string())
            })
            .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
            stx.apply();
        }

        let trigger_id: TriggerId = "failing_time_trigger".parse()?;
        let asset_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::new(
            DomainId::try_new("wonderland", "universal")?,
            "rose".parse()?,
        );
        let alice_asset = AssetId::new(asset_def_id.clone(), ALICE_ID.clone());
        let failing_instruction: InstructionBox =
            Transfer::asset_quantity(alice_asset, 1_u32, BOB_ID.clone()).into();
        let trigger = Trigger::new(
            trigger_id.clone(),
            Action::new(
                vec![failing_instruction.clone()],
                Repeats::Exactly(1),
                ALICE_ID.clone(),
                TimeEventFilter(ExecutionTime::Schedule(Schedule {
                    start_ms: 0,
                    period_ms: Some(1_000),
                })),
            ),
        );

        {
            let mut stx = state_block.transaction();
            Register::trigger(trigger).execute(&ALICE_ID, &mut stx)?;
            stx.apply();
        }

        let time_event = state_block.create_time_event(&header);
        let action = {
            state_block
                .world
                .triggers()
                .time_triggers()
                .get(&trigger_id)
                .expect("time trigger registered")
                .clone()
        };

        let (entrypoint, result) =
            state_block.execute_time_trigger(&trigger_id, &action, &time_event, 0);

        assert!(result.is_err(), "expected trigger execution to fail");
        let expected_step = ExecutionStep(ConstVec::from(vec![failing_instruction]));
        assert_eq!(entrypoint.instructions, expected_step);
        assert_eq!(entrypoint.id, trigger_id);
        assert_eq!(entrypoint.authority, *ALICE_ID);

        Ok(())
    }

    #[test]
    fn time_trigger_same_id_reschedule_keeps_new_repeat_budget() -> Result<()> {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query);

        let block1 = new_dummy_block_with_payload(|h| {
            h.set_height(NonZeroU64::new(1).unwrap());
            h.creation_time_ms = 0;
        });
        let mut state_block = state.block(block1.as_ref().header());
        let trigger_id: TriggerId = "self_reschedule".parse()?;
        {
            let mut stx = state_block.transaction();
            let domain_id: DomainId = DomainId::try_new("wonderland", "universal")?;
            Register::domain(Domain::new(domain_id))
                .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;

            let replacement_schedule = Schedule {
                start_ms: 10_000,
                period_ms: None,
            };
            let replacement_trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    Vec::<InstructionBox>::new(),
                    Repeats::Exactly(1),
                    ALICE_ID.clone(),
                    TimeEventFilter(ExecutionTime::Schedule(replacement_schedule)),
                ),
            );
            let instructions = vec![
                InstructionBox::from(Unregister::trigger(trigger_id.clone())),
                InstructionBox::from(Register::trigger(replacement_trigger)),
            ];
            let trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    instructions,
                    Repeats::Exactly(1),
                    ALICE_ID.clone(),
                    TimeEventFilter(ExecutionTime::Schedule(Schedule {
                        start_ms: 0,
                        period_ms: None,
                    })),
                ),
            );
            Register::trigger(trigger).execute(&ALICE_ID, &mut stx)?;
            stx.apply();
        }
        let _ = state_block.apply_without_execution(&block1, Vec::new());
        state_block.commit()?;

        let block2 = new_dummy_block_with_payload(|h| {
            h.set_height(NonZeroU64::new(2).unwrap());
            h.creation_time_ms = 2;
        });
        let mut state_block = state.block(block2.as_ref().header());
        let time_event = state_block.create_time_event(&block2.as_ref().header());
        let original_action = state_block
            .world
            .triggers()
            .time_triggers()
            .get(&trigger_id)
            .expect("original trigger should be registered")
            .clone();
        let (_entrypoint, result) =
            state_block.execute_time_trigger(&trigger_id, &original_action, &time_event, 0);
        assert!(
            result.is_ok(),
            "self-rescheduling trigger should execute successfully: {:?}",
            result
        );

        let action = state_block
            .world
            .triggers()
            .time_triggers()
            .get(&trigger_id)
            .expect("replacement trigger should remain registered");
        assert_eq!(action.repeats, Repeats::Exactly(1));
        assert_eq!(
            action
                .metadata()
                .get(&"__registered_block_height".parse::<Name>()?)
                .and_then(|json| json.try_into_any_norito::<u64>().ok()),
            Some(2)
        );
        match action.filter.0 {
            ExecutionTime::Schedule(schedule) => {
                assert_eq!(schedule.start_ms, 10_000);
                assert_eq!(schedule.period_ms, None);
            }
            ExecutionTime::PreCommit => panic!("expected replacement schedule"),
        }

        Ok(())
    }

    #[test]
    fn time_trigger_nft_seq_base_strides_by_256() {
        let base0 = StateBlock::time_trigger_nft_seq_base(42, 0);
        let base1 = StateBlock::time_trigger_nft_seq_base(42, 1);
        let base2 = StateBlock::time_trigger_nft_seq_base(42, 2);
        assert_eq!(base1, base0.saturating_add(256));
        assert_eq!(base2, base1.saturating_add(256));

        let next_block = StateBlock::time_trigger_nft_seq_base(43, 0);
        assert!(next_block > base2);
    }

    #[test]
    fn create_time_event_clamps_on_time_regression() {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query);

        let block1 = new_dummy_block_with_payload(|h| {
            h.set_height(NonZeroU64::new(1).unwrap());
            h.creation_time_ms = 2_000;
        });
        let mut state_block1 = state.block(block1.as_ref().header());
        let _ = state_block1.apply_without_execution(&block1, Vec::new());
        state_block1.commit().unwrap();

        let block2 = new_dummy_block_with_payload(|h| {
            h.set_height(NonZeroU64::new(2).unwrap());
            h.creation_time_ms = 1_000;
        });
        let header2 = block2.as_ref().header();
        let state_block2 = state.block(header2);
        let header2_for_event = block2.as_ref().header();
        let time_event = state_block2.create_time_event(&header2_for_event);

        assert_eq!(time_event.interval.since(), Duration::from_millis(1_000));
        assert_eq!(time_event.interval.length(), Duration::ZERO);
    }

    #[test]
    fn time_triggers_due_for_block_detects_precommit_trigger() -> Result<()> {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query);

        let header1 = BlockHeader::new(NonZeroU64::new(1).unwrap(), None, None, None, 0, 0);
        let mut state_block1 = state.block(header1);
        {
            let mut stx = state_block1.transaction();
            let domain_id: DomainId = DomainId::try_new("wonderland", "universal")?;
            Register::domain(Domain::new(domain_id.clone()))
                .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&SAMPLE_GENESIS_ACCOUNT_ID, &mut stx)?;
            let trigger = Trigger::new(
                "precommit_probe".parse()?,
                Action::new(
                    vec![InstructionBox::from(Log::new(
                        Level::INFO,
                        "probe".to_owned(),
                    ))],
                    Repeats::Exactly(1),
                    ALICE_ID.clone(),
                    TimeEventFilter::new(ExecutionTime::PreCommit),
                ),
            );
            Register::trigger(trigger).execute(&ALICE_ID, &mut stx)?;
            stx.apply();
        }
        state_block1.commit().unwrap();

        let header2 = BlockHeader::new(NonZeroU64::new(2).unwrap(), None, None, None, 0, 0);
        let view = state.view();
        assert_eq!(
            state.time_triggers_due_for_block_fast(&header2),
            view.time_triggers_due_for_block(&header2),
            "fast helper should match StateView trigger checks"
        );
        assert!(
            state.time_triggers_due_for_block_fast(&header2),
            "precommit triggers should be due for the next block via fast helper"
        );
        assert!(
            view.time_triggers_due_for_block(&header2),
            "precommit triggers should be due for the next block"
        );

        Ok(())
    }

