    #[test]
    fn block_does_not_advance_sweep_marker_after_partial_release_failure() {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query);
        let referendum_id = "partial-release-failure".to_owned();
        let released_voter = (*ALICE_ID).clone();
        let retained_voter = (*BOB_ID).clone();

        {
            let mut world_block = state.world.block();
            let mut locks = GovernanceLocksForReferendum::default();
            locks.locks.insert(
                released_voter.clone(),
                GovernanceLockRecord {
                    owner: released_voter.clone(),
                    amount: Quantity::from(1_u32),
                    slashed: Quantity::zero(),
                    expiry_height: 5,
                    direction: 0,
                    duration_blocks: 0,
                    custody: Some(GovernanceLockCustody {
                        escrowed: false,
                        asset_definition_id: state.gov.voting_asset_id.clone(),
                        bond_escrow_account: state.gov.bond_escrow_account.clone(),
                        slash_receiver_account: state.gov.slash_receiver_account.clone(),
                    }),
                },
            );
            locks.locks.insert(
                retained_voter.clone(),
                GovernanceLockRecord {
                    owner: retained_voter.clone(),
                    amount: Quantity::from(1_u32),
                    slashed: Quantity::zero(),
                    expiry_height: 5,
                    direction: 0,
                    duration_blocks: 0,
                    custody: Some(GovernanceLockCustody {
                        escrowed: true,
                        asset_definition_id: state.gov.voting_asset_id.clone(),
                        bond_escrow_account: state.gov.bond_escrow_account.clone(),
                        slash_receiver_account: state.gov.slash_receiver_account.clone(),
                    }),
                },
            );
            world_block
                .governance_locks
                .insert(referendum_id.clone(), locks);
            *world_block.governance_last_unlock_sweep_height.get_mut() = 1;
            world_block.commit();
        }

        let header = BlockHeader::new(nonzero!(10_u64), None, None, None, 0, 0);
        let block = state.block(header);
        let locks_after = block
            .world
            .governance_locks
            .get(&referendum_id)
            .expect("referendum lock container remains");
        assert!(
            !locks_after.locks.contains_key(&released_voter),
            "successful release in a partial sweep must still be applied"
        );
        assert!(
            locks_after.locks.contains_key(&retained_voter),
            "failed release in a partial sweep must remain retryable"
        );
        assert_eq!(
            *block.world.governance_last_unlock_sweep_height, 1,
            "an incomplete sweep must not advance the successful sweep marker"
        );
    }

    #[test]
    fn transaction_failure_rolls_back_asset_world_and_trigger_changes() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query_handle);

        let header = BlockHeader::new(NonZeroU64::new(1).unwrap(), None, None, None, 0, 0);
        let mut state_block = state.block(header);
        let mut stx = state_block.transaction();

        let domain_id: DomainId = DomainId::try_new("wonderland", "universal").unwrap();
        Register::domain(Domain::new(domain_id.clone()))
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
        Register::account(new_sample_account(&ALICE_ID))
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
        Grant::account_permission(
            iroha_executor_data_model::permission::trigger::CanRegisterTrigger {
                authority: ALICE_ID.clone(),
            },
            ALICE_ID.clone(),
        )
        .execute(&ALICE_ID, &mut stx)
        .unwrap();
        let asset_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::new(
            DomainId::try_new("wonderland", "universal").unwrap(),
            "rose".parse().unwrap(),
        );
        Register::asset_definition({
            let __asset_definition_id = asset_def_id.clone();
            AssetDefinition::numeric(__asset_definition_id.clone())
                .with_name(__asset_definition_id.name().to_string())
        })
        .execute(&ALICE_ID, &mut stx)
        .unwrap();

        stx.apply();
        state_block.commit().unwrap();

        let asset_id = AssetId::new(asset_def_id.clone(), ALICE_ID.clone());
        let key: Name = "temp".parse().unwrap();
        let trigger_id: TriggerId = "rollback_guard".parse().unwrap();

        {
            let header = BlockHeader::new(NonZeroU64::new(2).unwrap(), None, None, None, 0, 0);
            let mut state_block = state.block(header);
            {
                let mut stx = state_block.transaction();
                Mint::asset_quantity(1_u32, asset_id.clone())
                    .execute(&ALICE_ID, &mut stx)
                    .unwrap();
                SetKeyValue::account(
                    ALICE_ID.clone(),
                    key.clone(),
                    Json::from(norito::json!("temp")),
                )
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
                let trigger_action = Action::new(
                    vec![InstructionBox::from(Burn::asset_quantity(
                        1_u32,
                        asset_id.clone(),
                    ))],
                    Repeats::Exactly(1),
                    ALICE_ID.clone(),
                    ExecuteTriggerEventFilter::new()
                        .for_trigger(trigger_id.clone())
                        .under_authority(ALICE_ID.clone()),
                );
                Register::trigger(Trigger::new(trigger_id.clone(), trigger_action))
                    .execute(&ALICE_ID, &mut stx)
                    .unwrap();
                let duplicate = Register::asset_definition({
                    let __asset_definition_id = asset_def_id.clone();
                    AssetDefinition::numeric(__asset_definition_id.clone())
                        .with_name(__asset_definition_id.name().to_string())
                })
                .execute(&ALICE_ID, &mut stx);
                assert!(
                    duplicate.is_err(),
                    "expected duplicate asset definition to fail"
                );
            }
        }

        let view = state.view();
        assert!(
            view.world.asset(&asset_id).is_err(),
            "asset mint should not persist after transaction failure"
        );
        let metadata = view
            .world
            .map_account(&ALICE_ID, |account| {
                account.value().metadata().get(&key).cloned()
            })
            .unwrap();
        assert!(
            metadata.is_none(),
            "account metadata change should rollback on failure"
        );
        assert!(
            view.world.triggers().ids().get(&trigger_id).is_none(),
            "trigger registration should rollback on failure"
        );
    }

    #[test]
    fn execute_called_trigger_failure_rolls_back_state() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query_handle);

        let trigger_id: TriggerId = "rollback_trigger".parse().unwrap();
        let asset_definition_id: AssetDefinitionId =
            iroha_data_model::asset::AssetDefinitionId::new(
                DomainId::try_new("wonderland", "universal").unwrap(),
                "xor".parse().unwrap(),
            );

        // Commit initial domain, account, and the by-call trigger.
        let block = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(1).unwrap());
        });
        {
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();
            Register::domain(Domain::new(
                DomainId::try_new("wonderland", "universal").unwrap(),
            ))
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            let create_asset = Register::asset_definition({
                let __asset_definition_id = asset_definition_id.clone();
                AssetDefinition::numeric(__asset_definition_id.clone())
                    .with_name(__asset_definition_id.name().to_string())
            });
            let fail_isi = Unregister::domain(DomainId::try_new("dummy", "universal").unwrap());
            let instructions: [InstructionBox; 2] = [create_asset.into(), fail_isi.into()];
            let trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    instructions,
                    Repeats::Indefinitely,
                    ALICE_ID.clone(),
                    ExecuteTriggerEventFilter::new()
                        .for_trigger(trigger_id.clone())
                        .under_authority(ALICE_ID.clone()),
                ),
            );
            Register::trigger(trigger)
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            stx.apply();
            state_block.commit().unwrap();
        }

        // Execute the trigger and expect rejection; state changes must rollback.
        let block = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(2).unwrap());
        });
        {
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();
            let event = ExecuteTriggerEvent {
                trigger_id: trigger_id.clone(),
                authority: ALICE_ID.clone(),
                args: Json::default(),
            };
            let err = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("trigger should fail to execute");
            match err {
                TransactionRejectionReason::Validation(
                    ValidationFail::InstructionFailed(InstructionExecutionError::Find(
                        FindError::Domain(_),
                    ))
                    | ValidationFail::NotPermitted(_),
                ) => {}
                other => panic!("unexpected rejection: {other:?}"),
            }
        }

        let view = state.view();
        assert!(
            view.world.asset_definition(&asset_definition_id).is_err(),
            "asset definition created by a failing trigger must not persist",
        );
    }

    #[test]
    fn self_calling_trigger_stops_at_synchronous_execution_depth() {
        let state = State::new(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        {
            let mut parameters = state.world.parameters.block();
            parameters.smart_contract.execution_depth = 3;
            parameters.commit();
        }

        let trigger_id: TriggerId = "bounded_self_call".parse().expect("valid trigger id");
        let header = BlockHeader::new(nonzero!(1_u64), None, None, None, 0, 0);
        let mut block = state.block(header);
        let mut transaction = block.transaction();
        Register::domain(Domain::new(
            DomainId::try_new("wonderland", "universal").expect("valid domain"),
        ))
        .execute(&ALICE_ID, &mut transaction)
        .expect("register domain");
        Register::account(new_sample_account(&ALICE_ID))
            .execute(&ALICE_ID, &mut transaction)
            .expect("register account");

        let trigger = Trigger::new(
            trigger_id.clone(),
            Action::new(
                [InstructionBox::from(ExecuteTrigger::new(
                    trigger_id.clone(),
                ))],
                Repeats::Exactly(1),
                ALICE_ID.clone(),
                ExecuteTriggerEventFilter::new()
                    .for_trigger(trigger_id.clone())
                    .under_authority(ALICE_ID.clone()),
            ),
        );
        Register::trigger(trigger)
            .execute(&ALICE_ID, &mut transaction)
            .expect("register self-calling trigger");

        let event = ExecuteTriggerEvent {
            trigger_id: trigger_id.clone(),
            authority: ALICE_ID.clone(),
            args: Json::default(),
        };
        let error = transaction
            .execute_called_trigger(&trigger_id, &event)
            .expect_err("self-call must stop at the configured trigger depth");

        assert!(
            format!("{error:?}").contains("MaxDepthExceeded"),
            "unexpected self-call rejection: {error:?}"
        );
        assert_eq!(
            transaction.active_trigger_execution_depth, 0,
            "the synchronous depth reservation must unwind after rejection"
        );
        assert_eq!(
            transaction
                .world
                .triggers
                .by_call_triggers()
                .get(&trigger_id)
                .expect("trigger remains staged")
                .repeats,
            Repeats::Exactly(1),
            "a rejected recursive execution must not consume the repeat budget"
        );
    }

    #[test]
    fn authenticated_generic_ivm_trigger_executes_without_contract_identity() {
        use iroha_data_model::{
            events::execute_trigger::{ExecuteTriggerEvent, ExecuteTriggerEventFilter},
            transaction::{Executable, IvmBytecode},
            trigger::{
                Trigger,
                action::{Action, Repeats},
            },
        };

        let state = State::new(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        let trigger_id: TriggerId = "generic_ivm_callback".parse().expect("trigger id");
        let mut program = ivm::ProgramMetadata {
            max_cycles: 100,
            ..ivm::ProgramMetadata::default()
        }
        .encode();
        program.extend_from_slice(&ivm::encoding::wide::encode_halt().to_le_bytes());
        let generic_code_hash = ivm::contract_code_hash(&program);

        let block1 = new_dummy_block_with_payload(|header| {
            header.set_height(nonzero!(1_u64));
        });
        {
            let mut state_block = state.block(block1.as_ref().header());
            let mut transaction = state_block.transaction();
            Register::domain(Domain::new(
                DomainId::try_new("wonderland", "universal").expect("domain id"),
            ))
            .execute(&ALICE_ID, &mut transaction)
            .expect("register domain");
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&ALICE_ID, &mut transaction)
                .expect("register account");
            Grant::account_permission(
                iroha_executor_data_model::permission::trigger::CanRegisterTrigger {
                    authority: ALICE_ID.clone(),
                },
                ALICE_ID.clone(),
            )
            .execute(&ALICE_ID, &mut transaction)
            .expect("grant trigger registration");
            Register::trigger(Trigger::new(
                trigger_id.clone(),
                Action::new(
                    Executable::Ivm(IvmBytecode::from_compiled(program)),
                    Repeats::Indefinitely,
                    ALICE_ID.clone(),
                    ExecuteTriggerEventFilter::new()
                        .for_trigger(trigger_id.clone())
                        .under_authority(ALICE_ID.clone()),
                ),
            ))
            .execute(&ALICE_ID, &mut transaction)
            .expect("register authenticated generic trigger");
            transaction.apply();
            state_block.commit().expect("commit generic trigger");
        }

        let block2 = new_dummy_block_with_payload(|header| {
            header.set_height(nonzero!(2_u64));
        });
        let mut state_block = state.block(block2.as_ref().header());
        let mut transaction = state_block.transaction();
        let event = ExecuteTriggerEvent {
            trigger_id: trigger_id.clone(),
            authority: ALICE_ID.clone(),
            args: Json::default(),
        };
        let step = transaction
            .execute_called_trigger(&trigger_id, &event)
            .expect("generic IVM trigger executes at pc zero");
        assert!(step.0.is_empty());

        transaction.world.contract_manifests.insert(
            generic_code_hash,
            iroha_data_model::smart_contract::manifest::ContractManifest {
                seiyaku_name: None,
                code_hash: Some(generic_code_hash),
                abi_hash: Some(Hash::prehashed(ivm::syscalls::compute_abi_hash(
                    ivm::SyscallPolicy::AbiV1,
                ))),
                compiler_fingerprint: None,
                features_bitmap: None,
                access_set_hints: None,
                entrypoints: None,
                states: None,
                kotoba: None,
                error_codes: None,
                provenance: None,
            },
        );
        let execute_events_before = transaction
            .world
            .external_event_buf
            .iter()
            .filter(|event| {
                matches!(
                    event,
                    EventBox::ExecuteTrigger(execute)
                        if execute.trigger_id() == &trigger_id
                )
            })
            .count();
        let error = transaction
            .execute_called_trigger(&trigger_id, &event)
            .expect_err("a manifest-bound hash must not execute as a generic trigger");
        assert!(
            matches!(
                &error,
                TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                    if message.contains("contract manifest")
            ),
            "unexpected generic-trigger binding error: {error:?}"
        );
        let completion = transaction
            .world
            .external_event_buf
            .iter()
            .rev()
            .find_map(|event| match event {
                EventBox::TriggerCompleted(completion)
                    if completion.trigger_id() == &trigger_id =>
                {
                    Some(completion)
                }
                _ => None,
            });
        assert!(
            matches!(
                completion,
                Some(completion)
                    if completion.trigger_id() == &trigger_id
                        && matches!(
                            completion.outcome(),
                            TriggerCompletedOutcome::Failure(message)
                                if message.contains("contract manifest")
                        )
            ),
            "generic-trigger binding rejection must emit an auditable failure completion"
        );
        assert_eq!(
            transaction
                .world
                .external_event_buf
                .iter()
                .filter(|event| {
                    matches!(
                        event,
                        EventBox::ExecuteTrigger(execute)
                            if execute.trigger_id() == &trigger_id
                    )
                })
                .count(),
            execute_events_before,
            "generic-trigger binding rejection must not publish an execute-trigger event"
        );
    }

    #[test]
    fn raw_ivm_trigger_enforces_entrypoint_authorization_before_argument_decode() {
        use iroha_data_model::{
            events::execute_trigger::{ExecuteTriggerEvent, ExecuteTriggerEventFilter},
            smart_contract::ContractAddress,
            transaction::{Executable, IvmBytecode},
            trigger::{
                Trigger,
                action::{Action, Repeats},
            },
        };
        use iroha_test_samples::ALICE_KEYPAIR;
        use ivm::KotodamaCompiler;

        use crate::smartcontracts::code::{
            activate_instance, register_code_bytes, register_manifest,
        };

        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query_handle);

        const REQUIRED_PERMISSION: &str = "raw_trigger_run";
        let trigger_id: TriggerId = "protected_raw_callback".parse().expect("trigger id");
        let src = r#"
            seiyaku ProtectedRawTrigger {
              kotoage fn main(int marker, Json event) authorize("raw_trigger_run") {
                let _marker = marker;
                ledger::account::set_detail(
                  account: context::seiyaku_subject(),
                  key: Name::parse("raw_trigger_marker"),
                  value: event
                );
              }
            }
        "#;
        let (program, mut manifest) = KotodamaCompiler::new()
            .compile_source_with_manifest(src)
            .expect("compile protected raw trigger contract");
        let code_hash = ivm::contract_code_hash(&program);
        let bytecode = IvmBytecode::from_compiled(program.clone());
        let contract_address = ContractAddress::derive(
            iroha_data_model::account::address::chain_discriminant(),
            &ALICE_ID,
            77,
            DataSpaceId::UNIVERSAL,
        )
        .expect("derive raw trigger contract address");
        let contract_subject = contract_address.subject_id();

        let block1 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(1).unwrap());
            header.creation_time_ms = 1;
        });
        {
            let mut state_block = state.block(block1.as_ref().header());
            let mut stx = state_block.transaction();

            Register::domain(Domain::new(
                DomainId::try_new("wonderland", "universal").unwrap(),
            ))
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
            Register::account(Account::new(contract_subject.clone()))
                .execute(&ALICE_ID, &mut stx)
                .expect("register raw trigger contract subject");
            let deployment_permission: Permission =
                iroha_executor_data_model::permission::smart_contract::CanRegisterSmartContractCode
                    .into();
            Grant::account_permission(deployment_permission, ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("grant contract deployment permission");
            let registered_hash = register_code_bytes(&ALICE_ID, program, &mut stx)
                .expect("register raw trigger bytecode");
            assert_eq!(registered_hash, code_hash);
            manifest.code_hash = Some(code_hash);
            register_manifest(&ALICE_ID, manifest.signed(&ALICE_KEYPAIR), &mut stx)
                .expect("register raw trigger manifest");
            activate_instance(&ALICE_ID, contract_address.clone(), code_hash, &mut stx)
                .expect("activate raw trigger contract");
            let mut callback_metadata = Metadata::default();
            callback_metadata.insert(
                "contract_entrypoint".parse().expect("metadata key"),
                Json::new("main"),
            );
            callback_metadata.insert(
                "contract_address".parse().expect("metadata key"),
                Json::new(contract_address.to_string()),
            );
            let trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    Executable::Ivm(bytecode),
                    Repeats::Indefinitely,
                    ALICE_ID.clone(),
                    ExecuteTriggerEventFilter::new()
                        .for_trigger(trigger_id.clone())
                        .under_authority(ALICE_ID.clone()),
                )
                .with_metadata(callback_metadata),
            );
            Register::trigger(trigger)
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            stx.apply();
            state_block.commit().unwrap();
        }

        let block2 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(2).unwrap());
            header.creation_time_ms = 2;
        });
        {
            let mut state_block = state.block(block2.as_ref().header());
            let mut stx = state_block.transaction();
            stx.pipeline_ivm_prepared_cache =
                PreparedContractCache::with_capacity(stx.pipeline.cache_size);
            assert!(
                stx.pipeline_ivm_prepared_cache.get(code_hash).is_none(),
                "adversarial fixture must start without a cached trigger artifact"
            );
            let metadata_marker: Name = "raw_trigger_marker"
                .parse()
                .expect("valid raw-trigger metadata marker");
            let event = ExecuteTriggerEvent {
                trigger_id: trigger_id.clone(),
                authority: ALICE_ID.clone(),
                // Trigger event arguments use the same named-field object as direct
                // contract calls. The `event` field itself remains arbitrary JSON.
                args: Json::from(norito::json!({
                    "marker": "7",
                    "event": { "marker": "authorized" }
                })),
            };
            let denied_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let denied = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("raw IVM trigger must enforce its kotoage permission before decoding");
            assert!(
                matches!(
                    &denied,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains(REQUIRED_PERMISSION)
                ),
                "unexpected raw trigger authorization error: {denied:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "unauthorized trigger event arguments must remain undecoded"
            );
            assert!(
                stx.world
                    .account(&contract_subject)
                    .expect("raw trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker)
                    .is_none(),
                "denied raw IVM trigger must apply no queued effect"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                denied_events_before,
                "denied raw IVM trigger must emit no completion event"
            );
            assert_eq!(
                stx.pipeline_ivm_prepared_cache.stats().preparations,
                1,
                "a missing cached artifact must be authenticated and prepared exactly once from authoritative trigger storage"
            );

            let callback_permission = Permission::new(REQUIRED_PERMISSION.into(), Json::new(()));
            Grant::account_permission(callback_permission.clone(), ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("grant raw IVM trigger entrypoint permission");
            stx.execute_called_trigger(&trigger_id, &event)
                .expect("granted raw trigger should execute");
            assert_eq!(
                ivm::argument_record_decode_count(),
                1,
                "authorized trigger arguments must be prepared exactly once"
            );
            let trigger_cache_before_warm = stx.ivm_cache.lock().stats();
            let prepared_before_warm = stx.pipeline_ivm_prepared_cache.stats();
            ivm::reset_argument_record_decode_count();
            stx.execute_called_trigger(&trigger_id, &event)
                .expect("warm raw Kotodama trigger should reuse its prepared runtime");
            assert_eq!(
                ivm::argument_record_decode_count(),
                1,
                "warm trigger arguments must still decode exactly once"
            );
            let trigger_cache_after_warm = stx.ivm_cache.lock().stats();
            let prepared_after_warm = stx.pipeline_ivm_prepared_cache.stats();
            assert_eq!(
                trigger_cache_after_warm, trigger_cache_before_warm,
                "warm Kotodama trigger dispatch must not hash, parse, summarize, or build a private runtime template"
            );
            assert_eq!(
                prepared_after_warm.preparations, prepared_before_warm.preparations,
                "warm trigger dispatch must not copy and prepare the stored artifact again"
            );
            assert_eq!(
                prepared_after_warm.runtime_prepared_loads,
                prepared_before_warm.runtime_prepared_loads,
                "warm trigger dispatch must not load prepared code into another VM"
            );
            assert_eq!(
                prepared_after_warm.runtime_template_builds,
                prepared_before_warm.runtime_template_builds,
                "warm trigger dispatch must not reconstruct a pristine runtime template"
            );
            assert!(
                prepared_after_warm.runtime_hits > prepared_before_warm.runtime_hits,
                "warm trigger dispatch must check out the retained runtime"
            );
            let authorized_marker = stx
                .world
                .account(&contract_subject)
                .expect("raw trigger contract subject account")
                .metadata()
                .get(&metadata_marker)
                .cloned()
                .expect("authorized raw trigger writes its metadata marker");
            let live_manifest = stx
                .world
                .contract_manifests
                .remove(code_hash)
                .expect("remove raw-trigger manifest for adversarial check");
            let missing_manifest_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let missing_manifest = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("raw trigger must reject a missing live manifest even with warm code");
            assert!(
                matches!(
                    &missing_manifest,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains("has no manifest")
                ),
                "unexpected missing-manifest trigger error: {missing_manifest:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "missing trigger manifest must reject before event argument decoding"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                missing_manifest_events_before,
                "missing trigger manifest must emit no completion event"
            );
            assert_eq!(
                stx.world
                    .account(&contract_subject)
                    .expect("raw trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker),
                Some(&authorized_marker),
                "missing trigger manifest must apply no queued effect"
            );
            stx.world
                .contract_manifests
                .insert(code_hash, live_manifest);
            let live_code = stx
                .world
                .contract_code
                .remove(code_hash)
                .expect("remove live raw-trigger code for adversarial check");
            stx.world
                .contract_code
                .insert(code_hash, vec![0xFF; live_code.len().max(1)]);
            let mismatched_code_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let mismatched_code = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("cached raw trigger must reject mismatched live WSV code");
            assert!(
                matches!(
                    &mismatched_code,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains("does not match live WSV")
                ),
                "unexpected mismatched-code trigger error: {mismatched_code:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "mismatched live code must reject before event argument decoding"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                mismatched_code_events_before,
                "mismatched live code must emit no completion event"
            );
            assert_eq!(
                stx.world
                    .account(&contract_subject)
                    .expect("raw trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker),
                Some(&authorized_marker),
                "mismatched live code must apply no queued effect"
            );
            assert!(
                stx.world.contract_code.remove(code_hash).is_some(),
                "remove forged live code before restoring authoritative bytes"
            );
            stx.world.contract_code.insert(code_hash, live_code);
            Revoke::account_permission(callback_permission.clone(), ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("revoke raw IVM trigger entrypoint permission");
            let revoked_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let revoked = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("revoked raw IVM trigger permission must deny callback dispatch");
            assert!(
                matches!(
                    &revoked,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains(REQUIRED_PERMISSION)
                ),
                "unexpected revoked raw trigger error: {revoked:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "revoked raw trigger event arguments must remain undecoded"
            );
            assert_eq!(
                stx.world
                    .account(&contract_subject)
                    .expect("raw trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker),
                Some(&authorized_marker),
                "revoked raw IVM trigger must preserve the last authorized state"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                revoked_events_before,
                "revoked raw IVM trigger must emit no completion event"
            );

            Grant::account_permission(callback_permission, ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("restore raw IVM trigger entrypoint permission");
            stx.world
                .contract_instances
                .remove(contract_address.clone());
            let deactivated_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let deactivated = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("deactivated raw IVM trigger target must deny callback dispatch");
            assert!(
                matches!(
                    &deactivated,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains("not found")
                ),
                "unexpected deactivated raw trigger error: {deactivated:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "deactivated raw trigger event arguments must remain undecoded"
            );
            assert_eq!(
                stx.world
                    .account(&contract_subject)
                    .expect("raw trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker),
                Some(&authorized_marker),
                "deactivated raw IVM trigger must apply no queued effect"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                deactivated_events_before,
                "deactivated raw IVM trigger must emit no completion event"
            );
            stx.apply();
            state_block.commit().unwrap();
        }
    }

    #[test]
    fn identityless_raw_trigger_rejects_before_event_argument_decode_and_event_emission() {
        use iroha_data_model::{
            events::execute_trigger::{ExecuteTriggerEvent, ExecuteTriggerEventFilter},
            transaction::{Executable, IvmBytecode},
            trigger::{
                Trigger,
                action::{Action, Repeats},
            },
        };

        let state = State::new(
            World::default(),
            Kura::blank_kura_for_testing(),
            LiveQueryStore::start_test(),
        );
        let trigger_id: TriggerId = "identityless_raw_callback".parse().expect("trigger id");
        let program = ivm::KotodamaCompiler::new()
            .compile_source(
                r#"
seiyaku IdentitylessRawCallback {
  kotoage fn main(Json ev) authorize("identityless_raw_callback_run") {
    let _ev = ev;
  }
}
"#,
            )
            .expect("compile identity-less raw callback fixture");
        let block1 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(1).expect("non-zero height"));
        });
        {
            let mut state_block = state.block(block1.as_ref().header());
            let mut stx = state_block.transaction();
            Register::domain(Domain::new(
                DomainId::try_new("wonderland", "universal").expect("domain id"),
            ))
            .execute(&ALICE_ID, &mut stx)
            .expect("register domain");
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&ALICE_ID, &mut stx)
                .expect("register authority");
            let mut metadata = Metadata::default();
            metadata.insert(
                "contract_entrypoint".parse().expect("metadata key"),
                Json::new("main"),
            );
            let trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    Executable::Ivm(IvmBytecode::from_compiled(program)),
                    Repeats::Indefinitely,
                    ALICE_ID.clone(),
                    ExecuteTriggerEventFilter::new()
                        .for_trigger(trigger_id.clone())
                        .under_authority(ALICE_ID.clone()),
                )
                .with_metadata(metadata),
            );
            Register::trigger(trigger)
                .execute(&ALICE_ID, &mut stx)
                .expect("register identity-less raw trigger");
            stx.apply();
            state_block.commit().expect("commit trigger fixture");
        }

        let block2 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(2).expect("non-zero height"));
        });
        let mut state_block = state.block(block2.as_ref().header());
        let mut stx = state_block.transaction();
        let event = ExecuteTriggerEvent {
            trigger_id: trigger_id.clone(),
            authority: ALICE_ID.clone(),
            args: Json::from(norito::json!({ "untrusted": [1, 2, 3] })),
        };
        let external_events_before = stx.world.external_event_buf.len();
        ivm::reset_argument_record_decode_count();
        let error = stx
            .execute_called_trigger(&trigger_id, &event)
            .expect_err("raw callback without a live identity must fail closed");
        assert!(
            matches!(
                &error,
                TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                    if message.contains("requires a live contract_address or contract_alias")
            ),
            "unexpected identity-less raw trigger error: {error:?}"
        );
        assert_eq!(
            ivm::argument_record_decode_count(),
            0,
            "identity-less raw trigger must not decode event arguments"
        );
        assert_eq!(
            stx.world.external_event_buf.len(),
            external_events_before,
            "denied raw trigger must not emit an externally observable execute event"
        );
    }

    #[test]
    fn contract_call_trigger_enforces_entrypoint_authorization_before_argument_decode() {
        use iroha_data_model::{
            events::execute_trigger::{ExecuteTriggerEvent, ExecuteTriggerEventFilter},
            smart_contract::ContractAddress,
            transaction::{
                Executable,
                executable::{ContractArgumentRecord, ContractInvocation},
            },
            trigger::{
                Trigger,
                action::{Action, Repeats},
            },
        };
        use iroha_test_samples::ALICE_KEYPAIR;
        use ivm::KotodamaCompiler;

        use crate::smartcontracts::code::{
            activate_instance, register_code_bytes, register_manifest,
        };

        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query_handle);

        const REQUIRED_PERMISSION: &str = "contract_trigger_run";
        let src = r#"
            seiyaku ProtectedContractCallTrigger {
              kotoage fn run(int marker) authorize("contract_trigger_run") {
                let _marker = marker;
                ledger::account::set_detail(
                  account: context::seiyaku_subject(),
                  key: Name::parse("contract_trigger_marker"),
                  value: Json::parse("{\"authorized\":true}")
                );
              }

              trigger protected_contract_callback -> run {
                on execute trigger protected_contract_callback;
              }
            }
        "#;
        let (code, mut manifest) = KotodamaCompiler::new()
            .compile_source_with_manifest(src)
            .expect("compile contract-call trigger probe");
        let parsed = ivm::ProgramMetadata::parse(&code).expect("parse trigger contract artifact");
        let argument_schema = parsed
            .contract_interface
            .as_ref()
            .and_then(|interface| {
                interface
                    .entrypoints
                    .iter()
                    .find(|entrypoint| entrypoint.name == "run")
            })
            .and_then(|entrypoint| entrypoint.argument_schema.as_ref())
            .expect("parameterized trigger callback schema");
        let callback_arguments = ivm::encode_argument_record_from_json(
            argument_schema,
            &Json::from(norito::json!({ "marker": "9" })),
        )
        .expect("encode trigger callback arguments");
        let callback_arguments = ContractArgumentRecord::try_new(callback_arguments)
            .expect("bounded trigger callback arguments");

        let trigger_id: TriggerId = "contract_call_payload_probe".parse().unwrap();
        let contract_address = ContractAddress::derive(
            iroha_data_model::account::address::chain_discriminant(),
            &ALICE_ID,
            0,
            DataSpaceId::UNIVERSAL,
        )
        .expect("derive contract address");
        let contract_subject = contract_address.subject_id();

        let block1 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(1).unwrap());
            header.creation_time_ms = 1;
        });
        {
            let mut state_block = state.block(block1.as_ref().header());
            let mut stx = state_block.transaction();

            Register::domain(Domain::new(
                DomainId::try_new("wonderland", "universal").unwrap(),
            ))
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
            Register::account(Account::new(contract_subject.clone()))
                .execute(&ALICE_ID, &mut stx)
                .expect("register ContractCall trigger contract subject");
            let deployment_permission: Permission =
                iroha_executor_data_model::permission::smart_contract::CanRegisterSmartContractCode
                    .into();
            Grant::account_permission(deployment_permission, ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("grant contract deployment permission");
            let code_hash =
                register_code_bytes(&ALICE_ID, code, &mut stx).expect("register contract bytecode");
            manifest.code_hash = Some(code_hash);
            let manifest = manifest.signed(&ALICE_KEYPAIR);
            register_manifest(&ALICE_ID, manifest, &mut stx).expect("register contract manifest");
            activate_instance(&ALICE_ID, contract_address.clone(), code_hash, &mut stx)
                .expect("activate contract instance");

            let trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    Executable::ContractCall(ContractInvocation {
                        contract_address: contract_address.clone(),
                        expected_code_hash: code_hash,
                        entrypoint: "run".to_owned(),
                        arguments: Some(callback_arguments),
                    }),
                    Repeats::Indefinitely,
                    ALICE_ID.clone(),
                    ExecuteTriggerEventFilter::new()
                        .for_trigger(trigger_id.clone())
                        .under_authority(ALICE_ID.clone()),
                ),
            );
            Register::trigger(trigger)
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            stx.apply();
            state_block.commit().unwrap();
        }

        let block2 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(2).unwrap());
            header.creation_time_ms = 2;
        });
        {
            let mut state_block = state.block(block2.as_ref().header());
            let mut stx = state_block.transaction();
            let metadata_marker: Name = "contract_trigger_marker"
                .parse()
                .expect("valid ContractCall trigger metadata marker");
            let event = ExecuteTriggerEvent {
                trigger_id: trigger_id.clone(),
                authority: ALICE_ID.clone(),
                args: Json::from_string_unchecked(r#"{"condition_code":7}"#.to_owned()),
            };
            let denied_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let denied = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("trigger authority without the entrypoint permission must be denied");
            assert!(
                matches!(
                    &denied,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains(REQUIRED_PERMISSION)
                ),
                "unexpected trigger authorization error: {denied:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "denied ContractCall trigger event arguments must remain undecoded"
            );
            assert!(
                stx.world
                    .account(&contract_subject)
                    .expect("ContractCall trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker)
                    .is_none(),
                "denied ContractCall trigger must apply no queued effect"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                denied_events_before,
                "denied ContractCall trigger must emit no completion event"
            );

            let callback_permission = Permission::new(REQUIRED_PERMISSION.into(), Json::new(()));
            Grant::account_permission(callback_permission.clone(), ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("grant trigger entrypoint permission");
            stx.execute_called_trigger(&trigger_id, &event)
                .expect("granted contract-call trigger should consume its canonical arguments");
            assert_eq!(
                ivm::argument_record_decode_count(),
                1,
                "authorized ContractCall trigger arguments must be prepared exactly once"
            );
            let authorized_marker = stx
                .world
                .account(&contract_subject)
                .expect("ContractCall trigger contract subject account")
                .metadata()
                .get(&metadata_marker)
                .cloned()
                .expect("authorized trigger writes its metadata marker");
            Revoke::account_permission(callback_permission.clone(), ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("revoke trigger entrypoint permission");
            let revoked_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let revoked = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("revoked ContractCall trigger permission must deny callback dispatch");
            assert!(
                matches!(
                    &revoked,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains(REQUIRED_PERMISSION)
                ),
                "unexpected revoked trigger authorization error: {revoked:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "revoked ContractCall trigger event arguments must remain undecoded"
            );
            assert_eq!(
                stx.world
                    .account(&contract_subject)
                    .expect("ContractCall trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker),
                Some(&authorized_marker),
                "revoked ContractCall trigger must preserve the last authorized state"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                revoked_events_before,
                "revoked ContractCall trigger must emit no completion event"
            );

            Grant::account_permission(callback_permission, ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("restore trigger entrypoint permission");
            stx.world
                .contract_instances
                .remove(contract_address.clone());
            let deactivated_events_before = stx.world.external_event_buf.len();
            ivm::reset_argument_record_decode_count();
            let deactivated = stx
                .execute_called_trigger(&trigger_id, &event)
                .expect_err("deactivated ContractCall trigger target must deny callback dispatch");
            assert!(
                matches!(
                    &deactivated,
                    TransactionRejectionReason::Validation(ValidationFail::NotPermitted(message))
                        if message.contains("not found")
                ),
                "unexpected deactivated trigger error: {deactivated:?}"
            );
            assert_eq!(
                ivm::argument_record_decode_count(),
                0,
                "deactivated ContractCall trigger event arguments must remain undecoded"
            );
            assert_eq!(
                stx.world
                    .account(&contract_subject)
                    .expect("ContractCall trigger contract subject account")
                    .metadata()
                    .get(&metadata_marker),
                Some(&authorized_marker),
                "deactivated ContractCall trigger must apply no queued effect"
            );
            assert_eq!(
                stx.world.external_event_buf.len(),
                deactivated_events_before,
                "deactivated ContractCall trigger must emit no completion event"
            );
        }
    }

    #[allow(clippy::too_many_lines)]
    #[test]
    fn execute_data_trigger_supports_alias_resolve_and_json_amount_transfer() {
        use iroha_data_model::{
            account::rekey::AccountAlias,
            events::data::prelude as data_pre,
            permission::Permission,
            smart_contract::ContractAddress,
            transaction::{Executable, IvmBytecode},
            trigger::{
                Trigger,
                action::{Action, Repeats},
            },
        };
        use iroha_primitives::json::Json;
        use iroha_test_samples::ALICE_KEYPAIR;
        use ivm::{
            KotodamaCompiler,
            kotodama::compiler::{CompilerMode, CompilerOptions},
        };

        use crate::smartcontracts::code::{
            activate_instance, register_code_bytes, register_manifest,
        };

        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query_handle);

        let domain_id: DomainId = DomainId::try_new("wonderland", "universal").unwrap();
        let rose_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::new(
            domain_id.clone(),
            "rose".parse().unwrap(),
        );
        let gold_def_id: AssetDefinitionId = iroha_data_model::asset::AssetDefinitionId::new(
            domain_id.clone(),
            "gold".parse().unwrap(),
        );
        let gold_source = AssetId::new(gold_def_id.clone(), ALICE_ID.clone());
        let gold_target = AssetId::new(gold_def_id.clone(), BOB_ID.clone());
        let rose_source = AssetId::new(rose_def_id.clone(), ALICE_ID.clone());
        let rose_target = AssetId::new(rose_def_id.clone(), BOB_ID.clone());
        let trigger_id: TriggerId = "alias_json_transfer".parse().unwrap();
        let banking_label = AccountAlias::new(
            "banking".parse().expect("banking label"),
            Some(AccountAliasDomain::new(domain_id.name().clone())),
            DataSpaceId::UNIVERSAL,
        );

        let src = r#"
            seiyaku AliasTransfer {
              error enum AliasTransferError {
                UnexpectedKind = 1,
                UnexpectedOperation = 2,
                NonPositiveAmount = 3,
                UnexpectedAccountDomain = 4,
              }

              kotoage fn main(
                Name kind,
                Name op,
                AssetDefinitionId asset_definition_id,
                Name asset_definition_name,
                DomainId asset_definition_domain,
                AccountId account_id,
                DomainId account_domain,
                quantity amount,
              ) authorize("alias_transfer_run") {
                require(kind == Name::parse("asset_change"), AliasTransferError::UnexpectedKind);
                require(op == Name::parse("added"), AliasTransferError::UnexpectedOperation);
                require(amount > 0, AliasTransferError::NonPositiveAmount);
                require(
                  account_domain == DomainId::parse("wonderland.universal"),
                  AliasTransferError::UnexpectedAccountDomain,
                );
                let _asset_definition_id = asset_definition_id;
                let _asset_definition_name = asset_definition_name;
                let _asset_definition_domain = asset_definition_domain;
                let src = ledger::account::resolve_alias("banking@wonderland.universal");
                let payout = amount * 76;
                ledger::asset::transfer(source: account_id, destination: src, asset_definition: AssetDefinitionId::parse("__ROSE_ASSET_DEFINITION_ID__"), amount: amount, dataspace: DataSpaceId::parse("0"));
                ledger::asset::transfer(source: src, destination: account_id, asset_definition: AssetDefinitionId::parse("__GOLD_ASSET_DEFINITION_ID__"), amount: payout, dataspace: DataSpaceId::parse("0"));
              }
            }
        "#
        .replace("__ROSE_ASSET_DEFINITION_ID__", &rose_def_id.to_string())
        .replace("__GOLD_ASSET_DEFINITION_ID__", &gold_def_id.to_string());
        let (program, mut manifest) = KotodamaCompiler::new_with_options(CompilerOptions {
            mode: CompilerMode::Production,
            ..CompilerOptions::default()
        })
        .compile_source_with_manifest(&src)
        .expect("compile alias transfer contract");
        let code_hash = ivm::contract_code_hash(&program);
        let bytecode = IvmBytecode::from_compiled(program.clone());
        let contract_address = ContractAddress::derive(
            iroha_data_model::account::address::chain_discriminant(),
            &ALICE_ID,
            95,
            DataSpaceId::UNIVERSAL,
        )
        .expect("derive alias-transfer callback contract address");
        let contract_subject = contract_address.subject_id();

        let block1 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(1).unwrap());
            header.creation_time_ms = 1;
        });
        {
            let mut state_block = state.block(block1.as_ref().header());
            let mut stx = state_block.transaction();

            Register::domain(Domain::new(domain_id.clone()))
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
            Register::account(new_sample_account(&BOB_ID))
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
            Register::account(Account::new(contract_subject.clone()))
                .execute(&ALICE_ID, &mut stx)
                .expect("register alias-transfer callback contract subject");
            let deployment_permission: Permission =
                iroha_executor_data_model::permission::smart_contract::CanRegisterSmartContractCode
                    .into();
            Grant::account_permission(deployment_permission, ALICE_ID.clone())
                .execute(&ALICE_ID, &mut stx)
                .expect("grant alias-transfer callback deployment permission");
            let registered_hash = register_code_bytes(&ALICE_ID, program, &mut stx)
                .expect("register alias-transfer callback bytecode");
            assert_eq!(registered_hash, code_hash);
            manifest.code_hash = Some(code_hash);
            register_manifest(&ALICE_ID, manifest.signed(&ALICE_KEYPAIR), &mut stx)
                .expect("register alias-transfer callback manifest");
            activate_instance(&ALICE_ID, contract_address.clone(), code_hash, &mut stx)
                .expect("activate alias-transfer callback contract");
            Register::asset_definition({
                let __asset_definition_id = rose_def_id.clone();
                AssetDefinition::numeric(__asset_definition_id.clone())
                    .with_name(__asset_definition_id.name().to_string())
            })
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Register::asset_definition({
                let __asset_definition_id = gold_def_id.clone();
                AssetDefinition::numeric(__asset_definition_id.clone())
                    .with_name(__asset_definition_id.name().to_string())
            })
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Mint::asset_quantity(1_000_u32, gold_source.clone())
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
            Grant::account_permission(
                Permission::new("alias_transfer_run".into(), Json::new(())),
                ALICE_ID.clone(),
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Grant::account_permission(
                Permission::from(
                    iroha_executor_data_model::permission::account::CanManageAccountAlias {
                        scope: iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Dataspace(
                            iroha_data_model::nexus::DataSpaceId::UNIVERSAL,
                        ),
                    },
                ),
                ALICE_ID.clone(),
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Grant::account_permission(
                Permission::from(
                    iroha_executor_data_model::permission::account::CanManageAccountAlias {
                        scope: iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Domain(
                            domain_id.clone(),
                        ),
                    },
                ),
                ALICE_ID.clone(),
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Grant::account_permission(
                Permission::from(
                    iroha_executor_data_model::permission::account::CanResolveAccountAlias {
                        scope: iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Dataspace(
                            iroha_data_model::nexus::DataSpaceId::UNIVERSAL,
                        ),
                    },
                ),
                ALICE_ID.clone(),
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Grant::account_permission(
                Permission::from(
                    iroha_executor_data_model::permission::account::CanResolveAccountAlias {
                        scope: iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Domain(
                            domain_id.clone(),
                        ),
                    },
                ),
                ALICE_ID.clone(),
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            // Alias reads are authorized as the trigger caller, but deployed-contract effects
            // execute as the immutable bound subject. Grant that subject only the two asset
            // capabilities this callback needs.
            Grant::account_permission(
                Permission::from(
                    iroha_executor_data_model::permission::asset::CanTransferAssetWithDefinition {
                        asset_definition: rose_def_id.clone(),
                    },
                ),
                contract_subject.clone(),
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Grant::account_permission(
                Permission::from(
                    iroha_executor_data_model::permission::asset::CanTransferAssetWithDefinition {
                        asset_definition: gold_def_id.clone(),
                    },
                ),
                contract_subject,
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            seed_account_alias_lease(&mut stx, &ALICE_ID, &banking_label);
            let resolved_alias = iroha_data_model::alias_setup::ResolvedAccountAliasV1::new(
                banking_label
                    .to_literal(&stx.nexus.dataspace_catalog)
                    .expect("fixture alias must resolve")
                    .parse()
                    .expect("fixture alias must be canonical"),
                banking_label.dataspace,
            );
            iroha_data_model::isi::alias_setup::EnsureAlias::new(
                iroha_data_model::alias_setup::AliasIntentV1::AccountAlias(
                    iroha_data_model::alias_setup::AliasAccountIntentV1 {
                        alias: resolved_alias,
                        target_account: ALICE_ID.clone(),
                        provision: iroha_data_model::alias_setup::AccountProvisionV1::Existing,
                        role: iroha_data_model::alias_setup::AccountAliasRoleV1::Primary,
                    },
                ),
                iroha_data_model::alias_setup::AliasLeaseAcquisitionV1::new(1, None),
                iroha_data_model::alias_setup::AliasQuoteGuardV1 {
                    expected_policy_version: 0,
                    expected_payment_asset: iroha_data_model::asset::AssetDefinitionId::new(
                        DomainId::try_new("assets", "universal").expect("fixture asset domain"),
                        "xor".parse().expect("fixture asset name"),
                    ),
                    max_amount: Quantity::zero(),
                    valid_until_ms: 0,
                },
            )
            .execute(&ALICE_ID, &mut stx)
            .unwrap();

            let mut callback_metadata = Metadata::default();
            callback_metadata.insert(
                "contract_entrypoint".parse().expect("metadata key"),
                Json::new("main"),
            );
            callback_metadata.insert(
                "contract_address".parse().expect("metadata key"),
                Json::new(contract_address.to_string()),
            );
            let trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    Executable::Ivm(bytecode),
                    Repeats::Indefinitely,
                    ALICE_ID.clone(),
                    data_pre::DataEventFilter::Asset(
                        data_pre::AssetEventFilter::new()
                            .for_events(data_pre::AssetEventSet::Added)
                            .for_asset(rose_target.clone()),
                    ),
                )
                .with_metadata(callback_metadata),
            );
            Register::trigger(trigger)
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            stx.apply();
            state_block.commit().unwrap();
        }

        let block2 = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(2).unwrap());
            header.creation_time_ms = 2;
        });
        {
            let mut state_block = state.block(block2.as_ref().header());
            let mut stx = state_block.transaction();

            Mint::asset_quantity(5_u32, rose_target.clone())
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            let steps = stx
                .execute_data_triggers_dfs(&ALICE_ID)
                .expect("data trigger should execute transfer path");
            assert_eq!(steps.len(), 1, "expected one data trigger execution");

            stx.apply();
            state_block.commit().unwrap();
        }

        let view = state.view();
        let bob_gold = view
            .world
            .asset(&gold_target)
            .expect("trigger should credit gold to bob");
        assert_eq!(&**bob_gold.value(), &Quantity::from(380_u32));
        let alice_gold = view
            .world
            .asset(&gold_source)
            .expect("trigger should debit gold from the reserve");
        assert_eq!(&**alice_gold.value(), &Quantity::from(620_u32));
        let alice_rose = view
            .world
            .asset(&rose_source)
            .expect("trigger should collect rose into the reserve");
        assert_eq!(&**alice_rose.value(), &Quantity::from(5_u32));
    }

    #[test]
    fn detached_execute_called_trigger_failure_rolls_back_state() {
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new(World::default(), kura, query_handle);

        let trigger_id: TriggerId = "rollback_trigger_detached".parse().unwrap();
        let asset_definition_id: AssetDefinitionId =
            iroha_data_model::asset::AssetDefinitionId::new(
                DomainId::try_new("wonderland", "universal").unwrap(),
                "xor".parse().unwrap(),
            );

        // Commit initial domain, account, and the by-call trigger.
        let block = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(1).unwrap());
        });
        {
            let mut state_block = state.block(block.as_ref().header());
            let mut stx = state_block.transaction();
            Register::domain(Domain::new(
                DomainId::try_new("wonderland", "universal").unwrap(),
            ))
            .execute(&ALICE_ID, &mut stx)
            .unwrap();
            Register::account(new_sample_account(&ALICE_ID))
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            let create_asset = Register::asset_definition({
                let __asset_definition_id = asset_definition_id.clone();
                AssetDefinition::numeric(__asset_definition_id.clone())
                    .with_name(__asset_definition_id.name().to_string())
            });
            let fail_isi = Unregister::domain(DomainId::try_new("dummy", "universal").unwrap());
            let instructions: [InstructionBox; 2] = [create_asset.into(), fail_isi.into()];
            let trigger = Trigger::new(
                trigger_id.clone(),
                Action::new(
                    instructions,
                    Repeats::Indefinitely,
                    ALICE_ID.clone(),
                    ExecuteTriggerEventFilter::new()
                        .for_trigger(trigger_id.clone())
                        .under_authority(ALICE_ID.clone()),
                ),
            );
            Register::trigger(trigger)
                .execute(&ALICE_ID, &mut stx)
                .unwrap();

            stx.apply();
            state_block.commit().unwrap();
        }

        // Build a detached delta that records the by-call trigger execution.
        let mut delta = DetachedStateTransactionDelta::default();
        let event = ExecuteTriggerEvent {
            trigger_id: trigger_id.clone(),
            authority: ALICE_ID.clone(),
            args: Json::default(),
        };
        delta.execute_trigger_by_call(event);

        // Merge the detached delta and expect rejection; state changes must rollback.
        let block = new_dummy_block_with_payload(|header| {
            header.set_height(NonZeroU64::new(2).unwrap());
        });
        {
            let mut state_block = state.block(block.as_ref().header());
            let result = delta.merge_into(&mut state_block, &ALICE_ID);
            assert!(
                result.is_err(),
                "detached trigger execution should fail and reject the transaction"
            );
        }

        let view = state.view();
        assert!(
            view.world.asset_definition(&asset_definition_id).is_err(),
            "asset definition created by a failing detached trigger must not persist",
        );
    }

    fn build_executor_verdict_program(
        verdict: &Result<(), iroha_data_model::ValidationFail>,
    ) -> Vec<u8> {
        use norito::codec::Encode as _;

        crate::executor::build_program_from_encoded_result(&verdict.encode())
    }

    #[test]
    fn execute_called_trigger_respects_executor_validation() {
        use iroha_data_model::{
            ChainId, Level,
            events::execute_trigger::{ExecuteTriggerEvent, ExecuteTriggerEventFilter},
            executor as data_model_executor,
            isi::Log,
            transaction::executable::IvmBytecode,
            trigger::TriggerId,
        };

        let verdict = Err(iroha_data_model::ValidationFail::NotPermitted(
            "executor denied".to_owned(),
        ));
        let bytecode = build_executor_verdict_program(&verdict);
        let raw = data_model_executor::Executor::new(IvmBytecode::from_compiled(bytecode));
        let executor = crate::executor::Executor::UserProvided(
            crate::executor::LoadedExecutor::load(raw).expect("load executor"),
        );

        let domain: Domain =
            Domain::new(DomainId::try_new("wonderland", "universal").unwrap()).build(&ALICE_ID);
        let account = new_sample_account(&ALICE_ID).build(&ALICE_ID);
        let world = World::with([domain], [account], []);
        let mut executor_block = world.executor.block();
        *executor_block.get_mut() = executor;
        executor_block.commit();

        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_with_chain(world, kura, query_handle, ChainId::from("test-chain"));

        let trigger_id: TriggerId = "executor_guarded_trigger".parse().unwrap();
        let trigger = Trigger::new(
            trigger_id.clone(),
            Action::new(
                vec![InstructionBox::from(Log::new(
                    Level::INFO,
                    "trigger log".to_owned(),
                ))],
                Repeats::Indefinitely,
                ALICE_ID.clone(),
                ExecuteTriggerEventFilter::new()
                    .for_trigger(trigger_id.clone())
                    .under_authority(ALICE_ID.clone()),
            ),
        );

        let header = BlockHeader::new(NonZeroU64::new(1).unwrap(), None, None, None, 0, 0);
        let mut state_block = state.block(header);
        {
            let mut stx = state_block.transaction();
            Register::trigger(trigger)
                .execute(&ALICE_ID, &mut stx)
                .unwrap();
            stx.apply();
        }
        state_block.commit().unwrap();

        let header = BlockHeader::new(NonZeroU64::new(2).unwrap(), None, None, None, 0, 0);
        let mut state_block = state.block(header);
        let mut stx = state_block.transaction();
        let event = ExecuteTriggerEvent {
            trigger_id: trigger_id.clone(),
            authority: ALICE_ID.clone(),
            args: Json::default(),
        };
        let err = stx
            .execute_called_trigger(&trigger_id, &event)
            .expect_err("trigger should be rejected by executor");
        match err {
            TransactionRejectionReason::Validation(
                iroha_data_model::ValidationFail::NotPermitted(msg),
            ) => {
                assert!(
                    msg.contains("executor denied"),
                    "unexpected rejection message: {msg}"
                );
            }
            other => panic!("unexpected rejection: {other:?}"),
        }
    }

    #[test]
    fn block_rejects_failing_execute_trigger_and_rolls_back() {
        use std::borrow::Cow;

        use iroha_test_samples::ALICE_KEYPAIR;

        use crate::{block::BlockBuilder, tx::AcceptedTransaction};

        // Seed the world with a domain and ALICE account to author the trigger.
        let domain: Domain =
            Domain::new(DomainId::try_new("wonderland", "universal").unwrap()).build(&ALICE_ID);
        let account = new_sample_account(&ALICE_ID).build(&ALICE_ID);
        let world = World::with([domain], [account], []);

        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_with_chain(world, kura, query_handle, ChainId::from("chain"));

        let trigger_id: TriggerId = "rollback_trigger_block".parse().unwrap();
        let asset_definition_id: AssetDefinitionId =
            iroha_data_model::asset::AssetDefinitionId::new(
                DomainId::try_new("wonderland", "universal").unwrap(),
                "xor".parse().unwrap(),
            );

        // Tx 1: register the by-call trigger that will fail when executed.
        let create_asset = Register::asset_definition({
            let __asset_definition_id = asset_definition_id.clone();
            AssetDefinition::numeric(__asset_definition_id.clone())
                .with_name(__asset_definition_id.name().to_string())
        });
        let fail_isi = Unregister::domain(DomainId::try_new("dummy", "universal").unwrap());
        let instructions: [InstructionBox; 2] = [create_asset.into(), fail_isi.into()];
        let register_trigger = Register::trigger(Trigger::new(
            trigger_id.clone(),
            Action::new(
                instructions,
                Repeats::Indefinitely,
                ALICE_ID.clone(),
                ExecuteTriggerEventFilter::new()
                    .for_trigger(trigger_id.clone())
                    .under_authority(ALICE_ID.clone()),
            ),
        ));
        let register_tx = TransactionBuilder::new(
            ChainId::from("chain"),
            ALICE_ID.clone(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions([register_trigger])
        .sign(ALICE_KEYPAIR.private_key());

        // Build and validate a block containing the registration transaction.
        let block = BlockBuilder::new(vec![AcceptedTransaction::new_unchecked(Cow::Owned(
            register_tx,
        ))])
        .chain(0, None)
        .sign(ALICE_KEYPAIR.private_key())
        .unpack(|_| {});

        let mut state_block = state.block(block.header());
        let valid = ValidBlock::validate_unchecked(block.into(), &mut state_block).unpack(|_| {});
        let reg_err = valid.as_ref().error(0).cloned();
        assert!(
            reg_err.is_none(),
            "trigger registration should succeed (reg_err={reg_err:?})"
        );

        // Commit the block effects and ensure no state leaked from the rejected transaction.
        let committed = valid.commit_unchecked().unpack(|_| {});
        let _ = state_block.apply_without_execution(&committed, Vec::new());
        state_block.commit().unwrap();
        let prev_block = committed;

        // Tx 2: attempt to execute the failing trigger by call in the next block.
        let exec_tx = TransactionBuilder::new(
            ChainId::from("chain"),
            ALICE_ID.clone(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions([InstructionBox::from(ExecuteTrigger::new(
            trigger_id.clone(),
        ))])
        .sign(ALICE_KEYPAIR.private_key());

        let block = BlockBuilder::new(vec![AcceptedTransaction::new_unchecked(Cow::Owned(
            exec_tx,
        ))])
        .chain(0, Some(prev_block.as_ref()))
        .sign(ALICE_KEYPAIR.private_key())
        .unpack(|_| {});

        let mut state_block = state.block(block.header());
        let valid = ValidBlock::validate_unchecked(block.into(), &mut state_block).unpack(|_| {});
        let exec_err = valid.as_ref().error(0).cloned();

        let committed = valid.commit_unchecked().unpack(|_| {});
        let _ = state_block.apply_without_execution(&committed, Vec::new());
        state_block.commit().unwrap();

        let view = state.view();
        let asset_exists = view.world.asset_definition(&asset_definition_id).is_ok();
        let trigger_present = view.world.triggers().ids().get(&trigger_id).is_some();

        assert!(
            exec_err.is_some(),
            "execute-trigger transaction should be rejected when trigger fails (asset_exists={asset_exists}, trigger_present={trigger_present}, reg_err={reg_err:?}, got {exec_err:?})"
        );
        if let Some(reason) = exec_err {
            match reason {
                TransactionRejectionReason::Validation(
                    ValidationFail::InstructionFailed(InstructionExecutionError::Find(
                        FindError::Domain(_),
                    ))
                    | ValidationFail::NotPermitted(_),
                ) => {}
                other => {
                    panic!("unexpected rejection reason: {other:?}");
                }
            }
        }
        assert!(
            !asset_exists,
            "asset definition created by a failing trigger must not persist after block application",
        );
    }

    #[test]
    fn confidential_digest_respects_activation_height() {
        use iroha_data_model::{
            confidential::ConfidentialStatus,
            proof::{VerifyingKeyId, VerifyingKeyRecord},
            zk::BackendTag,
        };

        let mut world = World::new();
        let id = VerifyingKeyId::new("halo2/ipa", "vk_activation");
        let mut record = VerifyingKeyRecord::new_with_owner(
            1,
            "circuit_activation",
            None,
            "core",
            BackendTag::Halo2IpaPasta,
            "pallas",
            [0x11; 32],
            [0x22; 32],
        );
        record.status = ConfidentialStatus::Proposed;
        record.activation_height = Some(5);
        record.gas_schedule_id = Some("sched_activation".into());
        record.public_inputs_schema_hash = [0x33; 32];
        world.verifying_keys.insert(id.clone(), record.clone());
        world
            .verifying_keys_by_circuit
            .insert((record.circuit_id.clone(), record.version), id.clone());

        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let mut state = State::new(world, kura, query);
        state.zk.registry_max_delta_per_block = 10;

        let view = state.view();
        let digest_before = compute_confidential_feature_digest(
            view.world(),
            &view.zk,
            view.sccp_registry.as_ref(),
            4,
        );
        assert_eq!(digest_before.vk_set_hash, None);

        let digest_at_activation = compute_confidential_feature_digest(
            view.world(),
            &view.zk,
            view.sccp_registry.as_ref(),
            5,
        );
        assert!(digest_at_activation.vk_set_hash.is_some());
    }

    #[test]
    fn confidential_digest_excludes_active_vk_outside_height_window() {
        use iroha_data_model::{
            confidential::ConfidentialStatus,
            proof::{VerifyingKeyId, VerifyingKeyRecord},
            zk::BackendTag,
        };

        let mut world = World::new();
        let id = VerifyingKeyId::new("halo2/ipa", "vk_windowed_active");
        let mut record = VerifyingKeyRecord::new_with_owner(
            1,
            "circuit_windowed_active",
            None,
            "core",
            BackendTag::Halo2IpaPasta,
            "pallas",
            [0x21; 32],
            [0x42; 32],
        );
        record.status = ConfidentialStatus::Active;
        record.activation_height = Some(5);
        record.withdraw_height = Some(8);
        record.gas_schedule_id = Some("sched_windowed_active".into());
        record.public_inputs_schema_hash = [0x63; 32];
        world.verifying_keys.insert(id.clone(), record.clone());
        world
            .verifying_keys_by_circuit
            .insert((record.circuit_id.clone(), record.version), id);

        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let state = State::new(world, kura, query);
        let view = state.view();

        assert_eq!(compute_vk_set_hash_at_height(view.world(), 4), None);
        assert!(compute_vk_set_hash_at_height(view.world(), 5).is_some());
        assert_eq!(compute_vk_set_hash_at_height(view.world(), 8), None);

        let digest_before = compute_confidential_feature_digest(
            view.world(),
            &view.zk,
            view.sccp_registry.as_ref(),
            4,
        );
        assert_eq!(digest_before.vk_set_hash, None);

        let digest_active = compute_confidential_feature_digest(
            view.world(),
            &view.zk,
            view.sccp_registry.as_ref(),
            5,
        );
        assert!(digest_active.vk_set_hash.is_some());

        let digest_withdrawn = compute_confidential_feature_digest(
            view.world(),
            &view.zk,
            view.sccp_registry.as_ref(),
            8,
        );
        assert_eq!(digest_withdrawn.vk_set_hash, None);
    }

    #[test]
    fn confidential_registry_delta_cap_limits_transitions() {
        use iroha_data_model::{
            confidential::ConfidentialStatus,
            proof::{VerifyingKeyId, VerifyingKeyRecord},
            zk::BackendTag,
        };

        let mut world = World::new();
        let ids = [
            VerifyingKeyId::new("halo2/ipa", "vk_alpha"),
            VerifyingKeyId::new("halo2/ipa", "vk_beta"),
        ];
        for (idx, id) in ids.iter().enumerate() {
            let mut record = VerifyingKeyRecord::new_with_owner(
                1,
                format!("circuit_{idx}"),
                None,
                "core",
                BackendTag::Halo2IpaPasta,
                "pallas",
                [0x40 + u8::try_from(idx).expect("vk index fits in u8"); 32],
                [0x50 + u8::try_from(idx).expect("vk index fits in u8"); 32],
            );
            record.status = ConfidentialStatus::Proposed;
            record.activation_height = Some(2);
            record.gas_schedule_id = Some(format!("sched_{idx}"));
            record.public_inputs_schema_hash =
                [0x60 + u8::try_from(idx).expect("vk index fits in u8"); 32];
            world.verifying_keys.insert(id.clone(), record.clone());
            world
                .verifying_keys_by_circuit
                .insert((record.circuit_id.clone(), record.version), id.clone());
        }

        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let mut state = State::new(world, kura, query);
        state.zk.registry_max_delta_per_block = 1;

        let header = BlockHeader::new(NonZeroU64::new(2).unwrap(), None, None, None, 0, 0);
        let block = state.block(header);

        let alpha_status = block
            .world
            .verifying_keys
            .get(&ids[0])
            .map(|rec| rec.status)
            .expect("alpha vk present");
        let beta_status = block
            .world
            .verifying_keys
            .get(&ids[1])
            .map(|rec| rec.status)
            .expect("beta vk present");

        assert_eq!(alpha_status, ConfidentialStatus::Active);
        assert_eq!(beta_status, ConfidentialStatus::Proposed);
    }

    fn assemble_ivm_header(code: &[u8]) -> Vec<u8> {
        let mut blob = ivm::ProgramMetadata {
            version_major: 1,
            version_minor: 0,
            mode: 0,
            vector_length: 0,
            max_cycles: 1_000_000,
            abi_version: 1,
        }
        .encode();
        blob.extend_from_slice(code);
        blob
    }

