    fn merge_candidate_with_lanes(epoch: u64, count: usize) -> crate::merge::MergeLedgerCandidate {
        let mut lane_snapshots = Vec::with_capacity(count);
        for idx in 0..count {
            let tip = u8::try_from(idx).expect("lane index fits in u8");
            let hint = tip.strict_add(1);
            let lane_id = LaneId::new(u32::try_from(idx).expect("lane index fits in u32"));
            let lane_incarnation = iroha_crypto::Hash::new([tip, 0x49]);
            let dataspace_id = DataSpaceId::new(u64::try_from(idx + 1).expect("dsid fits in u64"));
            let lane_block_height = epoch.saturating_add(u64::try_from(idx).expect("height fits"));
            let settlement_commitment =
                empty_merge_settlement(lane_id, lane_incarnation, dataspace_id, lane_block_height);
            lane_snapshots.push(MergeLaneSnapshot {
                lane_id,
                lane_incarnation,
                incarnation_activation_height: 1,
                proposal_height: epoch.max(1),
                dataspace_id,
                lane_block_height,
                tip_hash: HashOf::from_untyped_unchecked(iroha_crypto::Hash::new([tip])),
                merge_hint_root: iroha_crypto::Hash::new([hint]),
                settlement_hash: canonical_merge_settlement_hash(&settlement_commitment)
                    .expect("test settlement commitment should hash canonically"),
                settlement_commitment,
                relay_envelope: None,
            });
        }
        let active_lanes = lane_snapshots
            .iter()
            .map(|snapshot| MergeLaneBinding {
                lane_id: snapshot.lane_id,
                dataspace_id: snapshot.dataspace_id,
                lane_config_hash: Hash::new(
                    format!("test-merge-lane-{}", snapshot.lane_id.as_u32()).as_bytes(),
                ),
                incarnation: snapshot.lane_incarnation,
                activation_height: snapshot.incarnation_activation_height,
            })
            .collect::<Vec<_>>();
        let lifecycle_incarnations = active_lanes
            .iter()
            .map(
                |binding| iroha_data_model::nexus::LaneLifecycleIncarnationEntry {
                    lane_id: binding.lane_id,
                    incarnation: binding.incarnation,
                },
            )
            .collect::<Vec<_>>();
        let merge_hint_roots: Vec<Hash> = lane_snapshots
            .iter()
            .map(|snapshot| snapshot.merge_hint_root)
            .collect();
        let global_state_root = crate::merge::reduce_merge_hint_roots(&merge_hint_roots);
        crate::merge::MergeLedgerCandidate {
            version: crate::merge::MergeLedgerCandidate::VERSION,
            epoch_id: epoch,
            view: 0,
            carrier_height: 2,
            carrier_parent_hash: HashOf::from_untyped_unchecked(Hash::new(b"test-merge-parent")),
            lane_catalog_hash: Hash::new(format!("test-merge-catalog-{count}").as_bytes()),
            incarnation_root: iroha_data_model::nexus::LaneLifecycleParameterV1::incarnation_root(
                &lifecycle_incarnations,
            ),
            activation_root: crate::merge::merge_activation_root(&active_lanes),
            active_lanes,
            lane_snapshots,
            execution_batch: None,
            lane_drain_certificates: Vec::new(),
            queue_plan_admissions: Vec::new(),
            global_state_root,
        }
    }

    fn merge_candidate_from_relay(
        state: &State,
        epoch: u64,
        envelope: &LaneRelayEnvelope,
    ) -> crate::merge::MergeLedgerCandidate {
        if state.latest_block_hash_fast().is_none() {
            let parent = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::new(
                b"test-relay-carrier-parent",
            ));
            let mut block_hashes = state.block_hashes.block();
            block_hashes.push_for_tests(parent);
            block_hashes.commit_for_tests();
        }
        let merge_hint_root = envelope.merge_hint_root().expect("merge hint root");
        let lane_snapshots = vec![MergeLaneSnapshot {
            lane_id: envelope.lane_id,
            lane_incarnation: envelope.lane_incarnation,
            incarnation_activation_height: state
                .lane_incarnation_activation_heights_snapshot()
                .get(&envelope.lane_id)
                .copied()
                .unwrap_or_default()
                .saturating_add(1),
            proposal_height: envelope.block_header.height().get(),
            dataspace_id: envelope.dataspace_id,
            lane_block_height: envelope.block_height,
            tip_hash: envelope.block_header.hash(),
            merge_hint_root,
            settlement_commitment: envelope.settlement_commitment.clone(),
            settlement_hash: envelope.settlement_hash,
            relay_envelope: Some(envelope.clone()),
        }];
        let nexus = state.nexus_snapshot();
        let incarnations = state.lane_incarnations_snapshot();
        let activations = state.lane_incarnation_activation_heights_snapshot();
        let active_lanes = nexus
            .lane_catalog
            .lanes()
            .iter()
            .map(|lane| MergeLaneBinding {
                lane_id: lane.id,
                dataspace_id: lane.dataspace_id,
                lane_config_hash: merge_lane_config_hash(lane),
                incarnation: incarnations[&lane.id],
                activation_height: activations[&lane.id].saturating_add(1),
            })
            .collect::<Vec<_>>();
        let lifecycle_incarnations = active_lanes
            .iter()
            .map(
                |binding| iroha_data_model::nexus::LaneLifecycleIncarnationEntry {
                    lane_id: binding.lane_id,
                    incarnation: binding.incarnation,
                },
            )
            .collect::<Vec<_>>();
        let merge_hint_roots = vec![merge_hint_root];
        let global_state_root = crate::merge::reduce_merge_hint_roots(&merge_hint_roots);
        crate::merge::MergeLedgerCandidate {
            version: crate::merge::MergeLedgerCandidate::VERSION,
            epoch_id: epoch,
            view: envelope.block_header.view_change_index(),
            carrier_height: u64::try_from(state.committed_height())
                .unwrap_or(u64::MAX)
                .saturating_add(1),
            carrier_parent_hash: state
                .latest_block_hash_fast()
                .expect("test merge carrier parent was seeded"),
            lane_catalog_hash: merge_lane_catalog_hash(&nexus.lane_catalog),
            incarnation_root: iroha_data_model::nexus::LaneLifecycleParameterV1::incarnation_root(
                &lifecycle_incarnations,
            ),
            activation_root: crate::merge::merge_activation_root(&active_lanes),
            active_lanes,
            lane_snapshots,
            execution_batch: None,
            lane_drain_certificates: Vec::new(),
            queue_plan_admissions: Vec::new(),
            global_state_root,
        }
    }

    fn merge_entry_from_candidate(
        candidate: crate::merge::MergeLedgerCandidate,
        merge_qc: MergeQuorumCertificate,
    ) -> MergeLedgerEntry {
        candidate.into_entry(merge_qc)
    }

    fn ensure_merge_carrier_parent_for_test(state: &State) {
        let committed_height = state.committed_height();
        let durable_count = state.exact_durable_block_count().unwrap();
        if committed_height > 0 {
            assert_eq!(
                committed_height, durable_count,
                "partially hydrated test state must not synthesize an occupied carrier height"
            );
            let durable_tip = state
                .kura
                .get_durable_block_hash(
                    NonZeroUsize::new(durable_count).expect("durable height is non-zero"),
                )
                .expect("durable test state exposes its canonical tip");
            assert_eq!(
                state.latest_block_hash_fast(),
                Some(durable_tip),
                "committed test state tip must match Kura before carrier synthesis"
            );
            return;
        }
        if durable_count > 0 {
            let mut block_hashes = state.block_hashes.block();
            for height in 1..=durable_count {
                let height = NonZeroUsize::new(height).expect("durable height is non-zero");
                let hash = state
                    .kura
                    .get_durable_block_hash(height)
                    .expect("durable merge-carrier parent hash");
                block_hashes.push_for_tests(hash);
            }
            block_hashes.commit_for_tests();
            let tip_height = NonZeroUsize::new(durable_count).expect("durable tip is non-zero");
            let tip = state
                .kura
                .get_block(tip_height)
                .expect("durable merge-carrier parent block");
            state.update_latest_block_header_cache_for_tests(tip.header().clone());
            seed_empty_transaction_height_for_state_test(
                state,
                u64::try_from(durable_count).expect("durable test height fits u64"),
            );
            assert_eq!(state.committed_height(), durable_count);
            return;
        }
        let parent = new_dummy_block_with_payload(|header| {
            header.set_height(nonzero!(1_u64));
            header.set_prev_block_hash(None);
            header.set_view_change_index(0);
        });
        let parent_hash = parent.as_ref().hash();
        state
            .kura
            .store_block(parent.clone())
            .expect("store canonical merge-carrier parent");
        let mut block_hashes = state.block_hashes.block();
        block_hashes.push_for_tests(parent_hash);
        block_hashes.commit_for_tests();
        state.update_latest_block_header_cache_for_tests(parent.as_ref().header().clone());
        seed_empty_transaction_height_for_state_test(state, 1);
        assert_eq!(state.latest_block_hash_fast(), Some(parent_hash));
        assert_eq!(state.exact_durable_block_count().unwrap(), 1);
    }

    fn store_merge_carrier_without_state_publication_for_test(
        state: &State,
        entry: &MergeLedgerEntry,
    ) -> CommittedBlock {
        let expected_height = u64::try_from(state.committed_height())
            .expect("committed test height fits u64")
            .saturating_add(1);
        assert_eq!(
            entry.merge_qc.carrier_height, expected_height,
            "test merge entry must target the next canonical carrier"
        );
        assert_eq!(
            state.latest_block_hash_fast(),
            Some(entry.merge_qc.carrier_parent_hash),
            "test merge entry must bind the current canonical parent"
        );

        let mut carrier = new_dummy_block_with_payload(|header| {
            header.set_height(
                NonZeroU64::new(entry.merge_qc.carrier_height)
                    .expect("test merge carrier height is non-zero"),
            );
            header.set_prev_block_hash(Some(entry.merge_qc.carrier_parent_hash));
            header.set_view_change_index(entry.merge_qc.view);
        });
        let execution_context = carrier
            .as_ref()
            .execution_context()
            .cloned()
            .unwrap_or_else(
                || iroha_data_model::block::BlockExecutionContextBundle::new(Vec::new()),
            )
            .with_merge_entry(iroha_data_model::block::CertifiedMergeLedgerReference::new(
                entry,
            ));
        carrier
            .as_mut()
            .set_execution_context(Some(execution_context));
        state
            .kura
            .store_block_with_merge_entry(Arc::new(carrier.as_ref().clone()), entry)
            .expect("store canonical merge carrier");
        carrier
    }

    fn publish_committed_merge_carrier_for_test(state: &State, entry: &MergeLedgerEntry) {
        let carrier = store_merge_carrier_without_state_publication_for_test(state, entry);

        let carrier_hash = carrier.as_ref().hash();
        let mut block_hashes = state.block_hashes.block();
        block_hashes.push_for_tests(carrier_hash);
        block_hashes.commit_for_tests();
        state.update_latest_block_header_cache_for_tests(carrier.as_ref().header().clone());
        seed_empty_transaction_height_for_state_test(state, entry.merge_qc.carrier_height);
        assert_eq!(state.latest_block_hash_fast(), Some(carrier_hash));
        assert_eq!(
            state.exact_durable_block_count().unwrap(),
            usize::try_from(entry.merge_qc.carrier_height)
                .expect("test merge carrier height fits usize")
        );
    }

    fn set_commit_topology_from_keypairs(state: &State, keypairs: &[KeyPair]) {
        let mut topo = state.commit_topology.block();
        topo.clear();
        for keypair in keypairs {
            topo.push(PeerId::new(keypair.public_key().clone()));
        }
        topo.commit();
    }

    fn configure_commit_topology(state: &State, count: usize) -> Vec<KeyPair> {
        let mut peers = Vec::with_capacity(count);
        let mut keypairs = Vec::with_capacity(count);
        for _ in 0..count {
            let keypair =
                crate::state::checked_keypair_with_algorithm(iroha_crypto::Algorithm::BlsNormal);
            peers.push(PeerId::new(keypair.public_key().clone()));
            keypairs.push(keypair);
        }
        let mut topo = state.commit_topology.block();
        topo.clear();
        for peer in peers {
            topo.push(peer);
        }
        topo.commit();
        let committed_peers: Vec<_> = keypairs
            .iter()
            .map(|keypair| PeerId::new(keypair.public_key().clone()))
            .collect();
        let mut world_block = state.world.block();
        {
            let mut peers = world_block.peers_mut_for_testing().transaction();
            for peer in committed_peers {
                if !peers.iter().any(|existing| existing == &peer) {
                    peers.push(peer);
                }
            }
            peers.apply();
        }
        world_block.commit();
        seed_consensus_keys_with_pops(state, &keypairs);
        keypairs
    }

    fn configure_commit_topology_preserving_world_peers(
        state: &State,
        count: usize,
    ) -> Vec<KeyPair> {
        let keypairs: Vec<_> = (0..count)
            .map(|_| {
                crate::state::checked_keypair_with_algorithm(iroha_crypto::Algorithm::BlsNormal)
            })
            .collect();
        set_commit_topology_from_keypairs(state, &keypairs);
        seed_consensus_keys_with_pops(state, &keypairs);
        keypairs
    }

    fn record_commit_ready_merge_candidate_with_lanes(
        state: &mut State,
        count: usize,
        first_height: u64,
    ) -> (
        crate::merge::MergeLedgerCandidate,
        Vec<KeyPair>,
        Vec<KeyPair>,
    ) {
        assert!(count > 0, "test helper requires at least one lane");
        let lane_count = u32::try_from(count).expect("lane count fits in u32");
        let (validator_ids, validator_keypairs) = bls_accounts_in("validators", 4);
        seed_consensus_keys_with_pops(state, &validator_keypairs);

        let lanes: Vec<LaneConfig> = (0..lane_count)
            .map(|idx| {
                if idx == 0 {
                    LaneConfig::default()
                } else {
                    LaneConfig {
                        id: LaneId::new(idx),
                        alias: format!("lane-{idx}"),
                        dataspace_id: DataSpaceId::UNIVERSAL,
                        ..LaneConfig::default()
                    }
                }
            })
            .collect();
        let lane_catalog = LaneCatalog::new(
            core::num::NonZeroU32::new(lane_count).expect("non-zero"),
            lanes,
        )
        .expect("lane catalog");
        let nexus = iroha_config::parameters::actual::Nexus {
            enabled: true,
            lane_catalog,
            ..iroha_config::parameters::actual::Nexus::default()
        };
        state.set_nexus(nexus).expect("apply Nexus lane catalog");

        let registry_entries: Vec<_> = (0..lane_count)
            .map(|idx| {
                (
                    LaneId::new(idx),
                    DataSpaceId::UNIVERSAL,
                    validator_ids.clone(),
                )
            })
            .collect();
        install_lane_manifest_registry(state, &registry_entries);
        let commit_keypairs = configure_commit_topology_preserving_world_peers(state, 1);

        for idx in 0..lane_count {
            let envelope = sample_lane_relay_envelope_for_state(
                state,
                first_height,
                LaneId::new(idx),
                &validator_keypairs,
            );
            state
                .record_lane_relay(&envelope)
                .expect("commit-ready relay accepted");
        }

        ensure_merge_carrier_parent_for_test(state);
        let candidate = state
            .merge_entry_candidates_from_lane_relays()
            .into_iter()
            .next()
            .expect("merge candidate from recorded relays");
        (candidate, commit_keypairs, validator_keypairs)
    }

    fn empty_global_block_after(previous: Option<&SignedBlock>) -> SignedBlock {
        let creation_time_ms = previous.map_or(1_700_000_000_000, |block| {
            block.header().creation_time_ms.saturating_add(1)
        });
        autoscale_signed_block_with_committed_fragments(previous, creation_time_ms, 0)
    }

    fn certified_merge_carrier_after(
        previous: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> SignedBlock {
        let mut carrier = empty_global_block_after(Some(previous));
        assert_eq!(
            carrier.header().height().get(),
            entry.merge_qc.carrier_height,
            "merge fixture carrier height must match its QC"
        );
        assert_eq!(
            carrier.header().prev_block_hash(),
            Some(entry.merge_qc.carrier_parent_hash),
            "merge fixture carrier parent must match its QC"
        );
        assert_eq!(
            carrier.header().view_change_index(),
            entry.merge_qc.view,
            "merge fixture carrier view must match its QC"
        );
        let context = carrier
            .execution_context()
            .cloned()
            .unwrap_or_else(
                || iroha_data_model::block::BlockExecutionContextBundle::new(Vec::new()),
            )
            .with_merge_entry(iroha_data_model::block::CertifiedMergeLedgerReference::new(
                entry,
            ));
        carrier.set_execution_context(Some(context));
        carrier
    }

    fn commit_block_metadata_to_state(state: &State, block: &SignedBlock) {
        let mut state_block = state.block(block.header().clone());
        state_block.block_hashes.push(block.hash());
        insert_empty_transaction_block_for_state_commit(&mut state_block, block);
        state_block
            .commit()
            .expect("test global block metadata must commit to State");
    }

    fn commit_exact_merge_carrier_to_state(
        state: &State,
        carrier: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) {
        let mut state_block = state
            .block_with_certified_merge_entry(carrier.header().clone(), entry)
            .expect("certified merge entry must stage on its exact carrier");
        state_block.block_hashes.push(carrier.hash());
        insert_empty_transaction_block_for_state_commit(&mut state_block, carrier);
        state_block
            .commit()
            .expect("exact certified merge carrier must commit to State");
        state
            .record_globally_committed_merge_entry(entry, MergeLedgerPublicationMode::LiveCommit)
            .expect("exact certified merge carrier must publish its merge cache");
    }

    fn configured_single_lane_merge_state() -> (State, Vec<KeyPair>, Vec<KeyPair>, SignedBlock) {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query);
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                ..iroha_config::parameters::actual::Nexus::default()
            })
            .expect("enable single-lane Nexus merge fixture");

        let (validator_ids, validator_keypairs) = bls_accounts_in("validators", 4);
        seed_consensus_keys_with_pops(&state, &validator_keypairs);
        install_lane_manifest_registry(
            &state,
            &[(LaneId::SINGLE, DataSpaceId::UNIVERSAL, validator_ids)],
        );
        let commit_keypairs = configure_commit_topology_preserving_world_peers(&state, 1);

        let parent = empty_global_block_after(None);
        kura.store_block(Arc::new(parent.clone()))
            .expect("store merge fixture carrier parent");
        commit_block_metadata_to_state(&state, &parent);
        (state, validator_keypairs, commit_keypairs, parent)
    }

    fn queue_plan_entrypoint_for_state_test(state: &State, tag: u8) -> TransactionEntrypoint {
        let transaction_keypair =
            KeyPair::try_from_seed(vec![tag.wrapping_add(0x31); 32], Algorithm::Ed25519)
                .expect("deterministic QueuePlan transaction key");
        let authority = AccountId::new(transaction_keypair.public_key().clone());
        let mut transaction = TransactionBuilder::new(
            state.chain_id.clone(),
            authority,
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        );
        transaction.set_creation_time(Duration::from_millis(u64::from(tag).saturating_add(1)));
        TransactionEntrypoint::External(
            transaction
                .with_instructions([Log::new(Level::INFO, format!("queue-plan-admission-{tag}"))])
                .sign(transaction_keypair.private_key()),
        )
    }

    fn queue_plan_admission_certificate_for_state_test(
        state: &State,
        routing_plan: crate::queue::RoutingPlan,
        validator_keypairs: &[KeyPair],
        authority_height: u64,
        tag: u8,
    ) -> (crate::torii_proxy::QueuePlanAdmissionBindingV2, Vec<u8>) {
        let proposal_height = authority_height
            .checked_add(1)
            .expect("fixture proposal height");
        let predecessor_block_hash = if authority_height == 0 {
            None
        } else {
            usize::try_from(authority_height)
                .ok()
                .and_then(|height| height.checked_sub(1))
                .and_then(|index| state.block_hashes.view().get(index).copied())
        };
        let route_incarnations = routing_plan
            .legs()
            .into_iter()
            .map(|leg| {
                let validator_set =
                    state.authoritative_lane_peer_ids_at_height(leg.route.lane_id, proposal_height);
                assert!(
                    !validator_set.is_empty(),
                    "fixture route must have authoritative validators"
                );
                crate::queue::QueuePlanRouteIncarnationV2 {
                    leg,
                    lane_incarnation: state
                        .lane_incarnation(leg.route.lane_id)
                        .expect("fixture route has an active incarnation"),
                    validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
                    validator_set_hash: HashOf::new(&validator_set),
                    validator_count: u16::try_from(validator_set.len())
                        .expect("fixture validator count"),
                    durability_threshold: u16::try_from(validator_set.len().div_ceil(3))
                        .expect("fixture durability threshold"),
                    validator_set,
                }
            })
            .collect::<Vec<_>>();
        let admission_context = crate::queue::QueuePlanAdmissionContextV2 {
            version: crate::queue::QUEUE_PLAN_ADMISSION_CONTEXT_VERSION_V2,
            authority_height,
            proposal_height,
            predecessor_block_hash,
            routing_plan_digest: routing_plan.digest(),
            route_incarnations,
        };
        let entrypoint = queue_plan_entrypoint_for_state_test(state, tag);
        let binding = crate::torii_proxy::QueuePlanAdmissionBindingV2::new(
            &state.chain_id,
            &entrypoint,
            &routing_plan,
            admission_context,
            u64::from(tag).saturating_add(100),
        )
        .expect("canonical QueuePlan admission binding");
        let binding_hash = binding.canonical_hash();
        let coordinator = &binding.admission_context.route_incarnations[0];
        let attestations = coordinator
            .validator_set
            .iter()
            .take(usize::from(coordinator.durability_threshold))
            .enumerate()
            .map(|(index, validator)| {
                let keypair = validator_keypairs
                    .iter()
                    .find(|keypair| keypair.public_key() == validator.public_key())
                    .expect("fixture retains every authoritative validator key");
                let validator_index =
                    u16::try_from(index).expect("fixture validator index fits u16");
                let signing_bytes =
                    crate::torii_proxy::queue_plan_admission_attestation_signing_bytes_v2(
                        binding_hash,
                        validator_index,
                    )
                    .expect("QueuePlan attestation preimage");
                crate::torii_proxy::QueuePlanAdmissionAttestationV2 {
                    version: crate::torii_proxy::QUEUE_PLAN_ADMISSION_ATTESTATION_VERSION_V2,
                    validator_index,
                    signature: Signature::try_new(keypair.private_key(), &signing_bytes)
                        .expect("QueuePlan attestation signature"),
                }
            })
            .collect();
        let certificate = crate::torii_proxy::QueuePlanAdmissionCertificateV2 {
            version: crate::torii_proxy::QUEUE_PLAN_ADMISSION_CERTIFICATE_VERSION_V2,
            binding: binding.clone(),
            attestations,
        };
        (
            binding,
            norito::to_bytes(&certificate).expect("canonical QueuePlan admission certificate"),
        )
    }

    #[expect(
        clippy::too_many_lines,
        reason = "the fixture assembles one complete availability-certified autonomous source"
    )]
    fn autonomous_merge_source_for_queue_plan_admission_test(
        state: &State,
        binding: &crate::torii_proxy::QueuePlanAdmissionBindingV2,
        entrypoint: TransactionEntrypoint,
        routing_plan: crate::queue::RoutingPlan,
        validator_keypairs: &[KeyPair],
    ) -> MergeExecutionSource {
        let coordinator = binding
            .admission_context
            .route_incarnations
            .first()
            .expect("fixture binding has a coordinator");
        let validator_set = coordinator.validator_set.clone();
        let validator_count =
            u32::try_from(validator_set.len()).expect("fixture validator count fits u32");
        let min_quorum = u32::try_from(crate::sumeragi::network_topology::commit_quorum_from_len(
            validator_set.len(),
        ))
        .expect("fixture quorum fits u32");
        let proposal_height = binding.admission_context.proposal_height;
        let lane_block_height = 1;
        let lane_block_view = 0;
        let entrypoint_hash = Hash::from(entrypoint.hash());
        let mut descriptor = LaneBlockDescriptorV1 {
            lane_id: coordinator.leg.route.lane_id,
            dataspace_id: coordinator.leg.route.dataspace_id,
            lane_incarnation: coordinator.lane_incarnation,
            proposal_height,
            previous_lane_block_height: 0,
            previous_lane_block_descriptor_hash: None,
            lane_block_height,
            lane_block_view,
            subject_hash: Hash::new(b"queue-plan-pre-carrier-autonomous-subject"),
            payload_ownership_hash: Hash::new(b"queue-plan-pre-carrier-autonomous-ownership"),
            rbc_instance_hash: Hash::new(b"queue-plan-pre-carrier-autonomous-rbc"),
            accepted_candidate_indices: vec![0],
            accepted_transaction_hashes: vec![entrypoint_hash],
            validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
            validator_set_hash: HashOf::new(&validator_set),
            validator_set: validator_set.clone(),
            validator_count,
            min_quorum,
            qc_mode_tag: "permissioned:queue-plan-pre-carrier-autonomous".to_owned(),
            descriptor_hash: Hash::prehashed([0; Hash::LENGTH]),
        };
        descriptor.descriptor_hash = descriptor.computed_descriptor_hash();
        let mut proposal = LaneBlockProposalV1 {
            descriptor,
            proposal_hash: Hash::prehashed([0; Hash::LENGTH]),
            payload_block_hint: None,
        };
        proposal.proposal_hash = proposal.computed_proposal_hash();

        let accepted = crate::tx::AcceptedTransaction::new_unchecked_entrypoint(Cow::Owned(
            entrypoint.clone(),
        ));
        let reservation = crate::queue::LaneQueueReservationKeyV2 {
            version: crate::queue::LaneQueueReservationKeyV2::VERSION,
            signed_transaction_hash: accepted.hash(),
            entrypoint_hash: entrypoint.hash(),
            queue_plan_admission_binding_hash: binding.canonical_hash(),
            routing_plan_digest: routing_plan.digest(),
            coordinator_leg: routing_plan.coordinator_leg(),
            lane_id: proposal.descriptor.lane_id,
            dataspace_id: proposal.descriptor.dataspace_id,
            lane_incarnation: proposal.descriptor.lane_incarnation,
            proposal_height,
            lane_block_height,
            lane_block_view,
            reservation_owner_hash: Hash::new(
                b"queue-plan-pre-carrier-autonomous-reservation-owner",
            ),
            proposal_identity_hash: proposal.proposal_hash,
        };
        let producer_keypair = validator_keypairs
            .iter()
            .find(|keypair| keypair.public_key() == validator_set[0].public_key())
            .expect("fixture retains the deterministic producer key");
        let producer = validator_set[0].clone();
        let chain_id_hash = Hash::new(state.chain_id.clone().into_inner().as_bytes());
        let epoch =
            crate::sumeragi::epoch_for_height_from_world(&state.world.view(), proposal_height);
        let payload = crate::lane_consensus::LaneExecutablePayloadV1::new_signed_with_reservations(
            chain_id_hash,
            epoch,
            proposal.clone(),
            vec![entrypoint.clone()],
            vec![reservation],
            vec![routing_plan],
            vec![None],
            producer,
            producer_keypair.private_key(),
        )
        .expect("canonical autonomous QueuePlan fixture payload");

        let validator_pops = validator_set
            .iter()
            .map(|validator| {
                let keypair = validator_keypairs
                    .iter()
                    .find(|keypair| keypair.public_key() == validator.public_key())
                    .expect("fixture retains every lane validator key");
                iroha_crypto::bls_normal_pop_prove(keypair.private_key())
                    .expect("fixture lane validator PoP")
            })
            .collect::<Vec<_>>();
        let selected_keypairs = validator_set
            .iter()
            .take(usize::try_from(min_quorum).expect("fixture quorum fits usize"))
            .map(|validator| {
                validator_keypairs
                    .iter()
                    .find(|keypair| keypair.public_key() == validator.public_key())
                    .expect("fixture retains every selected lane validator key")
            })
            .collect::<Vec<_>>();
        let prepare_body = proposal.vote_body(CertPhase::Prepare);
        let availability_body = crate::lane_consensus::lane_payload_availability_body(
            &payload,
            &proposal,
            chain_id_hash,
            epoch,
        )
        .expect("fixture availability body");
        let prepare_votes = selected_keypairs
            .iter()
            .map(|keypair| {
                let availability_vote =
                    crate::lane_consensus::LanePayloadAvailabilityVoteV1::new_signed(
                        availability_body.clone(),
                        PeerId::new(keypair.public_key().clone()),
                        validator_pops.clone(),
                        keypair.private_key(),
                    )
                    .expect("fixture availability vote");
                crate::lane_consensus::LaneBlockVoteV1 {
                    body: prepare_body.clone(),
                    signer: PeerId::new(keypair.public_key().clone()),
                    bls_signature: Signature::try_new(
                        keypair.private_key(),
                        &prepare_body.signature_preimage(),
                    )
                    .expect("fixture prepare signature")
                    .payload()
                    .to_vec(),
                    payload_availability_vote: Some(availability_vote),
                }
            })
            .collect::<Vec<_>>();
        let prepare_qc = crate::lane_consensus::aggregate_lane_block_votes_to_qc(
            prepare_body,
            validator_set.clone(),
            &prepare_votes,
        )
        .expect("fixture availability-certified PrepareQC");
        let commit_votes = selected_keypairs
            .iter()
            .map(|keypair| {
                signed_lane_block_vote_for_state_test(&proposal, CertPhase::Commit, keypair)
            })
            .collect::<Vec<_>>();
        let commit_qc = crate::lane_consensus::aggregate_lane_block_votes_to_qc(
            proposal.vote_body(CertPhase::Commit),
            validator_set,
            &commit_votes,
        )
        .expect("fixture CommitQC");
        let signer_pops = selected_keypairs
            .iter()
            .map(|keypair| {
                (
                    keypair.public_key().clone(),
                    iroha_crypto::bls_normal_pop_prove(keypair.private_key())
                        .expect("fixture selected signer PoP"),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let certified = crate::kura::CertifiedLaneBlockArtifact::new(
            crate::lane_consensus::CommittedLaneBlockSession {
                proposal: proposal.clone(),
                prepare_qc: prepare_qc.clone(),
                commit_qc,
            },
            signer_pops,
        );
        let autonomous = crate::kura::AutonomousLaneBlockArtifact {
            format: crate::kura::AutonomousLaneBlockArtifactFormat::Current,
            executable_payload: payload.clone(),
            availability_certificate: Some(
                crate::lane_consensus::DurableLanePayloadAvailabilityCertificateV1 {
                    certificate: prepare_qc,
                },
            ),
            view_checkpoint: None,
            new_view_certificates: Vec::new(),
        };
        let bundle = crate::kura::AutonomousLaneMergeBundleV1 {
            version: 1,
            autonomous,
            certified: certified.clone(),
        };
        let source_bundle = bundle
            .encode_framed()
            .expect("fixture autonomous bundle encoding");
        crate::kura::Kura::validate_autonomous_lane_merge_bundle(&bundle, chain_id_hash, epoch)
            .expect("fixture autonomous bundle validation");
        let (proposal_block_hash, proposal_view) =
            crate::kura::Kura::autonomous_lane_execution_anchor(&proposal, payload.payload_hash);
        let descriptor = &proposal.descriptor;
        let ownership = SumeragiLanePayloadOwnership {
            proposal_height,
            proposal_view,
            lane_id: descriptor.lane_id,
            dataspace_id: descriptor.dataspace_id,
            lane_incarnation: descriptor.lane_incarnation,
            lane_block_height,
            lane_block_view,
            subject_hash: descriptor.subject_hash,
            qc_mode_tag: descriptor.qc_mode_tag.clone(),
            accepted_candidate_indices: descriptor.accepted_candidate_indices.clone(),
            accepted_transaction_hashes: descriptor.accepted_transaction_hashes.clone(),
            previous_lane_block_height: 0,
            previous_lane_block_descriptor_hash: None,
            lane_block_descriptor_hash: Some(descriptor.descriptor_hash),
            lane_block_descriptor_validator_set: descriptor.validator_set.clone(),
            lane_block_descriptor_validator_count: descriptor.validator_count,
            lane_block_descriptor_min_quorum: descriptor.min_quorum,
            payload_ownership_hash: descriptor.payload_ownership_hash,
            rbc_instance_hash: descriptor.rbc_instance_hash,
        };
        let input = crate::kura::LaneBlockExecutionInputArtifact::new(
            crate::kura::RecoveredLaneBlockPayload {
                proposal: proposal.clone(),
                artifact: crate::kura::LaneBlockArtifact::new(proposal_block_hash, ownership),
                autonomous_chain_id_hash: Some(chain_id_hash),
                autonomous_epoch: Some(epoch),
                autonomous_payload_hash: Some(payload.payload_hash),
                entrypoints: vec![entrypoint],
                reservation_keys: payload.reservation_keys.clone(),
                routing_plans: payload.routing_plans.clone(),
                native_amx_receipts: payload.native_amx_receipts.clone(),
            },
        );
        MergeExecutionSource {
            bundle_hash: merge_execution_source_bundle_hash(&source_bundle),
            source_bundle,
            origin_proposal: proposal,
            certified,
            input,
        }
    }

    fn configured_two_lane_merge_state() -> (State, Vec<KeyPair>, Vec<KeyPair>, SignedBlock) {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(World::default(), Arc::clone(&kura), query);
        let lane_one = LaneConfig {
            id: LaneId::new(1),
            alias: "replaceable-lane".to_owned(),
            ..LaneConfig::default()
        };
        let lane_catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), lane_one])
            .expect("two-lane merge fixture catalog");
        state
            .set_nexus(iroha_config::parameters::actual::Nexus {
                enabled: true,
                lane_catalog,
                ..iroha_config::parameters::actual::Nexus::default()
            })
            .expect("enable two-lane Nexus merge fixture");

        let (validator_ids, validator_keypairs) = bls_accounts_in("validators", 4);
        seed_consensus_keys_with_pops(&state, &validator_keypairs);
        install_lane_manifest_registry(
            &state,
            &[
                (
                    LaneId::SINGLE,
                    DataSpaceId::UNIVERSAL,
                    validator_ids.clone(),
                ),
                (LaneId::new(1), DataSpaceId::UNIVERSAL, validator_ids),
            ],
        );
        let commit_keypairs = configure_commit_topology_preserving_world_peers(&state, 1);

        let parent = empty_global_block_after(None);
        kura.store_block(Arc::new(parent.clone()))
            .expect("store two-lane merge fixture carrier parent");
        commit_block_metadata_to_state(&state, &parent);
        (state, validator_keypairs, commit_keypairs, parent)
    }

    #[test]
    fn queue_plan_only_carriers_require_exact_committed_active_lane_bindings() {
        let (state, validator_keypairs, commit_keypairs, parent) =
            configured_two_lane_merge_state();
        let routing_plan = crate::queue::RoutingPlan::single(crate::queue::RoutingDecision::new(
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
        ));
        let (_, certificate) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan,
            &validator_keypairs,
            1,
            0x51,
        );
        let candidate = state
            .merge_candidate_with_queue_plan_admissions(
                &parent.header(),
                0,
                None,
                vec![certificate],
            )
            .expect("canonical QueuePlan candidate construction")
            .expect("QueuePlan controls produce a standalone candidate");
        assert!(candidate.execution_batch.is_none());
        assert!(candidate.lane_snapshots.is_empty());
        assert!(candidate.lane_drain_certificates.is_empty());

        let mut stale_incarnation = candidate.clone();
        stale_incarnation.active_lanes[1].incarnation =
            Hash::new(b"forged-unrelated-lane-incarnation");
        let incarnation_entries = stale_incarnation
            .active_lanes
            .iter()
            .map(
                |binding| iroha_data_model::nexus::LaneLifecycleIncarnationEntry {
                    lane_id: binding.lane_id,
                    incarnation: binding.incarnation,
                },
            )
            .collect::<Vec<_>>();
        stale_incarnation.incarnation_root =
            iroha_data_model::nexus::LaneLifecycleParameterV1::incarnation_root(
                &incarnation_entries,
            );
        stale_incarnation.activation_root =
            crate::merge::merge_activation_root(&stale_incarnation.active_lanes);
        assert!(matches!(
            state.validate_merge_candidate_for_global_round(
                &stale_incarnation,
                &parent.header(),
                0,
            ),
            Err(MergeLedgerCommitError::IncarnationContext(_))
        ));

        let mut forged_config = candidate;
        forged_config.active_lanes[1].lane_config_hash = Hash::new(b"forged-unrelated-lane-config");
        let forged_qc = merge_qc_for_candidate(&state, &forged_config, &commit_keypairs, &[0]);
        let forged_entry = merge_entry_from_candidate(forged_config, forged_qc);
        assert!(matches!(
            state.validate_certified_merge_entry_for_global_order(&forged_entry),
            Err(MergeLedgerCommitError::IncarnationContext(_))
        ));
    }

    #[test]
    fn restart_authenticates_queue_plan_predecessor_from_durable_kura_before_state_replay() {
        let (state, validator_keypairs, commit_keypairs, parent) =
            configured_single_lane_merge_state();
        let kura = Arc::clone(&state.kura);
        let routing_plan = crate::queue::RoutingPlan::single(crate::queue::RoutingDecision::new(
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
        ));
        let (_, certificate) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan,
            &validator_keypairs,
            1,
            0x52,
        );
        let candidate = state
            .merge_candidate_with_queue_plan_admissions(
                &parent.header(),
                0,
                None,
                vec![certificate],
            )
            .expect("canonical QueuePlan candidate construction")
            .expect("QueuePlan controls produce a standalone candidate");
        let qc = merge_qc_for_candidate(&state, &candidate, &commit_keypairs, &[0]);
        let entry = merge_entry_from_candidate(candidate, qc);
        let carrier = certified_merge_carrier_after(&parent, &entry);
        kura.store_block_with_merge_entry(Arc::new(carrier.clone()), &entry)
            .expect("persist QueuePlan merge carrier before State publication");
        drop(state);

        let mut restarted = State::try_new_with_chain(
            World::default(),
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
            (*DEFAULT_TEST_CHAIN_ID).clone(),
            #[cfg(feature = "telemetry")]
            <_>::default(),
        )
        .expect("durable QueuePlan predecessor authenticates before State block replay");
        assert_eq!(
            restarted.committed_height(),
            0,
            "startup recovery must not pretend future Kura carriers are in State"
        );
        assert!(
            restarted.merge_ledger().is_empty(),
            "the future carrier remains unpublished until exact State replay"
        );

        restarted.push_block_hash_for_testing(parent.hash());
        restarted.push_block_hash_for_testing(carrier.hash());
        restarted
            .recover_merge_ledger_from_kura()
            .expect("exact State replay hydrates the authenticated QueuePlan carrier");
        assert_eq!(restarted.merge_ledger().snapshot()[0].as_ref(), &entry);
    }

    #[test]
    fn restart_rejects_queue_plan_predecessor_conflicting_with_durable_kura() {
        let (state, validator_keypairs, commit_keypairs, parent) =
            configured_single_lane_merge_state();
        let kura = Arc::clone(&state.kura);
        let routing_plan = crate::queue::RoutingPlan::single(crate::queue::RoutingDecision::new(
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
        ));
        let (_, valid_certificate) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan.clone(),
            &validator_keypairs,
            1,
            0x53,
        );
        let mut candidate = state
            .merge_candidate_with_queue_plan_admissions(
                &parent.header(),
                0,
                None,
                vec![valid_certificate],
            )
            .expect("canonical QueuePlan candidate construction")
            .expect("QueuePlan controls produce a standalone candidate");

        let conflicting_predecessor = HashOf::<BlockHeader>::from_untyped_unchecked(Hash::new(
            b"conflicting-queue-plan-restart-predecessor",
        ));
        {
            let mut block_hashes = state.block_hashes.block_and_revert();
            block_hashes.push(conflicting_predecessor);
            block_hashes.commit();
        }
        let (_, conflicting_certificate) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan,
            &validator_keypairs,
            1,
            0x54,
        );
        {
            let mut block_hashes = state.block_hashes.block_and_revert();
            block_hashes.push(parent.hash());
            block_hashes.commit();
        }
        candidate.queue_plan_admissions = vec![conflicting_certificate];
        let qc = merge_qc_for_candidate(&state, &candidate, &commit_keypairs, &[0]);
        let entry = merge_entry_from_candidate(candidate, qc);
        let carrier = certified_merge_carrier_after(&parent, &entry);
        kura.store_block_with_merge_entry(Arc::new(carrier), &entry)
            .expect("persist cryptographically valid conflicting QueuePlan carrier");
        drop(state);

        let recovery = State::try_new_with_chain(
            World::default(),
            kura,
            LiveQueryStore::start_test(),
            (*DEFAULT_TEST_CHAIN_ID).clone(),
            #[cfg(feature = "telemetry")]
            <_>::default(),
        );
        let error = match recovery {
            Ok(_) => panic!("durable Kura history must reject a conflicting QueuePlan predecessor"),
            Err(error) => error,
        };
        assert!(
            matches!(
                error,
                MergeLedgerCommitError::ExecutionBatchInvalid(ref message)
                    if message.contains(
                        "queue-plan admission predecessor is absent or differs from canonical history"
                    )
            ),
            "unexpected conflicting predecessor rejection: {error}"
        );
    }

    #[test]
    fn queue_plan_registry_staging_is_an_exact_idempotent_compare_and_set() {
        let (state, validator_keypairs, _, parent) = configured_two_lane_merge_state();
        let routing_plan = crate::queue::RoutingPlan::single(crate::queue::RoutingDecision::new(
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
        ));
        let (binding, certificate) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan,
            &validator_keypairs,
            1,
            0x59,
        );
        assert_eq!(
            state
                .queue_plan_admission_binding_registry_match(&binding)
                .expect("absent registry lookup"),
            QueuePlanAdmissionRegistryMatch::Absent
        );
        let candidate = state
            .merge_candidate_with_queue_plan_admissions(
                &parent.header(),
                0,
                None,
                vec![certificate.clone()],
            )
            .expect("canonical QueuePlan candidate")
            .expect("standalone QueuePlan candidate");
        let carrier = empty_global_block_after(Some(&parent));
        let mut state_block = state.block(carrier.header());
        let write_set_before = state_block.merge_execution_write_set_root();
        state_block
            .stage_queue_plan_admissions(&[certificate.clone()], &candidate.active_lanes, 2)
            .expect("absent registry marker is inserted");
        let write_set_after_insert = state_block.merge_execution_write_set_root();
        assert_ne!(
            write_set_after_insert, write_set_before,
            "QueuePlan registry writes must enter the signed final WSV write-set commitment"
        );
        state_block
            .stage_queue_plan_admissions(&[certificate.clone()], &candidate.active_lanes, 2)
            .expect("the exact marker is idempotent");
        assert_eq!(
            state_block.merge_execution_write_set_root(),
            write_set_after_insert,
            "idempotent exact CAS replay must not change the committed write set"
        );
        let key = State::queue_plan_admission_registry_marker_key(&binding.registry_key())
            .expect("fixture registry key");
        let expected_payload =
            State::queue_plan_admission_registry_marker_payload(&binding.registry_value())
                .expect("fixture registry value");
        assert_eq!(
            state_block.world.smart_contract_state.get(&key),
            Some(&expected_payload)
        );
        // `StateBlock` owns exclusive MV storage transactions. Release this
        // overlay before opening an independent one for the conflict case.
        drop(state_block);

        let mut conflicting_block = state.block(carrier.header());
        let conflicting_value = crate::torii_proxy::QueuePlanAdmissionRegistryValueV2 {
            version: crate::torii_proxy::QUEUE_PLAN_ADMISSION_BINDING_VERSION_V2,
            binding_hash: Hash::new(b"conflicting-cas-value"),
        };
        conflicting_block.world.smart_contract_state.insert(
            key,
            State::queue_plan_admission_registry_marker_payload(&conflicting_value)
                .expect("well-formed conflicting registry value"),
        );
        assert!(matches!(
            conflicting_block.stage_queue_plan_admissions(
                &[certificate],
                &candidate.active_lanes,
                2,
            ),
            Err(MergeLedgerCommitError::ExecutionMarkerConflict(_))
        ));
    }

    #[test]
    fn queue_plan_registry_presence_is_bounded_and_malformed_markers_fail_closed() {
        let (state, validator_keypairs, _, _) = configured_two_lane_merge_state();
        let routing_plan = crate::queue::RoutingPlan::single(crate::queue::RoutingDecision::new(
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
        ));
        let (binding, _) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan,
            &validator_keypairs,
            1,
            0x5A,
        );
        assert!(
            !state
                .queue_plan_admission_registry_entrypoint_present(binding.entrypoint_hash.clone(),)
                .expect("absent registry presence lookup")
        );

        let key = State::queue_plan_admission_registry_marker_key(&binding.registry_key())
            .expect("fixture registry key");
        let payload =
            State::queue_plan_admission_registry_marker_payload(&binding.registry_value())
                .expect("fixture registry value");
        {
            let mut world = state.world.block();
            world.smart_contract_state.insert(key.clone(), payload);
            world.commit();
        }
        assert!(
            state
                .queue_plan_admission_registry_entrypoint_present(binding.entrypoint_hash.clone(),)
                .expect("well-formed registry presence lookup")
        );

        {
            let mut world = state.world.block();
            world.smart_contract_state.insert(key, vec![0x00]);
            world.commit();
        }
        assert!(
            state
                .queue_plan_admission_registry_entrypoint_present(binding.entrypoint_hash)
                .is_err(),
            "a malformed marker must not be treated as an absent or canonical admission"
        );
    }

    #[test]
    fn same_carrier_queue_plan_certificate_cannot_authorize_autonomous_execution() {
        let (state, validator_keypairs, _, parent) = configured_single_lane_merge_state();
        let tag = 0x61;
        let entrypoint = queue_plan_entrypoint_for_state_test(&state, tag);
        let routing_plan = crate::queue::RoutingPlan::single(crate::queue::RoutingDecision::new(
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
        ));
        let (binding, certificate) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan.clone(),
            &validator_keypairs,
            1,
            tag,
        );
        binding
            .validate_for_request(&state.chain_id, &entrypoint, &routing_plan)
            .expect("fixture certificate binds the autonomous transaction");
        {
            let mut world = state.world.block();
            world.accounts.insert(
                entrypoint.authority().clone(),
                AccountValue::new(AccountDetails::default()),
            );
            world.commit();
        }
        let source = autonomous_merge_source_for_queue_plan_admission_test(
            &state,
            &binding,
            entrypoint,
            routing_plan,
            &validator_keypairs,
        );
        let application_header = BlockHeader::new(
            nonzero!(2_u64),
            Some(parent.hash()),
            None,
            None,
            u64::try_from(parent.header().creation_time().as_millis())
                .expect("fixture parent time fits u64")
                .saturating_add(1),
            0,
        );
        assert!(
            state
                .build_merge_execution_batch_from_source_prefix(
                    1,
                    application_header.clone(),
                    vec![source.clone()],
                )
                .is_none(),
            "an availability-certified source remains ineligible while its binding is absent from pre-carrier WSV"
        );

        let registry_key = State::queue_plan_admission_registry_marker_key(&binding.registry_key())
            .expect("fixture registry key");
        {
            let mut world = state.world.block();
            world.smart_contract_state.insert(
                registry_key.clone(),
                State::queue_plan_admission_registry_marker_payload(&binding.registry_value())
                    .expect("fixture registry value"),
            );
            world.commit();
        }
        let batch = state
            .build_merge_execution_batch_from_source_prefix(1, application_header, vec![source])
            .expect("the otherwise-identical source is eligible with exact pre-carrier authority");
        let lifecycle = state.lane_consensus_lifecycle_snapshot();
        let active_lanes = lifecycle
            .nexus
            .lane_catalog
            .lanes()
            .iter()
            .map(|lane| MergeLaneBinding {
                lane_id: lane.id,
                dataspace_id: lane.dataspace_id,
                lane_config_hash: merge_lane_config_hash(lane),
                incarnation: lifecycle.incarnations[&lane.id],
                activation_height: lifecycle.activation_heights[&lane.id].saturating_add(1),
            })
            .collect::<Vec<_>>();
        let incarnation_entries = active_lanes
            .iter()
            .map(
                |lane| iroha_data_model::nexus::LaneLifecycleIncarnationEntry {
                    lane_id: lane.lane_id,
                    incarnation: lane.incarnation,
                },
            )
            .collect::<Vec<_>>();
        let base = crate::merge::MergeLedgerCandidate {
            version: crate::merge::MergeLedgerCandidate::VERSION,
            epoch_id: 1,
            view: 0,
            carrier_height: 2,
            carrier_parent_hash: parent.hash(),
            lane_catalog_hash: merge_lane_catalog_hash(&lifecycle.nexus.lane_catalog),
            active_lanes: active_lanes.clone(),
            incarnation_root: LaneLifecycleParameterV1::incarnation_root(&incarnation_entries),
            activation_root: crate::merge::merge_activation_root(&active_lanes),
            lane_snapshots: Vec::new(),
            execution_batch: Some(batch),
            lane_drain_certificates: Vec::new(),
            queue_plan_admissions: Vec::new(),
            global_state_root: crate::merge::reduce_merge_hint_roots(&[]),
        };
        state
            .validate_merge_candidate_for_global_round(&base, &parent.header(), 0)
            .expect("fixture base candidate is valid with committed pre-carrier authority");

        {
            let mut world = state.world.block();
            world.smart_contract_state.remove(registry_key);
            world.commit();
        }
        assert!(matches!(
            state.merge_candidate_with_queue_plan_admissions(
                &parent.header(),
                0,
                Some(base),
                vec![certificate],
            ),
            Err(MergeLedgerCommitError::ExecutionBatchInvalid(_))
                | Err(MergeLedgerCommitError::ExecutionDivergence(_))
        ));
        assert_eq!(
            state
                .queue_plan_admission_binding_registry_match(&binding)
                .expect("post-negative registry lookup"),
            QueuePlanAdmissionRegistryMatch::Absent,
            "the rejected same-carrier control must not leak an admission marker into WSV"
        );
    }

    #[test]
    #[expect(
        clippy::too_many_lines,
        reason = "one linear test covers participant, incarnation, conflict, and malformed durable evidence"
    )]
    fn pending_queue_plan_evidence_blocks_every_bound_route_and_classifies_losers() {
        let (state, validator_keypairs, _, _) = configured_two_lane_merge_state();
        let participant_lane = LaneId::new(1);
        let routing_plan = crate::queue::RoutingPlan::native_amx(
            crate::queue::RoutingDecision::new(LaneId::SINGLE, DataSpaceId::UNIVERSAL),
            vec![crate::queue::RouteLeg::new(
                crate::queue::RoutingDecision::new(participant_lane, DataSpaceId::UNIVERSAL),
                crate::queue::RouteLegRole::Participant,
            )],
        );
        let (binding, certificate) = queue_plan_admission_certificate_for_state_test(
            &state,
            routing_plan,
            &validator_keypairs,
            1,
            0x61,
        );
        let pending_hash = state
            .kura
            .persist_pending_queue_plan_admission_certificate(&certificate)
            .expect("persist participant-bound QueuePlan certificate");
        let participant_incarnation = state
            .lane_incarnation(participant_lane)
            .expect("participant lane incarnation");
        assert!(
            state.lane_has_drain_blocking_evidence(
                participant_lane,
                DataSpaceId::UNIVERSAL,
                participant_incarnation,
            ),
            "a durable pending participant claim must block its exact lane incarnation"
        );
        assert!(
            !state.lane_has_drain_blocking_evidence(
                participant_lane,
                DataSpaceId::UNIVERSAL,
                Hash::new(b"unrelated-recreated-incarnation"),
            ),
            "pending evidence from another incarnation must not block a recreated lane"
        );

        state
            .kura
            .remove_pending_queue_plan_admission_certificate(pending_hash)
            .expect("remove first pending fixture");
        let replacement_incarnation = Hash::new(b"replacement-participant-incarnation");
        let _ = state
            .lane_incarnations
            .write()
            .insert(participant_lane, replacement_incarnation);
        let stale_hash = state
            .kura
            .persist_pending_queue_plan_admission_certificate(&certificate)
            .expect("persist authenticated stale QueuePlan certificate");
        assert_eq!(
            state
                .classify_pending_queue_plan_admission(&certificate, 2)
                .expect("authenticated stale evidence is classifiable")
                .1,
            PendingQueuePlanAdmissionDisposition::Stale
        );
        assert!(
            !state.lane_has_drain_blocking_evidence(
                participant_lane,
                DataSpaceId::UNIVERSAL,
                replacement_incarnation,
            ),
            "an authenticated stale claim is a definitive loser, not a drain blocker"
        );
        state
            .kura
            .remove_pending_queue_plan_admission_certificate(stale_hash)
            .expect("remove stale pending fixture");
        let _ = state
            .lane_incarnations
            .write()
            .insert(participant_lane, participant_incarnation);

        let registry_key = State::queue_plan_admission_registry_marker_key(&binding.registry_key())
            .expect("fixture registry key");
        let conflicting_value = crate::torii_proxy::QueuePlanAdmissionRegistryValueV2 {
            version: crate::torii_proxy::QUEUE_PLAN_ADMISSION_BINDING_VERSION_V2,
            binding_hash: Hash::new(b"different-immutable-queue-plan-binding"),
        };
        let conflicting_payload =
            State::queue_plan_admission_registry_marker_payload(&conflicting_value)
                .expect("fixture conflicting registry value");
        {
            let mut world = state.world.block();
            world
                .smart_contract_state
                .insert(registry_key.clone(), conflicting_payload);
            world.commit();
        }
        assert_eq!(
            state
                .classify_pending_queue_plan_admission(&certificate, 2)
                .expect("well-formed conflicting evidence is classifiable")
                .1,
            PendingQueuePlanAdmissionDisposition::DefinitiveConflict
        );
        assert_eq!(
            state
                .queue_plan_admission_binding_registry_match(&binding)
                .expect("well-formed conflicting marker"),
            QueuePlanAdmissionRegistryMatch::Conflict
        );
        let conflict_hash = state
            .kura
            .persist_pending_queue_plan_admission_certificate(&certificate)
            .expect("persist definitive conflict fixture");
        assert!(
            !state.lane_has_drain_blocking_evidence(
                participant_lane,
                DataSpaceId::UNIVERSAL,
                participant_incarnation,
            ),
            "a different well-formed immutable owner makes the pending claim a definitive loser"
        );
        state
            .kura
            .remove_pending_queue_plan_admission_certificate(conflict_hash)
            .expect("remove conflict pending fixture");
        {
            let mut world = state.world.block();
            world.smart_contract_state.insert(
                registry_key.clone(),
                State::queue_plan_admission_registry_marker_payload(&binding.registry_value())
                    .expect("exact fixture registry value"),
            );
            world.commit();
        }
        assert_eq!(
            state
                .queue_plan_admission_binding_registry_match(&binding)
                .expect("exact registry marker"),
            QueuePlanAdmissionRegistryMatch::Exact
        );
        {
            let mut world = state.world.block();
            world.smart_contract_state.insert(registry_key, vec![0x00]);
            world.commit();
        }
        assert!(
            state
                .queue_plan_admission_binding_registry_match(&binding)
                .is_err(),
            "malformed WSV registry markers must be reported as errors"
        );

        let malformed_hash = state
            .kura
            .persist_pending_queue_plan_admission_certificate(&[0xFF])
            .expect("persist malformed pending evidence");
        assert!(
            state.lane_has_drain_blocking_evidence(
                participant_lane,
                DataSpaceId::UNIVERSAL,
                participant_incarnation,
            ),
            "malformed durable pending evidence must fail closed for drain"
        );
        state
            .kura
            .remove_pending_queue_plan_admission_certificate(malformed_hash)
            .expect("remove malformed pending fixture");
    }

    fn next_relay_merge_entry(
        state: &State,
        lane_height: u64,
        validator_keypairs: &[KeyPair],
        commit_keypairs: &[KeyPair],
    ) -> MergeLedgerEntry {
        next_relay_merge_entry_for_lane(
            state,
            lane_height,
            LaneId::SINGLE,
            validator_keypairs,
            commit_keypairs,
        )
    }

    fn next_relay_merge_entry_for_lane(
        state: &State,
        lane_height: u64,
        lane_id: LaneId,
        validator_keypairs: &[KeyPair],
        commit_keypairs: &[KeyPair],
    ) -> MergeLedgerEntry {
        let envelope =
            sample_lane_relay_envelope_for_state(state, lane_height, lane_id, validator_keypairs);
        state
            .record_lane_relay(&envelope)
            .expect("record next contiguous merge relay");
        let candidate = state
            .merge_entry_candidates_from_lane_relays()
            .into_iter()
            .next()
            .expect("next relay merge candidate");
        let qc = merge_qc_for_candidate(state, &candidate, commit_keypairs, &[0]);
        merge_entry_from_candidate(candidate, qc)
    }

    fn store_and_commit_exact_merge_carrier(
        state: &State,
        previous: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> SignedBlock {
        let carrier = certified_merge_carrier_after(previous, entry);
        state
            .kura
            .store_block_with_merge_entry(Arc::new(carrier.clone()), entry)
            .expect("store exact merge carrier and full entry");
        commit_exact_merge_carrier_to_state(state, &carrier, entry);
        carrier
    }

    fn persist_merge_entry_with_exact_carrier(mut entry: MergeLedgerEntry) -> Arc<Kura> {
        let kura = Kura::blank_kura_for_testing();
        let parent = empty_global_block_after(None);
        let carrier = empty_global_block_after(Some(&parent));
        entry.merge_qc.carrier_height = carrier.header().height().get();
        entry.merge_qc.carrier_parent_hash = carrier
            .header()
            .prev_block_hash()
            .expect("non-genesis carrier has a parent");
        entry.merge_qc.view = carrier.header().view_change_index();
        let carrier = certified_merge_carrier_after(&parent, &entry);
        kura.store_block(Arc::new(parent))
            .expect("store invalid-history carrier parent");
        kura.store_block_with_merge_entry(Arc::new(carrier), &entry)
            .expect("store exact invalid-history carrier fixture");
        kura
    }

    fn panic_payload_text(payload: Box<dyn core::any::Any + Send>) -> String {
        if let Some(message) = payload.downcast_ref::<String>() {
            return message.clone();
        }
        if let Some(message) = payload.downcast_ref::<&'static str>() {
            return (*message).to_owned();
        }
        "non-string panic payload".to_owned()
    }

    #[test]
    fn staged_merge_missing_transaction_block_mutates_nothing() {
        let (state, validator_keypairs, commit_keypairs, parent) =
            configured_single_lane_merge_state();
        let entry = next_relay_merge_entry(&state, 1, &validator_keypairs, &commit_keypairs);
        let carrier = certified_merge_carrier_after(&parent, &entry);
        state
            .kura
            .store_block_with_merge_entry(Arc::new(carrier.clone()), &entry)
            .expect("store exact merge carrier before State commit");

        let committed_height_before = state.committed_height();
        let state_hash_before = state.lane_execution_state_hash();
        let roots_before = state.world.merge_hint_roots.view().clone();
        let global_root_before = *state.world.merge_global_state_root.view();
        let cache_before = state.merge_ledger.snapshot();
        let mut state_block = state
            .block_with_certified_merge_entry(carrier.header().clone(), &entry)
            .expect("stage exact certified merge entry");
        state_block.block_hashes.push(carrier.hash());

        let error = state_block
            .commit()
            .expect_err("missing transaction membership must abort the staged merge");
        assert!(matches!(error, TransactionsBlockError::MissingInsertBlock));
        assert_eq!(state.committed_height(), committed_height_before);
        assert_eq!(state.lane_execution_state_hash(), state_hash_before);
        assert_eq!(*state.world.merge_hint_roots.view(), roots_before);
        assert_eq!(
            *state.world.merge_global_state_root.view(),
            global_root_before
        );
        assert_eq!(state.merge_ledger.snapshot(), cache_before);
        let admission = state.merge_admission.read();
        assert!(admission.latest_entry().is_none());
        assert!(admission.latest_lane_snapshots.is_empty());
        assert!(admission.latest_execution_heights.is_empty());
    }

    #[test]
    fn durable_kura_carrier_requires_exact_committed_state_carrier_before_publication() {
        let (state, validator_keypairs, commit_keypairs, parent) =
            configured_single_lane_merge_state();
        let entry = next_relay_merge_entry(&state, 1, &validator_keypairs, &commit_keypairs);
        let carrier = certified_merge_carrier_after(&parent, &entry);
        state
            .kura
            .store_block_with_merge_entry(Arc::new(carrier.clone()), &entry)
            .expect("store exact Kura carrier");

        let state_hash_before = state.lane_execution_state_hash();
        let cache_before = state.merge_ledger.snapshot();
        let error = state
            .record_globally_committed_merge_entry(&entry, MergeLedgerPublicationMode::LiveCommit)
            .expect_err("Kura durability alone must not publish merge admission");
        assert!(matches!(
            error,
            MergeLedgerCommitError::ExecutionStatePublication(reason)
                if reason.contains("absent from committed State history")
        ));
        assert_eq!(state.lane_execution_state_hash(), state_hash_before);
        assert_eq!(state.merge_ledger.snapshot(), cache_before);
        {
            let admission = state.merge_admission.read();
            assert!(admission.latest_entry().is_none());
            assert!(admission.latest_lane_snapshots.is_empty());
            assert!(admission.latest_execution_heights.is_empty());
        }

        commit_exact_merge_carrier_to_state(&state, &carrier, &entry);
        assert_eq!(state.merge_ledger.snapshot().len(), 1);
        assert_eq!(state.merge_ledger.latest().as_deref(), Some(&entry));
        {
            let admission = state.merge_admission.read();
            assert_eq!(admission.latest_entry(), Some(&entry));
            assert_eq!(admission.expected_epoch(), 2);
            assert_eq!(admission.latest_lane_snapshots.len(), 1);
        }

        let (stored, event) = state
            .record_globally_committed_merge_entry(&entry, MergeLedgerPublicationMode::LiveCommit)
            .expect("publication retry for the exact State carrier is idempotent");
        assert_eq!(stored.as_ref(), &entry);
        assert!(event.is_none());
        assert_eq!(state.merge_ledger.snapshot().len(), 1);
    }

    #[test]
    fn stale_staged_merge_fails_before_wsv_when_admission_advances() {
        let (state, validator_keypairs, commit_keypairs, parent) =
            configured_single_lane_merge_state();
        let first = next_relay_merge_entry(&state, 1, &validator_keypairs, &commit_keypairs);
        let first_carrier = store_and_commit_exact_merge_carrier(&state, &parent, &first);
        let second = next_relay_merge_entry(&state, 2, &validator_keypairs, &commit_keypairs);
        let second_carrier = certified_merge_carrier_after(&first_carrier, &second);
        state
            .kura
            .store_block_with_merge_entry(Arc::new(second_carrier.clone()), &second)
            .expect("store second exact Kura carrier");

        let mut stale_block = state
            .block_with_certified_merge_entry(second_carrier.header().clone(), &second)
            .expect("stage epoch two before the competing admission publication");
        stale_block.block_hashes.push(second_carrier.hash());
        insert_empty_transaction_block_for_state_commit(&mut stale_block, &second_carrier);

        {
            let mut admission = state.merge_admission.write();
            admission
                .validate_next(&second)
                .expect("competing epoch two admission is initially valid");
            admission.record(&second);
        }
        let committed_height_before = state.committed_height();
        let state_hash_before = state.lane_execution_state_hash();
        let roots_before = state.world.merge_hint_roots.view().clone();
        let global_root_before = *state.world.merge_global_state_root.view();
        let cache_before = state.merge_ledger.snapshot();

        let error = stale_block
            .commit()
            .expect_err("stale staged epoch two must fail admission preflight");
        assert!(matches!(error, TransactionsBlockError::MergeAdmission));
        assert_eq!(state.committed_height(), committed_height_before);
        assert_eq!(state.lane_execution_state_hash(), state_hash_before);
        assert_eq!(*state.world.merge_hint_roots.view(), roots_before);
        assert_eq!(
            *state.world.merge_global_state_root.view(),
            global_root_before
        );
        assert_eq!(state.merge_ledger.snapshot(), cache_before);
        assert_eq!(state.merge_ledger.latest().as_deref(), Some(&first));
    }

    #[test]
    fn same_block_merge_and_lane_replacement_preserves_history_and_prunes_old_progress() {
        let replaced_lane = LaneId::new(1);
        let (state, validator_keypairs, commit_keypairs, parent) =
            configured_two_lane_merge_state();
        let entry = next_relay_merge_entry_for_lane(
            &state,
            1,
            replaced_lane,
            &validator_keypairs,
            &commit_keypairs,
        );
        let carrier = certified_merge_carrier_after(&parent, &entry);
        state
            .kura
            .store_block_with_merge_entry(Arc::new(carrier.clone()), &entry)
            .expect("store merge+lifecycle carrier");

        let old_incarnation = state
            .lane_incarnation(replaced_lane)
            .expect("replaceable lane has an incarnation");
        let catalog = state.nexus_snapshot().lane_catalog;
        let canonical_incarnations =
            iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations(
                &catalog,
                &state.lane_incarnations_snapshot(),
            )
            .expect("current lane incarnation set is canonical");
        let plan = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![
                catalog
                    .lanes()
                    .iter()
                    .find(|lane| lane.id == replaced_lane)
                    .expect("replaceable lane is in the catalog")
                    .clone(),
            ],
            retire: vec![replaced_lane],
        };
        let payload = iroha_data_model::nexus::LaneLifecycleParameterV1::new(
            &catalog,
            &canonical_incarnations,
            plan,
        )
        .expect("same-id lifecycle replacement payload is canonical");

        let mut state_block = state
            .block_with_certified_merge_entry(carrier.header().clone(), &entry)
            .expect("stage merge before the same-block lane replacement");
        {
            let mut transaction = state_block.transaction();
            transaction
                .stage_consensus_lane_lifecycle(&payload)
                .expect("stage same-block lane replacement after merge certification");
            transaction.apply();
        }
        assert!(state_block.pending_autoscale_lifecycle.is_some());
        state_block.block_hashes.push(carrier.hash());
        insert_empty_transaction_block_for_state_commit(&mut state_block, &carrier);
        state_block
            .commit()
            .expect("merge-covered lane progress must not block same-block replacement");

        let new_incarnation = state
            .lane_incarnation(replaced_lane)
            .expect("replacement lane has a fresh incarnation");
        assert_ne!(new_incarnation, old_incarnation);
        let admission = state.merge_admission.read();
        assert_eq!(admission.latest_entry(), Some(&entry));
        assert!(
            admission
                .binding_history
                .historical_incarnations
                .contains(&old_incarnation),
            "the globally committed old binding must remain in authenticated history"
        );
        assert!(
            admission
                .latest_lane_snapshots
                .keys()
                .all(|(lane_id, _, _)| *lane_id != replaced_lane),
            "replacement must prune old-incarnation relay tips"
        );
        assert!(
            admission
                .latest_execution_heights
                .keys()
                .all(|(lane_id, _, _)| *lane_id != replaced_lane),
            "replacement must prune old-incarnation execution tips"
        );
        let next_lane_height = admission
            .latest_lane_snapshots
            .get(&(replaced_lane, DataSpaceId::UNIVERSAL, new_incarnation))
            .map_or(1, |snapshot| snapshot.lane_block_height.saturating_add(1));
        assert_eq!(
            next_lane_height, 1,
            "fresh incarnation must restart at lane h1"
        );
    }

    #[test]
    fn empty_and_zero_activation_merge_entries_fail_live_and_recovery_with_same_rule() {
        let empty = MergeLedgerEntry {
            version: MergeLedgerEntry::VERSION,
            epoch_id: 1,
            lane_catalog_hash: Hash::new(b"catalog"),
            active_lanes: Vec::new(),
            incarnation_root: Hash::new(b"incarnations"),
            activation_root: Hash::new(b"activations"),
            lane_snapshots: Vec::new(),
            execution_batch: None,
            lane_drain_certificates: Vec::new(),
            queue_plan_admissions: Vec::new(),
            global_state_root: Hash::new(b"root"),
            merge_qc: dummy_merge_qc(),
        };
        let mut zero_activation =
            merge_entry_from_candidate(merge_candidate_with_lanes(1, 1), dummy_merge_qc());
        zero_activation.active_lanes[0].activation_height = 0;

        for (label, entry, expected_live, expected_recovery) in [
            (
                "empty",
                empty,
                "merge ledger entry must include a lane snapshot, execution batch, or drain certificate",
                "EmptyEntry",
            ),
            (
                "zero activation",
                zero_activation,
                "zero activation height",
                "zero activation height",
            ),
        ] {
            let live_state = State::new_for_testing(
                World::default(),
                Kura::blank_kura_for_testing(),
                LiveQueryStore::start_test(),
            );
            let live_error = live_state
                .validate_certified_merge_entry_for_global_order(&entry)
                .expect_err("malformed live merge entry must fail closed");
            assert!(
                live_error.to_string().contains(expected_live),
                "{label} live rejection used the wrong rule: {live_error}"
            );

            let kura = persist_merge_entry_with_exact_carrier(entry);
            let recovery = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                State::new_for_testing(World::default(), kura, LiveQueryStore::start_test())
            }));
            let panic = match recovery {
                Ok(_) => panic!("malformed globally carried history must abort recovery"),
                Err(payload) => panic_payload_text(payload),
            };
            assert!(
                panic.contains(expected_recovery),
                "{label} recovery rejection used the wrong rule: {panic}"
            );
        }
    }

    #[test]
    fn merge_consensus_snapshot_never_mixes_lifecycle_replacement_with_old_admission_tip() {
        let replaced_lane = LaneId::new(1);
        let (state, _validator_keypairs, _commit_keypairs, _parent) =
            configured_two_lane_merge_state();
        let state = Arc::new(state);
        let old_incarnation = state
            .lane_incarnation(replaced_lane)
            .expect("replaceable lane has an incarnation");
        let old_activation =
            state.lane_incarnation_activation_heights_snapshot()[&replaced_lane].saturating_add(1);
        let settlement =
            empty_merge_settlement(replaced_lane, old_incarnation, DataSpaceId::UNIVERSAL, 1);
        let old_tip = MergeLaneSnapshot {
            lane_id: replaced_lane,
            lane_incarnation: old_incarnation,
            incarnation_activation_height: old_activation,
            proposal_height: old_activation,
            dataspace_id: DataSpaceId::UNIVERSAL,
            lane_block_height: 1,
            tip_hash: HashOf::from_untyped_unchecked(Hash::new(b"old-tip")),
            merge_hint_root: Hash::new(b"old-hint"),
            settlement_hash: canonical_merge_settlement_hash(&settlement)
                .expect("old tip settlement hashes canonically"),
            settlement_commitment: settlement,
            relay_envelope: None,
        };
        let old_tip_key = (replaced_lane, DataSpaceId::UNIVERSAL, old_incarnation);
        state
            .merge_admission
            .write()
            .latest_lane_snapshots
            .insert(old_tip_key, old_tip);

        let catalog = state.nexus_snapshot().lane_catalog;
        let replacement = iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![
                catalog
                    .lanes()
                    .iter()
                    .find(|lane| lane.id == replaced_lane)
                    .expect("replaceable lane is in the catalog")
                    .clone(),
            ],
            retire: vec![replaced_lane],
        };
        let admission_guard = state.merge_admission.write();
        let (started_tx, started_rx) = std::sync::mpsc::channel();
        let reader_state = Arc::clone(&state);
        let reader = std::thread::spawn(move || {
            started_tx.send(()).expect("signal snapshot reader start");
            let snapshot = reader_state.merge_consensus_snapshot();
            (
                snapshot.lifecycle.incarnations[&replaced_lane],
                snapshot
                    .admission
                    .latest_lane_snapshots
                    .contains_key(&old_tip_key),
            )
        });
        started_rx.recv().expect("snapshot reader started");

        let writer_state = Arc::clone(&state);
        let writer =
            std::thread::spawn(move || writer_state.apply_lane_lifecycle_shared(&replacement));
        let write_generation_deadline = Instant::now() + Duration::from_secs(5);
        let observed_write_generation = loop {
            if state.state_view_generation() % 2 == 1 {
                break true;
            }
            if Instant::now() >= write_generation_deadline {
                break false;
            }
            std::thread::sleep(Duration::from_millis(1));
        };
        drop(admission_guard);
        writer
            .join()
            .expect("lifecycle writer thread must not panic")
            .expect("same-id lifecycle replacement must succeed");
        assert!(
            observed_write_generation,
            "test must overlap the snapshot with an active lifecycle write generation"
        );
        let (observed_incarnation, observed_old_tip) =
            reader.join().expect("snapshot reader must not panic");
        let new_incarnation = state
            .lane_incarnation(replaced_lane)
            .expect("replacement lane has a current incarnation");
        assert_ne!(new_incarnation, old_incarnation);
        assert_eq!(observed_incarnation, new_incarnation);
        assert!(
            !observed_old_tip,
            "a stable post-replacement consensus snapshot must not retain the old tip"
        );
    }

    #[test]
    fn apply_without_execution_updates_commit_topology_from_world_peers() {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let state = State::new_for_testing(World::default(), kura, query);

        let keypairs = configure_commit_topology(&state, 4);
        let base_topology: Vec<_> = keypairs
            .iter()
            .map(|kp| PeerId::new(kp.public_key().clone()))
            .collect();
        let new_peer = PeerId::new(
            crate::state::checked_keypair_with_algorithm(Algorithm::BlsNormal)
                .public_key()
                .clone(),
        );
        {
            let mut world_block = state.world.block();
            {
                let mut peers = world_block.peers_mut_for_testing().transaction();
                peers.clear();
                peers.extend(base_topology.clone());
                peers.push(new_peer.clone());
                peers.apply();
            }
            world_block.commit();
        }

        let block = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .sign(keypairs[0].private_key())
            .unpack(|_| {});
        let signed_block: SignedBlock = block.into();
        let mut state_block = state.block(signed_block.header());

        let valid = ValidBlock::validate_unchecked(signed_block, &mut state_block).unpack(|_| {});
        let committed = valid.commit_unchecked().unpack(|_| {});
        let prev_hash = committed.as_ref().hash();
        let _ = state_block.apply_without_execution(&committed, base_topology.clone());
        state_block.commit().expect("commit state block");

        let mut expected_topology = Topology::new(base_topology.clone());
        let mut world_peers = base_topology.clone();
        world_peers.push(new_peer);
        expected_topology.block_committed(world_peers, prev_hash);
        let expected = expected_topology.as_ref().to_vec();

        let view = state.view();
        let actual: Vec<_> = view.commit_topology().iter().cloned().collect();
        assert_eq!(actual, expected);
        let prev: Vec<_> = view.prev_commit_topology().iter().cloned().collect();
        assert_eq!(prev, base_topology);
    }

    #[test]
    fn v2_authority_skips_legacy_roster_but_preserves_topology_transition() {
        let kura = Kura::blank_kura_for_testing();
        let state = State::new_for_testing(
            World::default(),
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
        );
        let keypairs = configure_commit_topology(&state, 4);
        let base_topology = keypairs
            .iter()
            .map(|keypair| PeerId::new(keypair.public_key().clone()))
            .collect::<Vec<_>>();
        let block: SignedBlock = BlockBuilder::new(vec![dummy_accepted_transaction()])
            .chain(0, None)
            .sign(keypairs[0].private_key())
            .unpack(|_| {})
            .into();
        let mut state_block = state.block(block.header());
        let valid = ValidBlock::validate_unchecked(block, &mut state_block).unpack(|_| {});
        let committed = valid.commit_unchecked().unpack(|_| {});
        let block_hash = committed.as_ref().hash();

        let _ = state_block
            .apply_without_execution_with_verified_v2_finality(&committed, base_topology.clone());
        state_block
            .commit()
            .expect("commit v2-authorized state block");

        let mut expected_topology = Topology::new(base_topology.clone());
        expected_topology.block_committed(base_topology.clone(), block_hash);
        assert_eq!(
            state.commit_topology_snapshot(),
            expected_topology.as_ref().to_vec(),
            "v2 authority must preserve the ordinary commit-topology transition"
        );
        assert_eq!(state.prev_commit_topology_snapshot(), base_topology);
        assert!(
            state.world_view().commit_qcs().get(&block_hash).is_none(),
            "v2 authority must not populate the legacy WSV commit-QC archive"
        );
        assert!(
            state
                .commit_roster_journal
                .read()
                .get(1, block_hash)
                .is_none(),
            "v2 authority must not populate the legacy commit-roster journal"
        );
        assert!(
            kura.read_roster_metadata(1).is_none(),
            "v2 authority must not populate the legacy roster sidecar"
        );
    }

