    fn merge_signers_bitmap(
        signers: &BTreeSet<iroha_data_model::block::consensus::ValidatorIndex>,
        roster_len: usize,
    ) -> Vec<u8> {
        if roster_len == 0 {
            return Vec::new();
        }
        let mut bitmap = vec![0u8; roster_len.div_ceil(8)];
        for signer in signers {
            let Ok(idx) = usize::try_from(*signer) else {
                continue;
            };
            if idx >= roster_len {
                continue;
            }
            let byte = idx / 8;
            let bit = idx % 8;
            bitmap[byte] |= 1u8 << bit;
        }
        bitmap
    }

    fn merge_qc_for_candidate(
        state: &State,
        candidate: &crate::merge::MergeLedgerCandidate,
        keypairs: &[KeyPair],
        signers: &[usize],
    ) -> MergeQuorumCertificate {
        if state.latest_block_hash_fast().is_none() {
            let mut block_hashes = state.block_hashes.block();
            block_hashes.push_for_tests(candidate.carrier_parent_hash);
            block_hashes.commit_for_tests();
        }
        let validator_set = keypairs
            .iter()
            .map(|keypair| PeerId::new(keypair.public_key().clone()))
            .collect::<Vec<_>>();
        let validator_set_hash = HashOf::new(&validator_set);
        let message_digest = crate::merge::merge_qc_message_digest(
            &state.chain_id,
            candidate,
            VALIDATOR_SET_HASH_VERSION_V1,
            validator_set_hash,
        );
        let mut signers_set = BTreeSet::new();
        let mut signature_payloads = Vec::with_capacity(signers.len());
        let mut signer_proofs = Vec::with_capacity(signers.len());
        for idx in signers {
            let idx_u32 = u32::try_from(*idx).expect("signer index fits in u32");
            signers_set.insert(idx_u32);
            let signature =
                Signature::try_new(keypairs[*idx].private_key(), message_digest.as_ref())
                    .expect("test fixture signing should succeed");
            signature_payloads.push(signature.payload().to_vec());
            signer_proofs.push(iroha_data_model::merge::MergeSignerProof {
                signer: idx_u32,
                proof_of_possession: iroha_crypto::bls_normal_pop_prove(
                    keypairs[*idx].private_key(),
                )
                .expect("test signer PoP"),
            });
        }
        let signature_refs: Vec<&[u8]> = signature_payloads.iter().map(Vec::as_slice).collect();
        let aggregate_signature = iroha_crypto::bls_normal_aggregate_signatures(&signature_refs)
            .expect("aggregate merge signatures");
        let signers_bitmap = merge_signers_bitmap(&signers_set, keypairs.len());
        MergeQuorumCertificate::new(
            candidate.view,
            candidate.epoch_id,
            candidate.carrier_height,
            candidate.carrier_parent_hash,
            crate::merge::merge_chain_id_digest(&state.chain_id),
            VALIDATOR_SET_HASH_VERSION_V1,
            validator_set_hash,
            validator_set,
            signers_bitmap,
            signer_proofs,
            aggregate_signature,
            message_digest,
        )
    }

    fn setup_nexus_fee_merge_state(
        sponsor_balance: Quantity,
        fee_amount: Quantity,
        source_id: [u8; 32],
    ) -> (State, AccountId, AssetDefinitionId, Vec<KeyPair>) {
        let (sponsor_id, _sponsor_kp) = gen_account_in("wonderland");
        let (custody_id, _custody_kp) = gen_account_in("wonderland");
        let program_id = FeeSponsorProgramId::new(
            sponsor_id.clone(),
            "merge-receipts".parse().expect("program name"),
        );
        let lease_id = Hash::new(b"merge-fee-sponsor-spend-lease");
        let domain_id = DomainId::try_new("wonderland", "universal").expect("domain id");
        let domain = Domain::new(domain_id.clone()).build(&sponsor_id);
        let sponsor = Account::new(sponsor_id.clone()).build(&sponsor_id);
        let custody = Account::new(custody_id.clone()).build(&sponsor_id);
        let fee_asset_selector = iroha_config::parameters::defaults::nexus::fees::fee_asset_id();
        let asset_def_id = AssetDefinitionId::parse_address_literal(&fee_asset_selector)
            .expect("default Nexus XOR fee asset id must be canonical");
        let asset_definition =
            AssetDefinition::numeric(asset_def_id.clone()).with_name("xor".to_string());
        let mut asset_definition = asset_definition.build(&sponsor_id);
        asset_definition.total_quantity = sponsor_balance.clone();
        let custody_asset = Asset::new(
            AssetId::of(asset_def_id.clone(), custody_id.clone()),
            sponsor_balance.clone(),
        );
        let mut world = World::with_assets(
            [domain],
            [sponsor, custody],
            [asset_definition],
            [custody_asset],
            [],
        );
        let fee_asset_alias: AssetDefinitionAlias =
            "xor#universal".parse().expect("canonical fee asset alias");
        world.asset_definition_aliases =
            std::iter::once((fee_asset_alias.clone(), asset_def_id.clone())).collect();
        world.asset_definition_alias_bindings = std::iter::once((
            asset_def_id.clone(),
            AssetDefinitionAliasBindingRecord {
                alias: fee_asset_alias,
                lease_expiry_ms: None,
                grace_until_ms: None,
                bound_at_ms: 0,
            },
        ))
        .collect();
        let allocation = VerifiedFeeSponsorVaultAllocation::new(
            program_id.clone(),
            1,
            asset_def_id.clone(),
            Quantity::from(1_000_000_u32),
            DataSpaceId::UNIVERSAL,
            1,
            Hash::new(b"merge-fee-sponsor-source-state"),
            100,
            lease_id,
            Hash::new(b"merge-fee-sponsor-proof"),
            *Hash::new(b"merge-fee-sponsor-statement").as_ref(),
            Hash::new(b"merge-fee-sponsor-proof-digest"),
            1,
            *Hash::new(b"merge-fee-sponsor-manifest").as_ref(),
            AxtFastpqBinding {
                parameter: "fastpq-lane-balanced".to_owned(),
                source_dsid: DataSpaceId::UNIVERSAL.as_u64(),
                source_dataspace: "universal".to_owned(),
                source_receipt_id: "merge-fee-sponsor-receipt".to_owned(),
                source_tx_commitment: "aa".repeat(32),
                claim_type: "fee_sponsor_vault_allocation".to_owned(),
                claim_digest: "bb".repeat(32),
                witness_commitment: "cc".repeat(32),
                policy_commitment: "dd".repeat(32),
                verified_effect_type: "fee_sponsor_vault_allocation".to_owned(),
                corridor: "fee-sponsor".to_owned(),
                verifier_id: "fastpq".to_owned(),
                verifier_version: "v1".to_owned(),
                target_dsids: vec![DataSpaceId::UNIVERSAL.as_u64()],
                effect_binding: None,
            },
        );
        let allocation_key: Name =
            VerifiedFeeSponsorVaultAllocation::state_key_for(&program_id, &asset_def_id, &lease_id)
                .parse()
                .expect("verified fee allocation state key");
        world.smart_contract_state_mut_for_testing().insert(
            allocation_key,
            norito::to_bytes(&Json::try_new(allocation).expect("verified fee allocation JSON"))
                .expect("verified fee allocation state"),
        );
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let mut state = State::new_for_testing(world, kura, query);
        assert_eq!(
            state
                .view()
                .world()
                .asset_definition(&asset_def_id)
                .expect("fee asset definition exists")
                .total_quantity(),
            &sponsor_balance,
            "fee fixture supply must equal its seeded sponsor balance"
        );
        let nexus = iroha_config::parameters::actual::Nexus {
            enabled: true,
            fees: iroha_config::parameters::actual::NexusFees {
                fee_asset_id: "xor#universal".to_owned(),
                settlement_mode:
                    iroha_config::parameters::actual::NexusFeeSettlementMode::LaneRelayBurn,
                sponsor_vault_custody_account_id: custody_id.clone(),
                ..iroha_config::parameters::actual::NexusFees::default()
            },
            ..iroha_config::parameters::actual::Nexus::default()
        };
        state.set_nexus(nexus).expect("apply Nexus config");

        let (validator_ids, validator_keypairs) = bls_accounts_in("validators", 4);
        seed_consensus_keys_with_pops(&state, &validator_keypairs);
        install_lane_manifest_registry(
            &state,
            &[(LaneId::new(0), DataSpaceId::UNIVERSAL, validator_ids)],
        );
        let commit_keypairs = configure_commit_topology_preserving_world_peers(&state, 1);
        let envelope =
            sample_lane_relay_envelope_for_state(&state, 1, LaneId::new(0), &validator_keypairs);
        let mut settlement = envelope.settlement_commitment.clone();
        // The fee receipt belongs to the same transaction as the base
        // settlement receipt. Bind both receipt categories to the same source
        // so `tx_count` continues to describe one distinct transaction.
        settlement.receipts[0].source_id = source_id;
        settlement.nexus_fee_receipts = vec![NexusFeeReceipt {
            version: NexusFeeReceipt::VERSION,
            source_id,
            dataspace_id: envelope.dataspace_id,
            lane_id: envelope.lane_id,
            block_height: envelope.block_height,
            debit_source: FeeDebitSource::SponsorProgram(program_id),
            fee_asset_id: asset_def_id.clone(),
            program_revision: Some(1),
            lease_id: Some(lease_id),
            fee_amount: fee_amount.clone(),
            schedule: NexusFeeScheduleInputs {
                tx_bytes_len: 0,
                instruction_count: 0,
                gas_used: 0,
                base_fee: fee_amount,
                per_byte_fee: Quantity::zero(),
                per_instruction_fee: Quantity::zero(),
                per_gas_unit_fee: Quantity::zero(),
            },
        }];
        let lane_block_descriptor_hash = envelope.lane_block_descriptor_hash;
        let envelope = LaneRelayEnvelope::new(
            envelope.block_header.clone(),
            envelope.qc.clone(),
            envelope.da_commitment_hash,
            settlement,
            envelope.rbc_bytes_total,
        )
        .expect("fee relay envelope")
        .with_lane_block_descriptor_hash(lane_block_descriptor_hash);
        let fastpq_proof = sample_fastpq_proof_material(&envelope, 0);
        let envelope = envelope
            .with_manifest_root(Some([0x44; 32]))
            .with_fastpq_proof_material(Some(fastpq_proof));
        // The governed proof is verified at proposal height 1, so publish the
        // corresponding committed carrier before the record is admitted.
        ensure_merge_carrier_parent_for_test(&state);
        seed_verified_lane_relay_record(&state, &envelope);
        state.record_lane_relay(&envelope).expect("relay accepted");
        if state.latest_block_hash_fast().is_none() {
            let mut block_hashes = state.block_hashes.block();
            block_hashes.push_for_tests(HashOf::<BlockHeader>::from_untyped_unchecked(Hash::new(
                b"test-merge-parent",
            )));
            block_hashes.commit_for_tests();
        }

        (state, custody_id, asset_def_id, commit_keypairs)
    }

    fn account_asset_balance(
        state: &State,
        asset_def_id: &AssetDefinitionId,
        account_id: &AccountId,
    ) -> Quantity {
        state
            .view()
            .world()
            .assets()
            .get(&AssetId::of(asset_def_id.clone(), account_id.clone()))
            .expect("account asset exists")
            .0
            .clone()
    }

