    #[test]
    fn commit_merge_entry_burns_nexus_fee_receipts_once() {
        let (state, sponsor_id, asset_def_id, commit_keypairs) =
            setup_nexus_fee_merge_state(Quantity::from(10_u32), Quantity::from(3_u32), [0x42; 32]);
        let candidate = state
            .merge_entry_candidates_from_lane_relays()
            .into_iter()
            .next()
            .expect("merge candidate");
        let qc = merge_qc_for_candidate(&state, &candidate, &commit_keypairs, &[0]);
        let entry = merge_entry_from_candidate(candidate.clone(), qc);

        state
            .commit_merge_entry(entry.clone())
            .expect("merge settlement burns fee");
        assert_eq!(
            account_asset_balance(&state, &asset_def_id, &sponsor_id),
            Quantity::from(7_u32)
        );

        let err = state
            .commit_merge_entry(entry)
            .expect_err("replayed merge entry must be rejected");
        assert!(matches!(
            err,
            MergeLedgerCommitError::NonMonotonicEpoch { .. }
                | MergeLedgerCommitError::DuplicateNexusFeeReceipt(_)
        ));
        assert_eq!(
            account_asset_balance(&state, &asset_def_id, &sponsor_id),
            Quantity::from(7_u32)
        );

        state.settled_nexus_fee_receipts.write().clear();
        let duplicate_candidate = crate::merge::MergeLedgerCandidate {
            epoch_id: 2,
            ..candidate.clone()
        };
        let duplicate_qc =
            merge_qc_for_candidate(&state, &duplicate_candidate, &commit_keypairs, &[0]);
        let duplicate_entry = merge_entry_from_candidate(duplicate_candidate, duplicate_qc);
        let err = state
            .commit_merge_entry(duplicate_entry)
            .expect_err("higher-epoch replay must be rejected before a second burn");
        assert!(matches!(
            err,
            MergeLedgerCommitError::NonMonotonicLaneSnapshot { .. }
                | MergeLedgerCommitError::DuplicateNexusFeeReceipt(_)
        ));
        assert_eq!(
            account_asset_balance(&state, &asset_def_id, &sponsor_id),
            Quantity::from(7_u32)
        );
    }

    #[test]
    fn commit_merge_entry_rejects_tampered_canonical_settlement_hash() {
        let (state, sponsor_id, asset_def_id, commit_keypairs) =
            setup_nexus_fee_merge_state(Quantity::from(10_u32), Quantity::from(3_u32), [0x46; 32]);
        let mut candidate = state
            .merge_entry_candidates_from_lane_relays()
            .into_iter()
            .next()
            .expect("merge candidate");
        candidate
            .lane_snapshots
            .first_mut()
            .expect("candidate lane snapshot")
            .settlement_hash =
            HashOf::from_untyped_unchecked(Hash::new(b"tampered-settlement-hash"));
        let qc = merge_qc_for_candidate(&state, &candidate, &commit_keypairs, &[0]);

        let err = state
            .commit_merge_entry(merge_entry_from_candidate(candidate, qc))
            .expect_err("tampered canonical settlement hash must be rejected");
        assert!(matches!(
            err,
            MergeLedgerCommitError::SettlementCommitmentMismatch { .. }
        ));
        assert_eq!(
            account_asset_balance(&state, &asset_def_id, &sponsor_id),
            Quantity::from(10_u32),
            "rejected settlement must not burn the sponsor balance"
        );
        assert!(state.kura.merge_ledger_snapshot().is_empty());
        assert!(state.settled_nexus_fee_receipts.read().is_empty());
    }

